// time one of their functions is used, so signing in and taking orders do not wait for them. Every function declared in a
// chunk is registered below as a small stub that loads the chunk and then runs the real function. Once a chunk is loaded the
// real function replaces the stub, so later calls are direct. tools/check-chunks.js keeps this registry correct.
// ============================================================
