// Release number taken from this script's own ?v= parameter, so chunk URLs change with every release and can be cached for a year.
const APP_VERSION = (() => { try { return new URL(document.currentScript.src).searchParams.get('v') || ''; } catch (e) { return ''; } })();
// Shared state that more than one file uses (chunks may only declare functions and their own private variables).
let allSuppliers = [];

function lazyChunkUrl(name) { return `js/${name}.js${APP_VERSION ? '?v=' + APP_VERSION : ''}`; }
const lazyChunkLoads = {};
function loadChunk(name) {
  if (!lazyChunkLoads[name]) {
    lazyChunkLoads[name] = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = lazyChunkUrl(name);
      script.onload = () => resolve();
      script.onerror = () => { delete lazyChunkLoads[name]; script.remove(); reject(new Error('Could not load part of the app. Check the connection and try again.')); };
      document.head.appendChild(script);
    });
  }
  return lazyChunkLoads[name];
}
function installLazyStubs() {
  for (const [chunk, names] of Object.entries(LAZY_REGISTRY)) {
    for (const name of names) {
      const stub = function (...args) {
        const first = args[0];
        // A form submit must be cancelled right now; waiting for the chunk would let the browser submit the form natively.
        if (first && first.type === 'submit' && typeof first.preventDefault === 'function') first.preventDefault();
        const real = window[name];
        if (real !== stub) return real.apply(this, args); // chunk already loaded: direct, synchronous call
        return loadChunk(chunk).then(() => {
          const loaded = window[name];
          if (loaded === stub) throw new Error(`${name} is missing from the ${chunk} module`);
          return loaded.apply(this, args);
        }).catch(err => { if (typeof showToast === 'function') showToast(err.message, 'error'); else console.error(err); });
      };
      window[name] = stub;
    }
  }
}
installLazyStubs();

// Warm the browser cache with the chunks this user is likely to open, when the browser is idle. Skipped on data saver.
function prefetchLazyChunks(names) {
  const conn = navigator.connection;
  if (conn && conn.saveData) return;
  const run = () => names.forEach(n => {
    if (!LAZY_REGISTRY[n] || document.querySelector(`link[data-lazy-chunk="${n}"]`)) return;
    const link = document.createElement('link');
    link.rel = 'prefetch'; link.as = 'script'; link.href = lazyChunkUrl(n); link.dataset.lazyChunk = n;
    document.head.appendChild(link);
  });
  (window.requestIdleCallback || ((f) => setTimeout(f, 1500)))(run);
}
function prefetchChunksForRole(role) {
  if (role === 'ADMIN') return prefetchLazyChunks(['analytics', 'attendance', 'staff', 'expenses', 'suppliers', 'recipes', 'users', 'audit', 'telegram']);
  if (role === 'MANAGER') return prefetchLazyChunks(['analytics', 'attendance', 'audit', 'staff', 'expenses', 'suppliers', 'recipes', 'users']);
  prefetchLazyChunks(['attendance']);
}
// On a returning device the role is known before sign-in finishes, so the landing screen's chunk can start downloading immediately.
try { const saved = JSON.parse(localStorage.getItem('neram_user') || 'null'); if (saved && saved.role) prefetchChunksForRole(saved.role); else prefetchLazyChunks(['analytics']); } catch (e) { /* ignore */ }


