function renderMobileTableControls() {
  const pillText = document.getElementById('mobileActiveTableText');
  const pillIcon = document.getElementById('mobileActiveTableIcon');
  const pillBtn = document.getElementById('mobileActiveTablePill');
  const statusBadge = document.getElementById('mobileTableStatusBadge');
  const cartTableTag = document.getElementById('mobileCartTableTag');
  const cartTableTagName = document.getElementById('mobileCartTableTagName');
  const cartTableTagIcon = document.getElementById('mobileCartTableTagIcon');
  const ribbon = document.getElementById('mobileQuickTableRibbon');
  const activeCountEl = document.getElementById('mobileActiveOrdersBadgeCount');
  const btnAddTable = document.getElementById('btnMobileAddTable');
  const btnPickerAddTable = document.getElementById('btnPickerAddNewTable');

  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  if (btnAddTable) {
    if (isManagerOrAdmin) btnAddTable.classList.remove('hidden');
    else btnAddTable.classList.add('hidden');
  }
  if (btnPickerAddTable) {
    if (isManagerOrAdmin) btnPickerAddTable.classList.remove('hidden');
    else btnPickerAddTable.classList.add('hidden');
  }

  if (activeCountEl) {
    activeCountEl.textContent = activeOrders.length;
  }

  const isOutdoor = currentOrderLocation === 'OUTDOOR';
  const isTakeaway = currentOrderLocation === 'TAKEAWAY';
  const tableNo = (isOutdoor || isTakeaway) ? '' : (document.getElementById('cartTableNo')?.value?.trim() || '');
  const outdoorToken = isOutdoor ? (currentTableOrder?.outdoorToken || 'OUT') : '';
  const takeawayToken = isTakeaway ? (currentTableOrder?.takeawayToken || 'TAK') : '';

  // 1. Update Active Table Pill & Floating Cart Tag
  if (isTakeaway) {
    if (pillText) pillText.textContent = `Takeaway: ${takeawayToken}`;
    if (pillIcon) pillIcon.className = 'fa-solid fa-bag-shopping text-[11px] text-amber-400';
    if (pillBtn) pillBtn.className = 'flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-amber-500/20 border border-amber-500/40 text-amber-300 font-bold text-xs shrink-0 active:scale-95 transition shadow-sm';
    if (cartTableTagName) cartTableTagName.textContent = `Takeaway: ${takeawayToken}`;
    if (cartTableTagIcon) cartTableTagIcon.className = 'fa-solid fa-bag-shopping text-[9px] text-amber-400';
    if (cartTableTag) cartTableTag.className = 'px-2 py-0.5 rounded-md text-[10px] font-black bg-amber-500/20 text-amber-300 border border-amber-500/30 flex items-center gap-1 hover:bg-amber-500/30 active:scale-95 transition cursor-pointer';

    if (statusBadge) {
      statusBadge.classList.remove('hidden');
      if (currentTableOrder) {
        statusBadge.textContent = `₹${currentTableOrder.netAmount.toFixed(0)}`;
        statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-400 border border-amber-500/30 truncate';
      } else {
        statusBadge.textContent = 'Takeaway Active';
        statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/10 text-amber-300 border border-amber-500/20 truncate';
      }
    }
  } else if (isOutdoor) {
    if (pillText) pillText.textContent = `Outdoor: ${outdoorToken}`;
    if (pillIcon) pillIcon.className = 'fa-solid fa-tree text-[11px] text-emerald-400';
    if (pillBtn) pillBtn.className = 'flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-emerald-500/20 border border-emerald-500/40 text-emerald-300 font-bold text-xs shrink-0 active:scale-95 transition shadow-sm';
    if (cartTableTagName) cartTableTagName.textContent = `Outdoor: ${outdoorToken}`;
    if (cartTableTagIcon) cartTableTagIcon.className = 'fa-solid fa-tree text-[9px] text-emerald-400';
    if (cartTableTag) cartTableTag.className = 'px-2 py-0.5 rounded-md text-[10px] font-black bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 flex items-center gap-1 hover:bg-emerald-500/30 active:scale-95 transition cursor-pointer';

    if (statusBadge) {
      statusBadge.classList.remove('hidden');
      if (currentTableOrder) {
        statusBadge.textContent = `₹${currentTableOrder.netAmount.toFixed(0)}`;
        statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 truncate';
      } else {
        statusBadge.textContent = 'Outdoor Active';
        statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-300 border border-emerald-500/20 truncate';
      }
    }
  } else if (tableNo) {
    if (pillText) pillText.textContent = `Table: ${tableNo}`;
    if (pillIcon) pillIcon.className = 'fa-solid fa-chair text-[11px] text-amber-400';
    if (pillBtn) pillBtn.className = 'flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-amber-500/20 border border-amber-500/40 text-amber-300 font-bold text-xs shrink-0 active:scale-95 transition shadow-sm';
    if (cartTableTagName) cartTableTagName.textContent = tableNo;
    if (cartTableTagIcon) cartTableTagIcon.className = 'fa-solid fa-chair text-[9px] text-amber-400';
    if (cartTableTag) cartTableTag.className = 'px-2 py-0.5 rounded-md text-[10px] font-black bg-amber-500/20 text-amber-300 border border-amber-500/30 flex items-center gap-1 hover:bg-amber-500/30 active:scale-95 transition cursor-pointer';

    if (statusBadge) {
      statusBadge.classList.remove('hidden');
      const order = currentTableOrder || activeOrders.find(o => o.tableNumber === tableNo);
      if (order) {
        if (order.status === 'KOT_REQUESTED') {
          statusBadge.textContent = 'KOT Req';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-orange-500/20 text-orange-400 border border-orange-500/30 animate-pulse';
        } else if (order.status === 'KOT_PRINTED') {
          statusBadge.textContent = 'Preparing';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-cyan-500/20 text-cyan-400 border border-cyan-500/30';
        } else if (order.status === 'BILL_REQUESTED') {
          statusBadge.textContent = 'Bill Req';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-purple-500/20 text-purple-400 border border-purple-500/30 animate-pulse';
        } else if (order.status === 'BILL_PRINTED') {
          statusBadge.textContent = 'Pending Pay';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/40 animate-pulse';
        } else {
          statusBadge.textContent = `₹${order.netAmount.toFixed(0)}`;
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30';
        }
      } else {
        statusBadge.textContent = 'Vacant';
        statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-gray-800 text-gray-400 border border-gray-700/60 truncate';
      }
    }
  } else {
    if (pillText) pillText.textContent = 'Select Table';
    if (pillIcon) pillIcon.className = 'fa-solid fa-chair text-[11px] text-amber-400';
    if (pillBtn) pillBtn.className = 'flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-amber-500/10 border border-dashed border-amber-500/60 text-amber-400 font-bold text-xs shrink-0 active:scale-95 transition shadow-sm animate-pulse';
    if (cartTableTagName) cartTableTagName.textContent = 'Select Table';
    if (cartTableTagIcon) cartTableTagIcon.className = 'fa-solid fa-chair text-[9px] text-amber-400';
    if (cartTableTag) cartTableTag.className = 'px-2 py-0.5 rounded-md text-[10px] font-black bg-amber-500/10 text-amber-400 border border-dashed border-amber-500/50 flex items-center gap-1 hover:bg-amber-500/20 active:scale-95 transition cursor-pointer animate-pulse';
    if (statusBadge) statusBadge.classList.add('hidden');
  }

  // Update floating cart button label: "View Order" if table has data or cart has items, else "Take Order"
  const floatingBtnText = document.getElementById('mobileFloatingCartBtnText');
  const floatingBtnIcon = document.getElementById('mobileFloatingCartBtnIcon');
  const hasOrderData = (cart && cart.length > 0) ||
    (currentTableOrder && currentTableOrder.items && currentTableOrder.items.length > 0);
  if (floatingBtnText && floatingBtnIcon) {
    if (hasOrderData) {
      floatingBtnText.textContent = 'View Order';
      floatingBtnIcon.className = 'fa-solid fa-chevron-up text-[10px]';
    } else {
      floatingBtnText.textContent = 'Take Order';
      floatingBtnIcon.className = 'fa-solid fa-plus text-[10px]';
    }
  }

  // 2. Render Horizontal Ribbon Chips
  if (ribbon) {
    const tables = getSavedTables();
    let ribbonHtml = '';

    if (isManagerOrAdmin) {
      ribbonHtml += `
        <button type="button" onclick="promptAddNewTable()"
          class="px-2 py-1 rounded-lg text-[11px] font-bold bg-gray-900 hover:bg-gray-800 text-amber-400 border border-amber-500/25 flex items-center gap-1 shrink-0 active:scale-95 transition">
          <i class="fa-solid fa-plus text-[9px]"></i> Table
        </button>
      `;
    }

    ribbonHtml += tables.map(t => {
      const order = activeOrders.find(o => o.tableNumber === t);
      const isSelected = (!isOutdoor && !isTakeaway && t === tableNo);

      let statusBadge = '';
      let borderClass = 'border-gray-800 bg-gray-900/70 text-gray-300';

      if (order) {
        if (order.status === 'KOT_REQUESTED') {
          borderClass = 'border-orange-500/50 bg-orange-500/10 text-orange-400';
          statusBadge = `<span class="text-[8px] font-bold px-1 rounded bg-orange-500/20 ml-1">KOT</span>`;
        } else if (order.status === 'KOT_PRINTED') {
          borderClass = 'border-cyan-500/50 bg-cyan-500/10 text-cyan-400';
          statusBadge = `<span class="text-[8px] font-bold px-1 rounded bg-cyan-500/20 ml-1">Prep</span>`;
        } else if (order.status === 'BILL_REQUESTED') {
          borderClass = 'border-purple-500/50 bg-purple-500/10 text-purple-400';
          statusBadge = `<span class="text-[8px] font-bold px-1 rounded bg-purple-500/20 ml-1">Bill</span>`;
        } else if (order.status === 'BILL_PRINTED') {
          borderClass = 'border-amber-500/60 bg-amber-500/10 text-amber-300';
          statusBadge = `<span class="text-[8px] font-bold px-1 rounded bg-amber-500/20 ml-1">Pay</span>`;
        } else {
          borderClass = 'border-emerald-500/50 bg-emerald-500/10 text-emerald-400';
          statusBadge = `<span class="text-[8px] font-bold px-1 rounded bg-emerald-500/20 ml-1">₹${order.netAmount.toFixed(0)}</span>`;
        }
      }

      const activeStyle = isSelected ? 'ring-2 ring-amber-400 border-amber-400 bg-amber-500/20 text-white font-black' : '';

      return `
        <button type="button" onclick="selectPickerTable('${t}')"
          class="px-2.5 py-1 rounded-lg text-[11px] font-semibold flex items-center border transition shrink-0 active:scale-95 ${borderClass} ${activeStyle}">
          <i class="fa-solid fa-chair text-[9px] mr-1 ${isSelected ? 'text-amber-400' : 'text-gray-400'}"></i>
          <span>${escapeHtml(t)}</span>
          ${statusBadge}
        </button>
      `;
    }).join('');

    // Outdoor Chip
    const outdoorActiveStyle = isOutdoor ? 'ring-2 ring-emerald-400 border-emerald-400 bg-emerald-500/20 text-emerald-300 font-black' : 'border-gray-800 bg-gray-900/70 text-gray-300';
    ribbonHtml += `
      <button type="button" onclick="openMobileTablePicker('Choose outdoor order or create new'); setPickerMode('OUTDOOR');"
        class="px-2.5 py-1 rounded-lg text-[11px] font-semibold flex items-center border transition shrink-0 active:scale-95 ${outdoorActiveStyle}">
        <i class="fa-solid fa-tree text-[9px] mr-1 text-emerald-400"></i>
        <span>Outdoor</span>
      </button>
    `;

    // Takeaway Chip
    const takeawayActiveStyle = isTakeaway ? 'ring-2 ring-amber-400 border-amber-400 bg-amber-500/20 text-amber-300 font-black' : 'border-gray-800 bg-gray-900/70 text-gray-300';
    ribbonHtml += `
      <button type="button" onclick="openMobileTablePicker('Choose takeaway order or create new'); setPickerMode('TAKEAWAY');"
        class="px-2.5 py-1 rounded-lg text-[11px] font-semibold flex items-center border transition shrink-0 active:scale-95 ${takeawayActiveStyle}">
        <i class="fa-solid fa-bag-shopping text-[9px] mr-1 text-amber-400"></i>
        <span>Takeaway</span>
      </button>
    `;

    ribbon.innerHTML = ribbonHtml;
  }
}

function updateOrderActionButtonsState() {
  const btnKot = document.getElementById('btnSendToKitchen');
  const btnRequestBill = document.getElementById('btnRequestBill');
  const btnPayPrint = document.getElementById('btnPayAndPrint');
  const btnSaveOrder = document.getElementById('btnSaveTableOrder');

  const isOutdoor = currentOrderLocation === 'OUTDOOR';
  const tableNo = document.getElementById('cartTableNo')?.value?.trim();
  const customerName = (document.getElementById('cartCustomer')?.value || '').trim();
  const isLocReady = isOrderLocationReady();
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');

  const cartHasItems = Boolean(cart && cart.length > 0);
  const isSavedOrder = Boolean(currentTableOrder && currentTableOrder.id);
  const hasChanges = hasOrderChanges();
  isCartDirty = hasChanges;

  // 0. SAVE ORDER BUTTON
  if (btnSaveOrder) {
    if (!isLocReady || !cartHasItems) {
      btnSaveOrder.disabled = true;
      btnSaveOrder.classList.add('opacity-40', 'cursor-not-allowed');
      btnSaveOrder.classList.remove('hover:bg-blue-500');
      btnSaveOrder.title = !isLocReady
        ? (isOutdoor ? 'Enter customer name first to save outdoor order' : 'Select a table first to save order')
        : 'Add dishes to cart before saving order';
    } else if (isSavingOrder) {
      btnSaveOrder.disabled = true;
      btnSaveOrder.classList.add('opacity-40', 'cursor-not-allowed');
      btnSaveOrder.classList.remove('hover:bg-blue-500');
      btnSaveOrder.title = 'Saving order...';
    } else if (isSendingKot) {
      btnSaveOrder.disabled = true;
      btnSaveOrder.classList.add('opacity-40', 'cursor-not-allowed');
      btnSaveOrder.classList.remove('hover:bg-blue-500');
      btnSaveOrder.title = 'Sending to kitchen...';
    } else if (!hasChanges) {
      // Order is already saved, no new changes
      btnSaveOrder.disabled = true;
      btnSaveOrder.classList.add('opacity-40', 'cursor-not-allowed');
      btnSaveOrder.classList.remove('hover:bg-blue-500');
      btnSaveOrder.title = 'Order is already saved. Add or modify dishes to enable saving.';
    } else {
      // New order or order has unsaved edits / updates
      btnSaveOrder.disabled = false;
      btnSaveOrder.classList.remove('opacity-40', 'cursor-not-allowed');
      btnSaveOrder.classList.add('hover:bg-blue-500');
      btnSaveOrder.title = isSavedOrder
        ? (isOutdoor ? 'Save updated dishes to outdoor order' : 'Save updated dishes to table order')
        : (isOutdoor ? 'Save new outdoor order' : 'Save new table order');
    }
  }

  // 1. SEND TO KITCHEN BUTTON
  if (btnKot) {
    if (!isLocReady || !cartHasItems) {
      btnKot.disabled = true;
      btnKot.classList.add('opacity-40', 'cursor-not-allowed');
      btnKot.classList.remove('hover:bg-orange-500');
      btnKot.title = currentOrderLocation === 'TAKEAWAY'
        ? 'Add dishes to cart to send to kitchen'
        : (isOutdoor ? 'Enter customer name and add dishes to enable' : 'Select a table and add dishes to enable');
    } else if (isSavingOrder) {
      btnKot.disabled = true;
      btnKot.classList.add('opacity-40', 'cursor-not-allowed');
      btnKot.classList.remove('hover:bg-orange-500');
      btnKot.title = 'Saving order in progress...';
    } else if (isSendingKot) {
      btnKot.disabled = true;
      btnKot.classList.add('opacity-40', 'cursor-not-allowed');
      btnKot.classList.remove('hover:bg-orange-500');
      btnKot.title = 'Sending to kitchen...';
    } else if (!isSavedOrder) {
      // Fresh new order - must be saved before sending to kitchen
      btnKot.disabled = true;
      btnKot.classList.add('opacity-40', 'cursor-not-allowed');
      btnKot.classList.remove('hover:bg-orange-500');
      btnKot.title = 'Click SAVE ORDER first before sending dishes to kitchen';
    } else if (hasChanges) {
      // Order has unsaved changes - must save changes first
      btnKot.disabled = true;
      btnKot.classList.add('opacity-40', 'cursor-not-allowed');
      btnKot.classList.remove('hover:bg-orange-500');
      btnKot.title = 'Click SAVE ORDER first before sending new dishes to kitchen';
    } else if (currentTableOrder.status === 'KOT_REQUESTED') {
      btnKot.disabled = true;
      btnKot.classList.add('opacity-40', 'cursor-not-allowed');
      btnKot.classList.remove('hover:bg-orange-500');
      btnKot.title = 'Kitchen ticket already requested';
    } else if (currentTableOrder.status === 'BILL_REQUESTED') {
      btnKot.disabled = true;
      btnKot.classList.add('opacity-40', 'cursor-not-allowed');
      btnKot.classList.remove('hover:bg-orange-500');
      btnKot.title = isOutdoor ? 'Final bill requested for outdoor order' : (currentOrderLocation === 'TAKEAWAY' ? 'Final bill requested for takeaway order' : 'Final bill requested for table');
    } else if (currentTableOrder.status === 'BILL_PRINTED') {
      btnKot.disabled = true;
      btnKot.classList.add('opacity-40', 'cursor-not-allowed');
      btnKot.classList.remove('hover:bg-orange-500');
      btnKot.title = 'Bill already printed. Awaiting payment.';
    } else if (currentTableOrder.status === 'PAID' || currentTableOrder.status === 'CANCELLED') {
      btnKot.disabled = true;
      btnKot.classList.add('opacity-40', 'cursor-not-allowed');
      btnKot.classList.remove('hover:bg-orange-500');
      btnKot.title = 'Order is completed or cancelled';
    } else {
      // Saved order with no unsaved changes: check for unprinted dishes or incremental changes
      const hasUnprinted = (currentTableOrder.items || []).some(it => {
        const printed = it.printedQuantity || 0;
        return (it.quantity || 0) > printed;
      });
      const hasKotChanges = Boolean(currentTableOrder.kotLastChanges && currentTableOrder.kotLastChanges.trim());

      if (!hasUnprinted && !hasKotChanges) {
        btnKot.disabled = true;
        btnKot.classList.add('opacity-40', 'cursor-not-allowed');
        btnKot.classList.remove('hover:bg-orange-500');
        btnKot.title = 'All items already sent to kitchen. Add or modify dishes and click SAVE ORDER to send more.';
      } else {
        btnKot.disabled = false;
        btnKot.classList.remove('opacity-40', 'cursor-not-allowed');
        btnKot.classList.add('hover:bg-orange-500');
        btnKot.title = 'Send Order Ticket to Kitchen';
      }
    }
  }

  // 3. REQUEST BILL BUTTON
  // Condition: Only after order is sent to kitchen, request bill should enable!
  if (btnRequestBill) {
    if (!isLocReady || cart.length === 0 || !currentTableOrder) {
      btnRequestBill.disabled = true;
      btnRequestBill.classList.add('opacity-40', 'cursor-not-allowed');
      btnRequestBill.classList.remove('hover:bg-purple-500');
      btnRequestBill.title = 'Save and send order to kitchen first';
    } else if (currentTableOrder.status === 'BILL_REQUESTED') {
      btnRequestBill.disabled = true;
      btnRequestBill.classList.add('opacity-40', 'cursor-not-allowed');
      btnRequestBill.classList.remove('hover:bg-purple-500');
      btnRequestBill.title = 'Bill has already been requested from manager';
    } else if (currentTableOrder.status === 'KOT_REQUESTED') {
      btnRequestBill.disabled = true;
      btnRequestBill.classList.add('opacity-40', 'cursor-not-allowed');
      btnRequestBill.classList.remove('hover:bg-purple-500');
      btnRequestBill.title = 'Kitchen ticket requested. Order must be sent to kitchen before bill can be requested.';
    } else if (currentTableOrder.status !== 'KOT_PRINTED' || !currentTableOrder.kotPrintedAt) {
      btnRequestBill.disabled = true;
      btnRequestBill.classList.add('opacity-40', 'cursor-not-allowed');
      btnRequestBill.classList.remove('hover:bg-purple-500');
      btnRequestBill.title = 'Order must be sent to kitchen before requesting bill.';
    } else {
      const hasUnprinted = (currentTableOrder.items || []).some(it => {
        const printed = it.printedQuantity || 0;
        return (it.quantity || 0) > printed;
      });
      if (hasUnprinted || isCartDirty) {
        btnRequestBill.disabled = true;
        btnRequestBill.classList.add('opacity-40', 'cursor-not-allowed');
        btnRequestBill.classList.remove('hover:bg-purple-500');
        btnRequestBill.title = 'New dishes added to order. Save and send to kitchen first.';
      } else {
        // Ready! Sent to kitchen and printed by manager!
        btnRequestBill.disabled = false;
        btnRequestBill.classList.remove('opacity-40', 'cursor-not-allowed');
        btnRequestBill.classList.add('hover:bg-purple-500');
        btnRequestBill.title = 'Customer is ready for final bill';
      }
    }
  }

  // 4. PAY & PRINT BILL BUTTON (Admin / Manager Only)
  // Condition: Only after request bill is clicked, admin or manager can click on PAY & PRINT BILL!
  if (btnPayPrint) {
    if (!isManagerOrAdmin) {
      btnPayPrint.classList.add('hidden');
    } else {
      btnPayPrint.classList.remove('hidden');
      if (!isLocReady || cart.length === 0 || !currentTableOrder) {
        btnPayPrint.disabled = true;
        btnPayPrint.classList.add('opacity-40', 'cursor-not-allowed');
        btnPayPrint.classList.remove('hover:from-amber-400', 'hover:to-amber-500', 'ring-2', 'ring-amber-400');
        btnPayPrint.title = isOutdoor ? 'Select an outdoor order with a requested bill' : 'Select a table with a requested bill';
      } else if (currentTableOrder.status !== 'BILL_REQUESTED') {
        btnPayPrint.disabled = true;
        btnPayPrint.classList.add('opacity-40', 'cursor-not-allowed');
        btnPayPrint.classList.remove('hover:from-amber-400', 'hover:to-amber-500', 'ring-2', 'ring-amber-400');
        if (currentTableOrder.status === 'BILL_PRINTED') {
          btnPayPrint.title = 'Bill already printed. Awaiting payment confirmation.';
        } else if (currentTableOrder.status === 'KOT_PRINTED') {
          btnPayPrint.title = 'Request bill must be clicked first before print bill is enabled';
        } else if (currentTableOrder.status === 'KOT_REQUESTED') {
          btnPayPrint.title = 'KOT must be printed and bill must be requested first';
        } else {
          btnPayPrint.title = 'Send to kitchen, print KOT, and request bill first';
        }
      } else {
        // Status is BILL_REQUESTED: ENABLED!
        btnPayPrint.disabled = false;
        btnPayPrint.classList.remove('opacity-40', 'cursor-not-allowed');
        btnPayPrint.classList.add('hover:from-amber-400', 'hover:to-amber-500', 'ring-2', 'ring-amber-400');
        btnPayPrint.title = 'Customer bill requested! Click to print bill';
      }
    }
  }
}

function updateKotButtonState() {
  updateOrderActionButtonsState();
}

// ============================================================
// THEME MANAGEMENT (Dark / Light Mode)
// ============================================================
function initTheme() {
  const savedTheme = localStorage.getItem('neram_theme') || 'dark';
  applyTheme(savedTheme, false);
}

function toggleTheme() {
  const isLight = document.body.classList.contains('theme-light');
  const nextTheme = isLight ? 'dark' : 'light';
  localStorage.setItem('neram_theme', nextTheme);
  applyTheme(nextTheme, true);
  if (typeof showToast === 'function') {
    showToast(nextTheme === 'light' ? 'Switched to Light Theme' : 'Switched to Dark Theme', 'info');
  }
}

function applyTheme(theme, animate = true) {
  const isLight = theme === 'light';
  if (isLight) {
    document.body.classList.add('theme-light');
  } else {
    document.body.classList.remove('theme-light');
  }

  // Update Header Theme Toggle Icon
  const headerIcon = document.getElementById('themeToggleIcon');
  if (headerIcon) {
    headerIcon.className = `fa-solid ${isLight ? 'fa-sun text-amber-500' : 'fa-moon text-amber-400'} text-xs sm:text-sm transition-transform duration-300`;
  }

  // Update Drawer Theme Toggle Icon and Text
  const drawerIcon = document.getElementById('drawerThemeToggleIcon');
  const drawerLabel = document.getElementById('drawerThemeToggleLabel');
  if (drawerIcon) {
    drawerIcon.className = `fa-solid ${isLight ? 'fa-sun text-amber-500' : 'fa-moon text-amber-400'} text-xs`;
  }
  if (drawerLabel) {
    drawerLabel.textContent = isLight ? 'Light Theme' : 'Dark Theme';
  }

  // Update meta theme-color for mobile status bar and browser bars
  const metaThemeColor = document.querySelector('meta[name="theme-color"]');
  if (metaThemeColor) {
    metaThemeColor.setAttribute('content', isLight ? '#f8fafc' : '#090d16');
  }
}

// ============================================================
// PROGRESSIVE WEB APP (PWA) SUPPORT
// ============================================================
let deferredPwaPrompt = null;

function initPwa() {
  // Register Service Worker
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('/sw.js', { scope: '/' })
        .then(reg => {
          console.log('[NERAM PWA] Service worker registered, scope:', reg.scope);
          reg.addEventListener('updatefound', () => {
            const newWorker = reg.installing;
            if (newWorker) {
              newWorker.addEventListener('statechange', () => {
                if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                  console.log('[NERAM PWA] New update available');
                }
              });
            }
          });
        })
        .catch(err => {
          console.warn('[NERAM PWA] Service worker registration failed:', err);
        });
    });
  }

  // Capture install prompt for Chrome / Android / Desktop
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPwaPrompt = e;
    const btn = document.getElementById('btnPwaInstall');
    if (btn) btn.classList.remove('hidden');
    const directSec = document.getElementById('pwaDirectInstallSection');
    if (directSec) directSec.classList.remove('hidden');
  });

  window.addEventListener('appinstalled', () => {
    deferredPwaPrompt = null;
    const btn = document.getElementById('btnPwaInstall');
    if (btn) btn.classList.add('hidden');
    const directSec = document.getElementById('pwaDirectInstallSection');
    if (directSec) directSec.classList.add('hidden');
    closePwaInstallModal();
    if (typeof showToast === 'function') {
      showToast('NERAM POS App Installed successfully!', 'success');
    }
  });

  // Check if running as standalone PWA
  const isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
  if (isStandalone) {
    const btn = document.getElementById('btnPwaInstall');
    if (btn) btn.classList.add('hidden');
    const drawerPwaBtn = document.getElementById('drawerPwaInstallBtn');
    if (drawerPwaBtn) drawerPwaBtn.classList.add('hidden');
  }
}

function handlePwaInstallClick() {
  const modal = document.getElementById('pwaInstallModal');
  if (modal) {
    const directSec = document.getElementById('pwaDirectInstallSection');
    if (directSec) {
      if (deferredPwaPrompt) {
        directSec.classList.remove('hidden');
      } else {
        directSec.classList.add('hidden');
      }
    }

    // Detect device type to highlight relevant guide
    const isIos = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
    const iosSec = document.getElementById('pwaIosGuideSection');
    const androidSec = document.getElementById('pwaAndroidGuideSection');
    if (isIos) {
      if (iosSec) iosSec.classList.remove('hidden');
      if (androidSec) androidSec.classList.add('hidden');
    } else {
      if (iosSec) iosSec.classList.add('hidden');
      if (androidSec) androidSec.classList.remove('hidden');
    }

    modal.classList.remove('hidden');
  }
}

async function triggerNativeInstallPrompt() {
  if (deferredPwaPrompt) {
    deferredPwaPrompt.prompt();
    const { outcome } = await deferredPwaPrompt.userChoice;
    console.log('[NERAM PWA] User prompt outcome:', outcome);
    deferredPwaPrompt = null;
    closePwaInstallModal();
  } else {
    closePwaInstallModal();
    if (typeof showToast === 'function') {
      showToast('Follow browser instructions to install the app', 'info');
    }
  }
}

function closePwaInstallModal() {
  const modal = document.getElementById('pwaInstallModal');
  if (modal) modal.classList.add('hidden');
}

// ============================================================
// TAB NAVIGATION & REFRESH PERSISTENCE HELPERS
// ============================================================
function isTabPermitted(tabId) {
  if (!currentUser) return false;
  const role = currentUser.role || '';
  const canTakeOrders = currentUser.canTakeOrders !== false;
  const canManageInventory = currentUser.canManageInventory === true;
  switch (tabId) {
    case 'tab-pos': return canTakeOrders;
    case 'tab-bills': return ['ADMIN', 'MANAGER'].includes(role);
    case 'tab-menu': return ['ADMIN', 'MANAGER'].includes(role);
    case 'tab-inventory': return canManageInventory;
    case 'tab-staff': return ['ADMIN', 'MANAGER'].includes(role);
    case 'tab-expenses': return ['ADMIN', 'MANAGER'].includes(role);
    case 'tab-analytics': return ['ADMIN', 'MANAGER'].includes(role);
    case 'tab-attendance': return true;
    case 'tab-audit': return role === 'ADMIN';
    case 'tab-telegram': return role === 'ADMIN';
    case 'tab-users': return ['ADMIN', 'MANAGER'].includes(role);
    case 'tab-suppliers': return ['ADMIN', 'MANAGER'].includes(role);
    case 'tab-gst': return ['ADMIN', 'MANAGER'].includes(role);
    default: return false;
  }
}

function normalizeTabId(raw) {
  if (!raw) return null;
  let str = String(raw).trim();
  if (str.startsWith('#')) str = str.substring(1);
  if (!str) return null;
  if (!str.startsWith('tab-')) str = 'tab-' + str;
  return str;
}

function setupHashRouting() {
  window.addEventListener('hashchange', () => {
    if (!currentUser) return;
    const target = normalizeTabId(window.location.hash);
    if (target && target !== activeTab && isTabPermitted(target)) {
      switchTab(target, false);
    }
  });
}

// ============================================================
// INITIALIZATION
// ============================================================
function initApp() {
  try {
    initTheme();
  } catch (err) {
    console.warn('[Init] Theme init error:', err);
  }
  try {
    initPwa();
  } catch (err) {
    console.warn('[Init] PWA init error:', err);
  }
  try {
    initClock();
  } catch (err) {
    console.warn('[Init] Clock init error:', err);
  }
  try {
    setupEventListeners();
  } catch (err) {
    console.warn('[Init] Event listeners error:', err);
  }
  try {
    loadTableOptions();
  } catch (err) {
    console.warn('[Init] Table options error:', err);
  }
  try {
    checkAuth();
  } catch (err) {
    console.error('[Init] Auth check error:', err);
    showLoginModal();
  }
  try {
    setupHashRouting();
  } catch (err) {
    console.warn('[Init] Hash routing error:', err);
  }
}

// Immediate watchdog in JS: never let splash screen hang longer than 2.5s
setTimeout(() => {
  dismissSplash();
  if (!currentUser) {
    const loginM = document.getElementById('loginModal');
    if (loginM && loginM.classList.contains('hidden')) {
      loginM.classList.remove('hidden');
    }
  }
}, 2500);

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  // DOM is already ready (interactive or complete)
  initApp();
}

function initClock() {
  const updateClock = () => {
    const el = document.getElementById('liveClock');
    if (el) {
      const now = new Date();
      el.textContent = now.toLocaleDateString('en-IN', {
        weekday: 'short', day: 'numeric', month: 'short', year: 'numeric'
      }) + ' ' + now.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    }
  };
  updateClock();
  setInterval(updateClock, 1000);
}

function checkAuth() {
  let stored = null;
  try {
    stored = localStorage.getItem('neram_user');
  } catch (e) {
    console.warn('[Auth] localStorage access restricted:', e);
  }
  if (stored) {
    try {
      currentUser = JSON.parse(stored);
      if (currentUser && (currentUser.token || currentUser.username || currentUser.role)) {
        applyUserSession();
        return;
      }
    } catch (e) {
      console.warn('[Auth] Stored session invalid JSON:', e);
    }
  }
  showLoginModal();
}

function dismissSplash() {
  if (window.__splashWatchdog) {
    clearTimeout(window.__splashWatchdog);
    window.__splashWatchdog = null;
  }
  const splash = document.getElementById('splashScreen');
  if (!splash) return;
  // Already dismissed
  if (splash.style.display === 'none' || splash.classList.contains('splash-dismissed')) return;
  splash.style.pointerEvents = 'none';
  splash.style.opacity = '0';
  splash.classList.add('splash-dismissed');
  setTimeout(() => {
    splash.style.display = 'none';
  }, 350);
}

function applyUserSession() {
  dismissSplash();
  document.getElementById('loginModal').classList.add('hidden');

  if (currentUser && currentUser.mustChangePassword === true) {
    openChangePasswordModal(true);
    return;
  }

  document.getElementById('headerUserName').textContent = currentUser.employeeName || currentUser.username;
  document.getElementById('headerUserRole').textContent = currentUser.role;
  const drawerUserName = document.getElementById('mobileDrawerUserName');
  const drawerUserRole = document.getElementById('mobileDrawerUserRole');
  if (drawerUserName) drawerUserName.textContent = currentUser.employeeName || currentUser.username;
  if (drawerUserRole) drawerUserRole.textContent = currentUser.role;

  buildNavigationTabs();

  // Role-based visibility for table management
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  const btnAddTableTop = document.getElementById('btnAddTableTop');
  const btnManageTablesTop = document.getElementById('btnManageTablesTop');
  const btnAddTableCart = document.getElementById('btnAddTableCart');
  const btnDeleteTableCart = document.getElementById('btnDeleteTableCart');

  if (btnAddTableTop) {
    if (isManagerOrAdmin) btnAddTableTop.classList.remove('hidden');
    else btnAddTableTop.classList.add('hidden');
  }
  if (btnManageTablesTop) {
    if (isManagerOrAdmin) btnManageTablesTop.classList.remove('hidden');
    else btnManageTablesTop.classList.add('hidden');
  }
  if (btnAddTableCart) {
    if (isManagerOrAdmin) btnAddTableCart.classList.remove('hidden');
    else btnAddTableCart.classList.add('hidden');
  }
  if (btnDeleteTableCart) {
    if (isManagerOrAdmin && document.getElementById('cartTableNo')?.value) {
      btnDeleteTableCart.classList.remove('hidden');
    } else {
      btnDeleteTableCart.classList.add('hidden');
    }
  }

  // Role-based visibility for Discount and GST controls in POS Cart (Manager & Admin only)
  const cartDiscountWrapper = document.getElementById('cartDiscountWrapper');
  const cartGstWrapper = document.getElementById('cartGstWrapper');
  const cartStaffTaxWrapper = document.getElementById('cartStaffTaxWrapper');
  const cartStaffDiscountWrapper = document.getElementById('cartStaffDiscountWrapper');
  const cartDiscountPct = document.getElementById('cartDiscountPct');
  const cartGstSelect = document.getElementById('cartGstSelect');
  if (!isManagerOrAdmin) {
    if (cartDiscountWrapper) cartDiscountWrapper.classList.add('hidden');
    if (cartGstWrapper) cartGstWrapper.classList.add('hidden');
    if (cartStaffTaxWrapper) cartStaffTaxWrapper.classList.remove('hidden');
    if (cartStaffDiscountWrapper) cartStaffDiscountWrapper.classList.add('hidden');
    if (cartDiscountPct) {
      cartDiscountPct.disabled = true;
      cartDiscountPct.value = 0;
    }
    if (cartGstSelect) cartGstSelect.disabled = true;
  } else {
    if (cartDiscountWrapper) cartDiscountWrapper.classList.remove('hidden');
    if (cartGstWrapper) cartGstWrapper.classList.remove('hidden');
    if (cartStaffTaxWrapper) cartStaffTaxWrapper.classList.add('hidden');
    if (cartStaffDiscountWrapper) cartStaffDiscountWrapper.classList.add('hidden');
    if (cartDiscountPct) cartDiscountPct.disabled = false;
    if (cartGstSelect) cartGstSelect.disabled = false;
  }

  // Role-based visibility for thermal printer settings (Only Manager and Admin)
  const headerPrinterStatusBtn = document.getElementById('headerPrinterStatusBtn');
  const headerMobilePrinterBtn = document.getElementById('headerMobilePrinterBtn');
  if (headerPrinterStatusBtn) {
    if (isManagerOrAdmin) headerPrinterStatusBtn.classList.remove('hidden');
    else headerPrinterStatusBtn.classList.add('hidden');
  }
  if (headerMobilePrinterBtn) {
    if (isManagerOrAdmin) headerMobilePrinterBtn.classList.remove('hidden');
    else headerMobilePrinterBtn.classList.add('hidden');
  }

  // Role-based visibility for cashier shift (Manager & Admin only; employees don't need shifts)
  const headerShiftStatusBtn = document.getElementById('headerShiftStatusBtn');
  const headerMobileShiftBtn = document.getElementById('headerMobileShiftBtn');
  if (headerShiftStatusBtn) {
    if (isManagerOrAdmin) headerShiftStatusBtn.classList.remove('hidden');
    else headerShiftStatusBtn.classList.add('hidden');
  }
  if (headerMobileShiftBtn) {
    if (isManagerOrAdmin) headerMobileShiftBtn.classList.remove('hidden');
    else headerMobileShiftBtn.classList.add('hidden');
  }

  // Role-based visibility for notifications center (Manager & Admin only)
  const headerNotificationsBtn = document.getElementById('headerNotificationsBtn');
  if (headerNotificationsBtn) {
    if (isManagerOrAdmin) headerNotificationsBtn.classList.remove('hidden');
    else headerNotificationsBtn.classList.add('hidden');
  }

  fetchDiningTables();
  if (isManagerOrAdmin) {
    loadPrinterConfig();
    checkPrinterConnectionStatus(false, true);
  }
  loadGstConfig();
  if (isManagerOrAdmin) {
    updateShiftHeaderIndicator();
    // Event-driven: one SSE connection signals changes; every (re)connect also performs the initial/recovery fetch.
    startNotificationStream();
  }

  // Load public menu status if admin or manager
  if (['ADMIN', 'MANAGER'].includes(currentUser.role)) {
    loadPublicMenuStatus();
  }

  // Restore preserved tab on refresh or navigate to role default
  const hashCandidate = normalizeTabId(window.location.hash);
  const savedCandidate = normalizeTabId(localStorage.getItem('neram_active_tab'));
  let defaultTab = 'tab-attendance';
  if (['ADMIN', 'MANAGER'].includes(currentUser.role)) {
    defaultTab = 'tab-analytics';
  } else if (currentUser.canTakeOrders !== false) {
    defaultTab = 'tab-pos';
  } else if (currentUser.canManageInventory === true) {
    defaultTab = 'tab-inventory';
  }

  let targetTab = defaultTab;
  if (hashCandidate && isTabPermitted(hashCandidate)) {
    targetTab = hashCandidate;
  } else if (savedCandidate && isTabPermitted(savedCandidate)) {
    targetTab = savedCandidate;
  }

  switchTab(targetTab, true);
  // Fetch the on-demand screens this role can open while the browser is idle, so opening them later is instant.
  prefetchChunksForRole(currentUser.role);

  // Live table orders, KOT status updates and manager bill prints arrive as 'orders-changed' stream signals.
  // The old 3s poll is kept only as a fallback that runs while the stream is not connected.
  ordersStream.start();
  if (!window.activeOrderPoller) {
    window.activeOrderPoller = setInterval(() => {
      if (!ordersStream.connected) runActiveOrderRefresh();
    }, 3000);
    document.addEventListener('visibilitychange', () => {
      if (!document.hidden && currentUser) {
        if (activeTab === 'tab-pos') runActiveOrderRefresh();
        if (['ADMIN', 'MANAGER'].includes(currentUser.role)) fetchSystemNotifications();
      }
    });
  }
}

function showLoginModal() {
  dismissSplash();
  document.getElementById('loginModal').classList.remove('hidden');
}

function quickFill(user, pass) {
  document.getElementById('loginUsername').value = user;
  document.getElementById('loginPassword').value = pass;
}

// ============================================================
// AUTHENTICATION
// ============================================================
async function handleLogin(e) {
  e.preventDefault();
  const errEl = document.getElementById('loginError');
  errEl.classList.add('hidden');

  const username = document.getElementById('loginUsername').value.trim();
  const password = document.getElementById('loginPassword').value;

  try {
    const res = await fetch(`${API_BASE_URL}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });

    if (!res.ok) {
      const errData = await res.json().catch(() => ({}));
      throw new Error(errData.message || 'Invalid username or password');
    }

    const data = await res.json();
    currentUser = data;
    localStorage.setItem('neram_user', JSON.stringify(data));

    if (data.mustChangePassword === true) {
      dismissSplash();
      document.getElementById('loginModal').classList.add('hidden');
      const curPassEl = document.getElementById('cpCurrentPassword');
      if (curPassEl) curPassEl.value = password;
      openChangePasswordModal(true);
      showToast('Temporary password detected. Please set your new secure password.', 'warning');
      return;
    }

    showToast(`Welcome back, ${data.employeeName || data.username}!`, 'success');
    applyUserSession();
  } catch (err) {
    errEl.textContent = err.message;
    errEl.classList.remove('hidden');
  }
}

function logout() {
  try {
    if (currentUser && currentUser.refreshToken) {
      fetch(`${API_BASE_URL}/auth/logout`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken: currentUser.refreshToken }),
        keepalive: true
      }).catch(() => { });
    }
  } catch (_) { }
  if (window.activeOrderPoller) {
    clearInterval(window.activeOrderPoller);
    window.activeOrderPoller = null;
  }
  stopNotificationStream();
  ordersStream.stop();
  isInitialNotificationFetch = true;
  lastKnownNotificationIds = new Set();
  currentUser = null;
  localStorage.removeItem('neram_user');
  localStorage.removeItem('neram_active_tab');
  try {
    history.replaceState(null, '', window.location.pathname);
  } catch (e) { }
  cart = [];
  location.reload();
}

// ------------------------------------------------------------
// Read-through cache + in-flight de-duplication for idempotent GETs.
// Only slow-changing reference data is TTL-cached; live data (orders, tables,
// notifications, shifts, bills) is never cached and only coalesced while a
// request for the identical URL is already in flight.
// ------------------------------------------------------------
const API_CACHE_RULES = [
  { re: /^\/(categories|menu-items)$/, ttl: 20000 },
  { re: /^\/gst\/config$/, ttl: 60000 },
  { re: /^\/settings\/(parcel-charge|public-menu)$/, ttl: 60000 },
  { re: /^\/printer\/config$/, ttl: 60000 }
];
const apiResponseCache = new Map(); // key -> { expires, data }
const apiInFlight = new Map();      // key -> Promise

function apiCloneData(data) {
  if (data === null || typeof data !== 'object') return data;
  try { return structuredClone(data); } catch (_) { return JSON.parse(JSON.stringify(data)); }
}

function invalidateApiCache(mutatedEndpoint) {
  if (!mutatedEndpoint) { apiResponseCache.clear(); return; }
  const seg = mutatedEndpoint.split('?')[0].split('/')[1] || '';
  // Related resources whose cached reads depend on one another.
  const groups = [['menu-items', 'categories', 'recipes'], ['gst', 'settings'], ['printer']];
  const related = new Set([seg]);
  groups.forEach(g => { if (g.includes(seg)) g.forEach(x => related.add(x)); });
  for (const key of Array.from(apiResponseCache.keys())) {
    const path = key.slice(key.indexOf('|') + 1);
    if (related.has(path.split('/')[1])) apiResponseCache.delete(key);
  }
}

// Helper for authenticated fetch
async function apiRequest(endpoint, options = {}, maybeBody = null) {
  const method = (typeof options === 'string' ? options : (options && options.method) || 'GET').toUpperCase();
  const hasBody = typeof options === 'string' ? maybeBody != null : !!(options && options.body);
  if (method !== 'GET' || hasBody) {
    try {
      return await apiRequestUncached(endpoint, options, maybeBody);
    } finally {
      // Invalidate after the write settles (success or failure) so no stale reference data survives.
      invalidateApiCache(endpoint);
    }
  }

  const key = `${currentUser ? currentUser.username : ''}|${endpoint}`;
  const rule = API_CACHE_RULES.find(r => r.re.test(endpoint));
  if (rule) {
    const hit = apiResponseCache.get(key);
    if (hit && hit.expires > Date.now()) return apiCloneData(hit.data);
  }
  let pending = apiInFlight.get(key);
  if (!pending) {
    pending = apiRequestUncached(endpoint, options, maybeBody)
      .then(data => {
        if (rule && data !== undefined) {
          apiResponseCache.set(key, { expires: Date.now() + rule.ttl, data });
        }
        return data;
      })
      .finally(() => apiInFlight.delete(key));
    apiInFlight.set(key, pending);
  }
  return apiCloneData(await pending);
}

// Single-flight access-token refresh. Returns true when currentUser.token was renewed.
let refreshInFlight = null;
function refreshAccessToken() {
  if (refreshInFlight) return refreshInFlight;
  refreshInFlight = (async () => {
    // Another browser tab may already have rotated the tokens: adopt them instead of spending the (single-use) refresh token.
    try {
      const stored = JSON.parse(localStorage.getItem('neram_user') || 'null');
      if (stored && stored.token && currentUser && stored.token !== currentUser.token) {
        currentUser = { ...currentUser, token: stored.token, refreshToken: stored.refreshToken };
        return true;
      }
    } catch (_) { }
    if (!currentUser || !currentUser.refreshToken) return false;
    const res = await fetch(`${API_BASE_URL}/auth/refresh`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refreshToken: currentUser.refreshToken })
    });
    if (!res.ok) return false;
    const data = await res.json();
    if (!data || !data.token) return false;
    currentUser = { ...currentUser, ...data };
    try { localStorage.setItem('neram_user', JSON.stringify(currentUser)); } catch (_) { }
    return true;
  })().catch(() => false).finally(() => { refreshInFlight = null; });
  return refreshInFlight;
}

async function apiRequestUncached(endpoint, options = {}, maybeBody = null, retried = false) {
  let fetchOptions = {};
  if (typeof options === 'string') {
    fetchOptions.method = options;
    if (maybeBody !== null && maybeBody !== undefined) {
      fetchOptions.body = typeof maybeBody === 'string' ? maybeBody : JSON.stringify(maybeBody);
    }
  } else {
    fetchOptions = { ...options };
  }

  const headers = fetchOptions.headers || {};
  if (currentUser && currentUser.token) {
    headers['Authorization'] = `Bearer ${currentUser.token}`;
  }
  if (!headers['Content-Type'] && fetchOptions.body && typeof fetchOptions.body === 'string') {
    headers['Content-Type'] = 'application/json';
  } else if (!headers['Content-Type']) {
    headers['Content-Type'] = 'application/json';
  }
  fetchOptions.headers = headers;

  const res = await fetch(`${API_BASE_URL}${endpoint}`, fetchOptions);

  if (res.status === 401) {
    if (!retried && await refreshAccessToken()) {
      return apiRequestUncached(endpoint, options, maybeBody, true);
    }
    logout();
    return;
  }

  if (!res.ok) {
    const err = await res.json().catch(() => ({ message: res.statusText }));
    throw new Error(err.message || err.error || 'Request failed');
  }

  if (res.status === 204) return null;
  return res.json();
}

// ============================================================
// MOBILE NAVIGATION & CART DRAWER HANDLERS
// ============================================================
function toggleMobileMenu(open) {
  const drawer = document.getElementById('mobileNavDrawer');
  if (!drawer) return;
  const backdrop = drawer.querySelector('.mobile-drawer-backdrop');
  const content = drawer.querySelector('.mobile-drawer-content');

  if (open) {
    drawer.classList.remove('pointer-events-none');
    backdrop.classList.remove('opacity-0', 'pointer-events-none');
    backdrop.classList.add('opacity-100', 'pointer-events-auto');
    content.classList.remove('-translate-x-full');
    content.classList.add('translate-x-0');
  } else {
    drawer.classList.add('pointer-events-none');
    backdrop.classList.remove('opacity-100', 'pointer-events-auto');
    backdrop.classList.add('opacity-0', 'pointer-events-none');
    content.classList.remove('translate-x-0');
    content.classList.add('-translate-x-full');
  }
}

function toggleMobileCart(open) {
  const panel = document.getElementById('posCartPanel');
  const backdrop = document.getElementById('mobileCartBackdrop');
  if (!panel) return;

  if (open) {
    panel.classList.add('mobile-open');
    document.body.classList.add('overflow-hidden-mobile');
    if (backdrop) {
      backdrop.classList.remove('opacity-0', 'pointer-events-none');
      backdrop.classList.add('opacity-100', 'pointer-events-auto');
    }
  } else {
    panel.classList.remove('mobile-open');
    document.body.classList.remove('overflow-hidden-mobile');
    if (backdrop) {
      backdrop.classList.remove('opacity-100', 'pointer-events-auto');
      backdrop.classList.add('opacity-0', 'pointer-events-none');
    }
  }
}

// ============================================================
// NAVIGATION TABS
// ============================================================
function buildNavigationTabs() {
  const container = document.getElementById('navTabsContainer');
  const drawerTabsContainer = document.getElementById('mobileNavDrawerTabs');
  if (container) container.innerHTML = '';
  if (drawerTabsContainer) drawerTabsContainer.innerHTML = '';

  const role = currentUser.role;
  const canTakeOrders = role === 'ADMIN' || role === 'MANAGER' || currentUser.canTakeOrders !== false;
  const canManageInventory = role === 'ADMIN' || role === 'MANAGER' || currentUser.canManageInventory === true;

  const allTabs = [
    { id: 'tab-pos', label: 'Table Orders & POS', icon: 'fa-cash-register', visible: canTakeOrders },
    { id: 'tab-bills', label: 'Bill Log & Printing', icon: 'fa-file-invoice-dollar', visible: ['ADMIN', 'MANAGER'].includes(role) },
    { id: 'tab-menu', label: 'Menu & Pricing', icon: 'fa-utensils', visible: ['ADMIN', 'MANAGER'].includes(role) },
    { id: 'tab-inventory', label: 'Inventory', icon: 'fa-boxes-stacked', visible: canManageInventory },
    { id: 'tab-staff', label: 'Staff & Payroll', icon: 'fa-users-gear', visible: ['ADMIN', 'MANAGER'].includes(role) },
    { id: 'tab-expenses', label: 'Cafe Expenses & EMI', icon: 'fa-receipt', visible: ['ADMIN', 'MANAGER'].includes(role) },
    { id: 'tab-analytics', label: 'Analytics', icon: 'fa-chart-pie', visible: ['ADMIN', 'MANAGER'].includes(role) },
    { id: 'tab-attendance', label: 'Attendance & Leaves', icon: 'fa-calendar-check', visible: true },
    { id: 'tab-audit', label: 'Audit Log', icon: 'fa-shield-halved', visible: role === 'ADMIN' },
    { id: 'tab-telegram', label: 'Telegram Alerts', icon: 'fa-paper-plane', visible: role === 'ADMIN' },
    { id: 'tab-users', label: 'User Accounts', icon: 'fa-id-badge', visible: ['ADMIN', 'MANAGER'].includes(role) },
    { id: 'tab-suppliers', label: 'Suppliers', icon: 'fa-truck', visible: ['ADMIN', 'MANAGER'].includes(role) },
    { id: 'tab-gst', label: 'GST Management', icon: 'fa-percent', visible: ['ADMIN', 'MANAGER'].includes(role) },
  ];

  const visibleTabs = allTabs.filter(t => t.visible);

  visibleTabs.forEach(t => {
    const isActive = activeTab === t.id;
    // Desktop Nav Button
    if (container) {
      const btn = document.createElement('button');
      btn.className = `tab-btn px-4 py-2 rounded-lg flex items-center space-x-2 text-gray-300 hover:text-white hover:bg-gray-800/80 transition ${isActive ? 'active' : ''}`;
      btn.onclick = () => switchTab(t.id);
      btn.innerHTML = `<i class="fa-solid ${t.icon}"></i><span>${t.label}</span>`;
      container.appendChild(btn);
    }

    // Mobile Drawer Navigation Item
    if (drawerTabsContainer) {
      const drawerBtn = document.createElement('button');
      drawerBtn.className = `w-full px-3.5 py-2.5 rounded-xl flex items-center space-x-3 text-left text-sm font-medium transition ${isActive
        ? 'bg-amber-500 text-gray-950 font-bold shadow-md shadow-amber-500/20'
        : 'text-gray-300 hover:bg-gray-900 hover:text-white'
        }`;
      drawerBtn.onclick = () => {
        toggleMobileMenu(false);
        switchTab(t.id);
      };
      drawerBtn.innerHTML = `<i class="fa-solid ${t.icon} text-base w-5 text-center ${isActive ? 'text-gray-950' : 'text-amber-400'}"></i><span>${t.label}</span>`;
      drawerTabsContainer.appendChild(drawerBtn);
    }
  });

  // Mobile Bottom Navigation Bar (Phone / Tablet quick switch)
  const bottomNavContainer = document.getElementById('mobileBottomNav');
  if (bottomNavContainer) {
    bottomNavContainer.innerHTML = '';
    const primaryTabIds = ['tab-pos', 'tab-bills', 'tab-menu', 'tab-inventory', 'tab-attendance', 'tab-staff'];
    let mobileTabs = visibleTabs.filter(t => primaryTabIds.includes(t.id));
    if (mobileTabs.length === 0) {
      mobileTabs = visibleTabs;
    }

    mobileTabs.slice(0, 5).forEach(t => {
      const isActive = activeTab === t.id;
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = `mobile-bottom-nav-item ${isActive ? 'active' : ''}`;
      btn.onclick = () => switchTab(t.id);
      let shortLabel = 'POS';
      if (t.id === 'tab-bills') shortLabel = 'Bills';
      else if (t.id === 'tab-menu') shortLabel = 'Menu';
      else if (t.id === 'tab-inventory') shortLabel = 'Stock';
      else if (t.id === 'tab-attendance') shortLabel = 'Leaves';
      else if (t.id === 'tab-staff') shortLabel = 'Staff';
      else shortLabel = t.label.split(' ')[0];

      btn.innerHTML = `<i class="fa-solid ${t.icon}"></i><span>${shortLabel}</span>`;
      bottomNavContainer.appendChild(btn);
    });
  }
}

function switchTab(tabId, updateUrl = true) {
  activeTab = tabId;
  localStorage.setItem('neram_active_tab', tabId);

  if (updateUrl !== false) {
    const cleanHash = '#' + tabId.replace(/^tab-/, '');
    if (window.location.hash !== cleanHash) {
      try {
        history.replaceState(null, '', cleanHash);
      } catch (e) {
        window.location.hash = cleanHash;
      }
    }
  }

  // Close any mobile sheets or menus on tab switch
  toggleMobileMenu(false);
  toggleMobileCart(false);

  // Toggle floating cart bar visibility on mobile: only show in POS tab
  const mobileCartBar = document.getElementById('mobileFloatingCartBar');
  if (mobileCartBar) {
    if (tabId === 'tab-pos') {
      mobileCartBar.classList.remove('hidden');
    } else {
      mobileCartBar.classList.add('hidden');
    }
  }

  // Hide all tab contents
  document.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));

  // Show active tab with smooth entry animation
  const activeEl = document.getElementById(tabId);
  if (activeEl) {
    activeEl.classList.remove('hidden');
    activeEl.classList.remove('tab-enter-active');
    void activeEl.offsetWidth;
    activeEl.classList.add('tab-enter-active');
  }

  // Update tab buttons
  document.querySelectorAll('.tab-btn').forEach(btn => {
    btn.classList.remove('active');
  });
  buildNavigationTabs();

  // Trigger tab data load
  switch (tabId) {
    case 'tab-pos':
      loadPosData();
      break;
    case 'tab-bills':
      loadBillsView(currentBillsMode);
      break;
    case 'tab-menu':
      loadMenuData();
      break;
    case 'tab-inventory':
      loadInventoryData();
      break;
    case 'tab-staff':
      loadStaffData();
      loadSalaryData();
      break;
    case 'tab-expenses':
      loadExpensesData();
      break;
    case 'tab-analytics':
      loadComprehensiveAnalytics();
      break;
    case 'tab-attendance':
      loadAttendanceData();
      loadLeavesData();
      break;
    case 'tab-audit':
      loadAuditLogs();
      break;
    case 'tab-users':
      loadUsersData();
      break;
    case 'tab-suppliers':
      loadSuppliersData();
      break;
    case 'tab-gst':
      loadGstConfig();
      break;
    case 'tab-telegram':
      if (!currentUser || currentUser.role !== 'ADMIN') {
        showToast('Access restricted to administrators only', 'error');
        return switchTab('tab-pos');
      }
      loadTelegramData();
      break;
  }
}

// ============================================================
// TAB 1: POS BILLING & TABLE ORDERS
// ============================================================
async function loadPosData() {
  try {
    [categories, menuItems] = await Promise.all([
      apiRequest('/categories'),
      apiRequest('/menu-items')
    ]);
    renderCategoryPills();
    renderDishesGrid();
    // refreshActiveOrders() already syncs dining tables first; fetching them here as well duplicated /tables.
    await refreshActiveOrders();
  } catch (err) {
    showToast('Failed to load menu: ' + err.message, 'error');
  }
}

let prevActiveOrderIds = new Set();

async function refreshActiveOrders() {
  try {
    // 1 + 2. Sync dining tables and active table/outdoor orders from the backend (fetched in parallel, both applied before continuing)
    const [, orders] = await Promise.all([fetchDiningTables(), apiRequest('/bills/active')]);
    const newOrders = orders || [];

    if (currentOrderLocation === 'TAKEAWAY') {
      const matchingOrder = currentTableOrder
        ? newOrders.find(o => o.id === currentTableOrder.id)
        : (currentTakeawayToken ? newOrders.find(o => o.takeawayToken === currentTakeawayToken) : null);

      if (currentTableOrder && !newOrders.some(o => o.id === currentTableOrder.id)) {
        const wasInBillFlow = ['KOT_REQUESTED', 'KOT_PRINTED', 'BILL_REQUESTED'].includes(currentTableOrder.status);
        if (wasInBillFlow) {
          showToast(`Takeaway Order ${currentTakeawayToken || ''} (${currentTableOrder.customerName || ''}) bill settled & printed. Ready for next order!`, 'success');
        }
        currentTableOrder = null;
        currentTakeawayToken = null;
        cart = [];
        isCartDirty = false;
        const custInput = document.getElementById('cartCustomer');
        if (custInput) custInput.value = '';
        syncTableOrderState('');
      } else if (!isCartDirty && matchingOrder) {
        const prevItemsKey = JSON.stringify((currentTableOrder?.items || []).map(i => ({ m: i.menuItemId, q: i.quantity, p: i.price, s: i.status })));
        const nextItemsKey = JSON.stringify((matchingOrder?.items || []).map(i => ({ m: i.menuItemId, q: i.quantity, p: i.price, s: i.status })));
        const prevStatus = currentTableOrder?.status || '';
        const nextStatus = matchingOrder?.status || '';
        const prevId = currentTableOrder?.id || null;
        const nextId = matchingOrder?.id || null;

        if (prevId !== nextId || prevStatus !== nextStatus || prevItemsKey !== nextItemsKey) {
          currentTableOrder = matchingOrder;
          currentTakeawayToken = matchingOrder.takeawayToken;
          syncTableOrderState('');
        }
      }
    } else if (currentOrderLocation === 'OUTDOOR') {
      const matchingOrder = currentTableOrder
        ? newOrders.find(o => o.id === currentTableOrder.id)
        : (currentOutdoorToken ? newOrders.find(o => o.outdoorToken === currentOutdoorToken) : null);

      if (currentTableOrder && !newOrders.some(o => o.id === currentTableOrder.id)) {
        const wasInBillFlow = ['KOT_REQUESTED', 'KOT_PRINTED', 'BILL_REQUESTED'].includes(currentTableOrder.status);
        if (wasInBillFlow) {
          showToast(`Outdoor Order ${currentOutdoorToken || ''} (${currentTableOrder.customerName || ''}) bill settled & printed. Ready for next order!`, 'success');
        }
        currentTableOrder = null;
        currentOutdoorToken = null;
        cart = [];
        isCartDirty = false;
        const custInput = document.getElementById('cartCustomer');
        if (custInput) custInput.value = '';
        syncTableOrderState('');
      } else if (!isCartDirty && matchingOrder) {
        const prevItemsKey = JSON.stringify((currentTableOrder?.items || []).map(i => ({ m: i.menuItemId, q: i.quantity, p: i.price, s: i.status })));
        const nextItemsKey = JSON.stringify((matchingOrder?.items || []).map(i => ({ m: i.menuItemId, q: i.quantity, p: i.price, s: i.status })));
        const prevStatus = currentTableOrder?.status || '';
        const nextStatus = matchingOrder?.status || '';
        const prevId = currentTableOrder?.id || null;
        const nextId = matchingOrder?.id || null;

        if (prevId !== nextId || prevStatus !== nextStatus || prevItemsKey !== nextItemsKey) {
          currentTableOrder = matchingOrder;
          currentOutdoorToken = matchingOrder.outdoorToken;
          syncTableOrderState('');
        }
      }
    } else {
      const selTable = document.getElementById('cartTableNo')?.value?.trim() || '';
      if (selTable) {
        const matchingOrder = newOrders.find(o => o.tableNumber === selTable) || null;

        // Case A: Current order was completed, billed, printed, or cancelled
        if (currentTableOrder && !newOrders.some(o => o.id === currentTableOrder.id)) {
          const wasInBillFlow = ['KOT_REQUESTED', 'KOT_PRINTED', 'BILL_REQUESTED'].includes(currentTableOrder.status);
          if (wasInBillFlow) {
            showToast(`Table ${selTable} bill settled & printed. Ready for new customer!`, 'success');
          }
          currentTableOrder = null;
          cart = [];
          isCartDirty = false;
          const custInput = document.getElementById('cartCustomer');
          if (custInput) custInput.value = '';
          syncTableOrderState(selTable);
        } else if (!isCartDirty) {
          // Case B: Real-time sync of dishes/order added or updated by another manager or staff member
          const prevItemsKey = JSON.stringify((currentTableOrder?.items || []).map(i => ({ m: i.menuItemId, q: i.quantity, p: i.price, s: i.status })));
          const nextItemsKey = JSON.stringify((matchingOrder?.items || []).map(i => ({ m: i.menuItemId, q: i.quantity, p: i.price, s: i.status })));
          const prevStatus = currentTableOrder?.status || '';
          const nextStatus = matchingOrder?.status || '';
          const prevId = currentTableOrder?.id || null;
          const nextId = matchingOrder?.id || null;

          if (prevId !== nextId || prevStatus !== nextStatus || prevItemsKey !== nextItemsKey) {
            currentTableOrder = matchingOrder;
            syncTableOrderState(selTable);
          }
        }
      }
    }

    activeOrders = newOrders;
    prevActiveOrderIds = new Set(newOrders.map(o => o.id));

    renderTableBadges();
    renderOutdoorBadges();
    renderTakeawayBadges();
  } catch (err) {
    console.error('Error loading active orders:', err);
  }
}

function renderTableBadges() {
  const container = document.getElementById('posTableGridBadges');
  if (!container) return;

  const tables = getSavedTables();
  const currentSel = (currentOrderLocation === 'TABLE') ? (document.getElementById('cartTableNo')?.value?.trim() || '') : '';

  container.innerHTML = tables.map(t => {
    const order = activeOrders.find(o => o.tableNumber === t);
    let statusBadge = '';
    let borderClass = 'border-gray-800 bg-gray-900/60 text-gray-300';

    if (order) {
      if (order.status === 'KOT_REQUESTED') {
        borderClass = 'border-orange-500/50 bg-orange-500/10 text-orange-400 animate-pulse';
        statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-orange-500/20 font-bold ml-1">KOT Req</span>`;
      } else if (order.status === 'KOT_PRINTED') {
        borderClass = 'border-cyan-500/50 bg-cyan-500/10 text-cyan-400';
        statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-cyan-500/20 font-bold ml-1">KOT Printed</span>`;
      } else if (order.status === 'BILL_REQUESTED') {
        borderClass = 'border-purple-500/50 bg-purple-500/10 text-purple-400 animate-pulse';
        statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-purple-500/20 font-bold ml-1">Bill Req</span>`;
      } else if (order.status === 'BILL_PRINTED') {
        borderClass = 'border-amber-500/70 bg-amber-500/10 text-amber-400 animate-pulse';
        statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-amber-500/20 text-amber-300 font-extrabold ml-1">Pending Pay</span>`;
      } else {
        borderClass = 'border-emerald-500/50 bg-emerald-500/10 text-emerald-400';
        statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-emerald-500/20 font-bold ml-1">₹${order.netAmount.toFixed(0)}</span>`;
      }
    }

    const isCurrent = t === currentSel;
    const activeRing = isCurrent ? 'ring-2 ring-amber-400 font-bold text-white' : '';

    return `
      <button type="button" onclick="switchTableSelection('${t}')" class="px-3 py-1.5 rounded-lg text-xs flex items-center border transition ${borderClass} ${activeRing}">
        <i class="fa-solid fa-chair text-[10px] mr-1"></i>
        <span>${t}</span>
        ${statusBadge}
      </button>
    `;
  }).join('');
  renderMobileTableControls();
}

function renderOutdoorBadges() {
  const container = document.getElementById('posOutdoorBadges');
  if (!container) return;

  const countBadge = document.getElementById('activeOrdersBadgeCount');
  if (countBadge) {
    countBadge.textContent = activeOrders.length;
  }

  const outdoorOrders = activeOrders.filter(o => o.orderType === 'OUTDOOR' || Boolean(o.outdoorToken));

  if (outdoorOrders.length === 0) {
    container.innerHTML = `<span class="text-[11px] text-gray-500 italic py-1">No active outdoor orders</span>`;
    renderMobileTableControls();
    return;
  }

  container.innerHTML = outdoorOrders.map(order => {
    let statusBadge = '';
    let borderClass = 'border-gray-800 bg-gray-900/60 text-gray-300';

    if (order.status === 'KOT_REQUESTED') {
      borderClass = 'border-orange-500/50 bg-orange-500/10 text-orange-400 animate-pulse';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-orange-500/20 font-bold ml-1">KOT Req</span>`;
    } else if (order.status === 'KOT_PRINTED') {
      borderClass = 'border-cyan-500/50 bg-cyan-500/10 text-cyan-400';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-cyan-500/20 font-bold ml-1">Preparing</span>`;
    } else if (order.status === 'BILL_REQUESTED') {
      borderClass = 'border-purple-500/50 bg-purple-500/10 text-purple-400 animate-pulse';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-purple-500/20 font-bold ml-1">Bill Req</span>`;
    } else if (order.status === 'BILL_PRINTED') {
      borderClass = 'border-amber-500/70 bg-amber-500/10 text-amber-400 animate-pulse';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-amber-500/20 text-amber-300 font-extrabold ml-1">Pending Pay</span>`;
    } else {
      borderClass = 'border-emerald-500/50 bg-emerald-500/10 text-emerald-400';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-emerald-500/20 font-bold ml-1">₹${order.netAmount.toFixed(0)}</span>`;
    }

    const isCurrent = currentOrderLocation === 'OUTDOOR' && currentTableOrder && currentTableOrder.id === order.id;
    const activeRing = isCurrent ? 'ring-2 ring-emerald-400 font-bold text-white' : '';

    return `
      <button type="button" onclick="selectOutdoorOrder(${order.id})" class="px-2.5 py-1 rounded-lg text-xs flex items-center border transition shrink-0 ${borderClass} ${activeRing}">
        <i class="fa-solid fa-tree text-[10px] mr-1 text-emerald-400"></i>
        <span class="font-bold text-white mr-1">${escapeHtml(order.customerName || 'Guest')}</span>
        <span class="font-mono text-[10px] text-emerald-400 font-semibold">• ${escapeHtml(order.outdoorToken || 'OUT')}</span>
        ${statusBadge}
      </button>
    `;
  }).join('');
  renderMobileTableControls();
}

function renderTakeawayBadges() {
  const container = document.getElementById('posTakeawayBadges');
  if (!container) return;

  const takeawayOrders = activeOrders.filter(o => o.orderType === 'TAKEAWAY' || Boolean(o.takeawayToken));

  if (takeawayOrders.length === 0) {
    container.innerHTML = `<span class="text-[11px] text-gray-500 italic py-1">No active takeaway orders</span>`;
    renderMobileTableControls();
    return;
  }

  container.innerHTML = takeawayOrders.map(order => {
    let statusBadge = '';
    let borderClass = 'border-gray-800 bg-gray-900/60 text-gray-300';

    if (order.status === 'KOT_REQUESTED') {
      borderClass = 'border-orange-500/50 bg-orange-500/10 text-orange-400 animate-pulse';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-orange-500/20 font-bold ml-1">KOT Req</span>`;
    } else if (order.status === 'KOT_PRINTED') {
      borderClass = 'border-cyan-500/50 bg-cyan-500/10 text-cyan-400';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-cyan-500/20 font-bold ml-1">Packing</span>`;
    } else if (order.status === 'BILL_REQUESTED') {
      borderClass = 'border-purple-500/50 bg-purple-500/10 text-purple-400 animate-pulse';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-purple-500/20 font-bold ml-1">Bill Req</span>`;
    } else if (order.status === 'BILL_PRINTED') {
      borderClass = 'border-amber-500/70 bg-amber-500/10 text-amber-400 animate-pulse';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-amber-500/20 text-amber-300 font-extrabold ml-1">Pending Pay</span>`;
    } else {
      borderClass = 'border-amber-500/50 bg-amber-500/10 text-amber-400';
      statusBadge = `<span class="text-[9px] px-1.5 py-0.2 rounded bg-amber-500/20 font-bold ml-1">₹${order.netAmount.toFixed(0)}</span>`;
    }

    const isCurrent = currentOrderLocation === 'TAKEAWAY' && currentTableOrder && currentTableOrder.id === order.id;
    const activeRing = isCurrent ? 'ring-2 ring-amber-400 font-bold text-white' : '';

    return `
      <button type="button" onclick="selectTakeawayOrder(${order.id})" class="px-2.5 py-1 rounded-lg text-xs flex items-center border transition shrink-0 ${borderClass} ${activeRing}">
        <i class="fa-solid fa-bag-shopping text-[10px] mr-1 text-amber-400"></i>
        <span class="font-bold text-white mr-1">${escapeHtml(order.customerName || 'Guest')}</span>
        <span class="font-mono text-[10px] text-amber-400 font-semibold">• ${escapeHtml(order.takeawayToken || 'TAK')}</span>
        ${statusBadge}
      </button>
    `;
  }).join('');
  renderMobileTableControls();
}

async function setOrderLocationMode(mode, orderToLoad = null) {
  currentOrderLocation = mode;

  const btnTable = document.getElementById('btnOrderLocTable');
  const btnOutdoor = document.getElementById('btnOrderLocOutdoor');
  const btnTakeaway = document.getElementById('btnOrderLocTakeaway');
  const tableSec = document.getElementById('cartTableSelectSection');
  const outdoorSec = document.getElementById('cartOutdoorTokenSection');
  const takeawaySec = document.getElementById('cartTakeawayTokenSection');
  const outdoorTokenDisp = document.getElementById('cartOutdoorTokenDisplay');
  const takeawayTokenDisp = document.getElementById('cartTakeawayTokenDisplay');
  const custLabel = document.getElementById('cartCustomerLabel');
  const custInput = document.getElementById('cartCustomer');
  const locLabel = document.getElementById('currentOrderLocationLabel');

  [btnTable, btnOutdoor, btnTakeaway].forEach(b => {
    if (b) b.className = 'py-0.5 px-1.5 rounded text-[10px] font-bold transition flex items-center justify-center gap-1 text-gray-400 hover:text-white';
  });

  if (mode === 'TAKEAWAY') {
    if (btnTakeaway) {
      btnTakeaway.className = 'py-0.5 px-1.5 rounded text-[10px] font-bold transition flex items-center justify-center gap-1 bg-amber-500 text-gray-950 font-bold shadow';
    }
    if (tableSec) tableSec.classList.add('hidden');
    if (outdoorSec) outdoorSec.classList.add('hidden');
    if (takeawaySec) takeawaySec.classList.remove('hidden');
    if (custLabel) custLabel.innerHTML = 'Customer (Optional)';
    if (custInput) custInput.placeholder = 'Guest / Customer name...';
    if (locLabel) {
      locLabel.textContent = 'TAKEAWAY / PARCEL';
      locLabel.className = 'text-[9px] text-amber-400 font-bold truncate';
    }

    const sel = document.getElementById('cartTableNo');
    if (sel) sel.value = '';

    if (orderToLoad) {
      currentTableOrder = orderToLoad;
      currentTakeawayToken = orderToLoad.takeawayToken;
      currentOutdoorToken = null;
      if (takeawayTokenDisp) takeawayTokenDisp.textContent = orderToLoad.takeawayToken || 'TAK';
      syncTableOrderState('');
    } else {
      currentTableOrder = null;
      currentTakeawayToken = null;
      currentOutdoorToken = null;
      try {
        const tokenRes = await apiRequest('/bills/next-takeaway-token');
        if (tokenRes && tokenRes.nextTakeawayToken) {
          nextTakeawayTokenPreview = tokenRes.nextTakeawayToken;
          if (takeawayTokenDisp) takeawayTokenDisp.textContent = nextTakeawayTokenPreview;
        }
      } catch (e) {
        if (takeawayTokenDisp) takeawayTokenDisp.textContent = 'TAK-001';
      }
      syncTableOrderState('');
    }
  } else if (mode === 'OUTDOOR') {
    if (btnOutdoor) {
      btnOutdoor.className = 'py-0.5 px-1.5 rounded text-[10px] font-bold transition flex items-center justify-center gap-1 bg-emerald-500 text-gray-950 font-bold shadow';
    }
    if (tableSec) tableSec.classList.add('hidden');
    if (outdoorSec) outdoorSec.classList.remove('hidden');
    if (takeawaySec) takeawaySec.classList.add('hidden');
    if (custLabel) custLabel.innerHTML = 'Customer Name <span class="text-rose-400 font-bold">*</span>';
    if (custInput) custInput.placeholder = 'Mandatory customer name';
    if (locLabel) {
      locLabel.textContent = 'OUTDOOR SEATING';
      locLabel.className = 'text-[9px] text-emerald-400 font-bold truncate';
    }

    const sel = document.getElementById('cartTableNo');
    if (sel) sel.value = '';

    if (orderToLoad) {
      currentTableOrder = orderToLoad;
      currentOutdoorToken = orderToLoad.outdoorToken;
      currentTakeawayToken = null;
      if (outdoorTokenDisp) outdoorTokenDisp.textContent = orderToLoad.outdoorToken || 'OUT';
      syncTableOrderState('');
    } else {
      currentTableOrder = null;
      currentOutdoorToken = null;
      currentTakeawayToken = null;
      try {
        const tokenRes = await apiRequest('/bills/next-outdoor-token');
        if (tokenRes && tokenRes.nextOutdoorToken) {
          nextOutdoorTokenPreview = tokenRes.nextOutdoorToken;
          if (outdoorTokenDisp) outdoorTokenDisp.textContent = nextOutdoorTokenPreview;
        }
      } catch (e) {
        if (outdoorTokenDisp) outdoorTokenDisp.textContent = 'OUT-001';
      }
      syncTableOrderState('');
    }
  } else {
    // Mode is TABLE
    if (btnTable) {
      btnTable.className = 'py-0.5 px-1.5 rounded text-[10px] font-bold transition flex items-center justify-center gap-1 bg-amber-500 text-gray-950 font-bold shadow';
    }
    if (tableSec) tableSec.classList.remove('hidden');
    if (outdoorSec) outdoorSec.classList.add('hidden');
    if (takeawaySec) takeawaySec.classList.add('hidden');
    if (custLabel) custLabel.innerHTML = 'Customer (Optional)';
    if (custInput) custInput.placeholder = 'Optional';
    if (locLabel) {
      locLabel.textContent = 'TABLE SEATING';
      locLabel.className = 'text-[9px] text-amber-400 font-bold truncate';
    }

    currentOutdoorToken = null;
    currentTakeawayToken = null;
    if (orderToLoad) {
      currentTableOrder = orderToLoad;
      loadTableOptions(orderToLoad.tableNumber);
      syncTableOrderState(orderToLoad.tableNumber);
    } else {
      const curTable = document.getElementById('cartTableNo')?.value || '';
      syncTableOrderState(curTable);
    }
  }

  renderTableBadges();
  renderOutdoorBadges();
  renderTakeawayBadges();
  updateOrderActionButtonsState();
}

async function startNewOutdoorOrder() {
  if (isCartDirty) {
    if (!confirm('You have unsaved changes in the current order. Start a new outdoor order anyway?')) {
      return;
    }
  }

  isCartDirty = false;
  cart = [];
  currentTableOrder = null;
  currentOutdoorToken = null;
  currentTakeawayToken = null;
  const custInput = document.getElementById('cartCustomer');
  if (custInput) custInput.value = '';

  await setOrderLocationMode('OUTDOOR');
  if (custInput) custInput.focus();
}

async function selectOutdoorOrder(orderId) {
  const order = activeOrders.find(o => o.id === orderId);
  if (!order) {
    showToast('Outdoor order not found in active orders', 'warning');
    return;
  }
  isCartDirty = false;
  await setOrderLocationMode('OUTDOOR', order);
}

async function startNewTakeawayOrder() {
  if (isCartDirty) {
    if (!confirm('You have unsaved changes in the current order. Start a new takeaway order anyway?')) {
      return;
    }
  }

  isCartDirty = false;
  cart = [];
  currentTableOrder = null;
  currentOutdoorToken = null;
  currentTakeawayToken = null;
  const custInput = document.getElementById('cartCustomer');
  if (custInput) custInput.value = '';

  await setOrderLocationMode('TAKEAWAY');
  if (custInput) custInput.focus();
}

async function selectTakeawayOrder(orderId) {
  const order = activeOrders.find(o => o.id === orderId);
  if (!order) {
    showToast('Takeaway order not found in active orders', 'warning');
    return;
  }
  isCartDirty = false;
  await setOrderLocationMode('TAKEAWAY', order);
}

async function convertCurrentOrderLocation() {
  if (!currentTableOrder || !currentTableOrder.id) {
    showToast('No active order to convert.', 'warning');
    return;
  }
  const currentType = currentTableOrder.orderType || (currentTableOrder.takeawayToken ? 'TAKEAWAY' : (currentTableOrder.outdoorToken ? 'OUTDOOR' : 'TABLE'));
  const target = prompt(`Current order is ${currentType}. Convert to: TABLE, OUTDOOR, or TAKEAWAY?`);
  if (!target) return;
  const upper = target.trim().toUpperCase();

  if (upper === 'TABLE') {
    const targetTable = prompt('Select Table to convert order to (e.g. T-01 to T-08):');
    if (!targetTable || !targetTable.trim()) return;
    try {
      const converted = await apiRequest(`/bills/${currentTableOrder.id}/change-location`, {
        method: 'POST',
        body: JSON.stringify({ orderType: 'TABLE', tableNumber: targetTable.trim() })
      });
      showToast(`Order #${converted.billNumber} converted to Table ${converted.tableNumber}`, 'success');
      await refreshActiveOrders();
      await switchTableSelection(converted.tableNumber);
    } catch (err) {
      showToast('Failed to convert location: ' + err.message, 'error');
    }
  } else if (upper === 'OUTDOOR') {
    let cust = (document.getElementById('cartCustomer')?.value || '').trim();
    if (!cust) {
      cust = prompt('Customer Name is required for Outdoor Seating:');
      if (!cust || !cust.trim()) return;
    }
    try {
      const converted = await apiRequest(`/bills/${currentTableOrder.id}/change-location`, {
        method: 'POST',
        body: JSON.stringify({ orderType: 'OUTDOOR', customerName: cust.trim() })
      });
      showToast(`Order #${converted.billNumber} converted to Outdoor: ${converted.customerName} • ${converted.outdoorToken}`, 'success');
      await refreshActiveOrders();
      await selectOutdoorOrder(converted.id);
    } catch (err) {
      showToast('Failed to convert location: ' + err.message, 'error');
    }
  } else if (upper === 'TAKEAWAY') {
    const cust = (document.getElementById('cartCustomer')?.value || '').trim() || 'Guest';
    try {
      const converted = await apiRequest(`/bills/${currentTableOrder.id}/change-location`, {
        method: 'POST',
        body: JSON.stringify({ orderType: 'TAKEAWAY', customerName: cust })
      });
      showToast(`Order #${converted.billNumber} converted to Takeaway: ${converted.takeawayToken}`, 'success');
      await refreshActiveOrders();
      await selectTakeawayOrder(converted.id);
    } catch (err) {
      showToast('Failed to convert location: ' + err.message, 'error');
    }
  } else {
    showToast('Invalid choice. Must be TABLE, OUTDOOR, or TAKEAWAY', 'warning');
  }
}

function openActiveOrdersModal() {
  const modal = document.getElementById('activeOrdersModal');
  if (!modal) return;
  modal.classList.remove('hidden');
  renderActiveOrdersCards();
}

function closeActiveOrdersModal() {
  const modal = document.getElementById('activeOrdersModal');
  if (modal) modal.classList.add('hidden');
}

function setActiveOrdersModalFilter(filter) {
  activeOrdersModalFilter = filter;
  const btnAll = document.getElementById('btnActFilterAll');
  const btnTable = document.getElementById('btnActFilterTable');
  const btnOutdoor = document.getElementById('btnActFilterOutdoor');
  const btnTakeaway = document.getElementById('btnActFilterTakeaway');

  [btnAll, btnTable, btnOutdoor, btnTakeaway].forEach(b => {
    if (b) {
      b.className = 'px-3 py-1 rounded text-gray-400 hover:text-white';
    }
  });

  if (filter === 'ALL' && btnAll) btnAll.className = 'px-3 py-1 rounded bg-amber-500 text-gray-950 font-bold';
  if (filter === 'TABLE' && btnTable) btnTable.className = 'px-3 py-1 rounded bg-amber-500 text-gray-950 font-bold';
  if (filter === 'OUTDOOR' && btnOutdoor) btnOutdoor.className = 'px-3 py-1 rounded bg-amber-500 text-gray-950 font-bold';
  if (filter === 'TAKEAWAY' && btnTakeaway) btnTakeaway.className = 'px-3 py-1 rounded bg-amber-500 text-gray-950 font-bold';

  renderActiveOrdersCards();
}

function renderActiveOrdersCards() {
  const container = document.getElementById('activeOrdersCardsContainer');
  if (!container) return;

  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  const query = (document.getElementById('activeOrdersSearchInput')?.value || '').trim().toLowerCase();

  let list = activeOrders || [];

  if (activeOrdersModalFilter === 'TABLE') {
    list = list.filter(o => o.orderType !== 'OUTDOOR' && o.orderType !== 'TAKEAWAY' && !o.outdoorToken && !o.takeawayToken && Boolean(o.tableNumber));
  } else if (activeOrdersModalFilter === 'OUTDOOR') {
    list = list.filter(o => o.orderType === 'OUTDOOR' || Boolean(o.outdoorToken));
  } else if (activeOrdersModalFilter === 'TAKEAWAY') {
    list = list.filter(o => o.orderType === 'TAKEAWAY' || Boolean(o.takeawayToken));
  }

  if (query) {
    list = list.filter(o => {
      const cust = (o.customerName || '').toLowerCase();
      const token = (o.outdoorToken || o.takeawayToken || '').toLowerCase();
      const billNo = String(o.billNumber || '').toLowerCase();
      const table = (o.tableNumber || '').toLowerCase();
      return cust.includes(query) || token.includes(query) || billNo.includes(query) || table.includes(query);
    });
  }

  if (list.length === 0) {
    container.innerHTML = `<div class="col-span-full text-center py-10 text-gray-500 text-xs">No active orders matching criteria</div>`;
    return;
  }

  container.innerHTML = list.map(order => {
    const isTakeaway = order.orderType === 'TAKEAWAY' || Boolean(order.takeawayToken);
    const isOutdoor = order.orderType === 'OUTDOOR' || Boolean(order.outdoorToken);
    let statusText = 'ACTIVE';
    let statusColor = 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30';

    if (order.status === 'KOT_REQUESTED') {
      statusText = 'KOT REQUESTED';
      statusColor = 'bg-orange-500/20 text-orange-400 border border-orange-500/30 animate-pulse';
    } else if (order.status === 'KOT_PRINTED') {
      statusText = isTakeaway ? 'PACKING' : 'PREPARING';
      statusColor = 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30';
    } else if (order.status === 'BILL_REQUESTED') {
      statusText = 'BILL REQUESTED';
      statusColor = 'bg-purple-500/20 text-purple-400 border border-purple-500/30 animate-pulse';
    } else if (order.status === 'BILL_PRINTED') {
      statusText = 'PENDING PAYMENT';
      statusColor = 'bg-amber-500/20 text-amber-300 border border-amber-500/40 animate-pulse';
    }

    const titleHtml = isTakeaway
      ? `<div class="flex items-center space-x-1.5 text-amber-400">
           <i class="fa-solid fa-bag-shopping text-sm"></i>
           <span class="font-extrabold text-sm text-white">${escapeHtml(order.customerName || 'Guest')}</span>
         </div>
         <div class="font-mono text-xs font-bold text-amber-400 mt-0.5">${escapeHtml(order.takeawayToken || 'TAK')}</div>`
      : (isOutdoor
        ? `<div class="flex items-center space-x-1.5 text-emerald-400">
             <i class="fa-solid fa-tree text-sm"></i>
             <span class="font-extrabold text-sm text-white">${escapeHtml(order.customerName || 'Outdoor Guest')}</span>
           </div>
           <div class="font-mono text-xs font-bold text-emerald-400 mt-0.5">${escapeHtml(order.outdoorToken || 'OUT')}</div>`
        : `<div class="flex items-center space-x-1.5 text-amber-400">
             <i class="fa-solid fa-chair text-sm"></i>
             <span class="font-extrabold text-sm text-white">${escapeHtml(order.tableNumber || 'Table')}</span>
           </div>
           <div class="text-xs text-gray-400 mt-0.5">${escapeHtml(order.customerName || 'Dine-in')}</div>`);

    return `
      <div onclick="selectOrderFromModal(${order.id})" class="glass-card p-3 rounded-xl cursor-pointer hover:border-amber-500/50 flex flex-col justify-between transition group">
        <div>
          <div class="flex justify-between items-start mb-2">
            <div>${titleHtml}</div>
            <span class="text-[9px] font-bold px-2 py-0.5 rounded-full ${statusColor}">${statusText}</span>
          </div>
          <div class="text-[11px] text-gray-400 mb-1">
            <span>Order #${order.billNumber}</span> • <span>${(order.items || []).length} dishes</span>
          </div>
        </div>
        <div class="flex justify-between items-center pt-2 border-t border-gray-800/80 mt-2 text-xs">
          <span class="font-bold text-amber-400">₹${(order.netAmount || 0).toFixed(2)}</span>
          <div class="flex items-center space-x-2">
            ${(order.status === 'BILL_PRINTED' && isManagerOrAdmin) ? `
              <button onclick="event.stopPropagation(); openConfirmPaymentModal(${order.id})" class="px-2 py-0.5 rounded bg-emerald-500 hover:bg-emerald-400 text-gray-950 font-bold text-[10px] shadow transition flex items-center gap-1">
                <i class="fa-solid fa-cash-register"></i> Confirm Pay
              </button>
            ` : ''}
            <span class="text-[10px] text-gray-400 group-hover:text-amber-400 font-semibold transition">Open in POS &rarr;</span>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

async function selectOrderFromModal(orderId) {
  closeActiveOrdersModal();
  const order = activeOrders.find(o => o.id === orderId);
  if (!order) return;

  if (order.orderType === 'TAKEAWAY' || Boolean(order.takeawayToken)) {
    await selectTakeawayOrder(order.id);
  } else if (order.orderType === 'OUTDOOR' || Boolean(order.outdoorToken)) {
    await selectOutdoorOrder(order.id);
  } else {
    await switchTableSelection(order.tableNumber);
  }
}

async function switchTableSelection(tableNo) {
  isCartDirty = false;
  await setOrderLocationMode('TABLE');
  loadTableOptions(tableNo);
  syncTableOrderState(tableNo);
  renderTableBadges();
  renderOutdoorBadges();
  renderMobileTableControls();

  if (pendingDishToAddAfterTableSelect) {
    const dishId = pendingDishToAddAfterTableSelect;
    pendingDishToAddAfterTableSelect = null;
    const dish = menuItems.find(m => m.id === dishId);
    addToCart(dishId);
    if (dish && tableNo) {
      showToast(`Added "${dish.name}" to ${tableNo}`, 'success');
    }
  }
}

function syncTableOrderState(tableNo) {
  const statusBadge = document.getElementById('orderStatusBadge');
  const refNo = document.getElementById('currentBillRefNo');
  const btnPayPrint = document.getElementById('btnPayAndPrint');
  const payModeSection = document.getElementById('payModeSection');
  const staffContainer = document.getElementById('orderStaffContainer');
  const staffNameEl = document.getElementById('orderStaffName');

  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  const isOutdoor = currentOrderLocation === 'OUTDOOR';
  const isTakeaway = currentOrderLocation === 'TAKEAWAY';

  if (isTakeaway) {
    // Handling Takeaway Order State
    const order = currentTableOrder;
    if (order) {
      if (refNo) refNo.textContent = `Ref: ${order.billNumber} • ${order.takeawayToken || 'TAK'}`;
      if (staffContainer && staffNameEl) {
        staffNameEl.textContent = order.createdByName || 'Staff';
        staffContainer.classList.remove('hidden');
      }
      if (statusBadge) {
        statusBadge.classList.remove('hidden');
        if (order.status === 'KOT_REQUESTED') {
          statusBadge.textContent = 'KOT REQUESTED';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-orange-500/20 text-orange-400 border border-orange-500/30';
        } else if (order.status === 'KOT_PRINTED') {
          statusBadge.textContent = 'PACKING';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-cyan-500/20 text-cyan-400 border border-cyan-500/30';
        } else if (order.status === 'BILL_REQUESTED') {
          statusBadge.textContent = 'BILL REQUESTED';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-purple-500/20 text-purple-400 border border-purple-500/30';
        } else if (order.status === 'BILL_PRINTED') {
          statusBadge.textContent = 'PENDING PAYMENT';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/40 animate-pulse';
        } else {
          statusBadge.textContent = 'TAKEAWAY ACTIVE';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-400 border border-amber-500/30';
        }
      }

      if (order.status === 'BILL_PRINTED') {
        cart = [];
        isCartDirty = false;
      } else if (!isCartDirty) {
        const custInput = document.getElementById('cartCustomer');
        if (custInput) custInput.value = order.customerName || '';
        const notesInput = document.getElementById('cartOrderNotes');
        if (notesInput) {
          let clean = (order.notes || '').replace(/^(Takeaway Order|Outdoor Order|Table Order|POS Order|Kitchen Order Ticket)(:\s*)?/i, '');
          notesInput.value = clean.trim();
        }

        cart = (order.items || []).map(it => {
          const matchedMenu = menuItems.find(m => m.id === it.menuItemId);
          return {
            item: matchedMenu || { id: it.menuItemId, name: it.itemName, price: it.price, isVeg: true },
            quantity: it.quantity,
            customization: it.customization || '',
            isTakeaway: it.isTakeaway != null ? Boolean(it.isTakeaway) : true
          };
        });
      }
    } else {
      if (refNo) refNo.textContent = '';
      if (statusBadge) statusBadge.classList.add('hidden');
      if (staffContainer) staffContainer.classList.add('hidden');
      if (!isCartDirty) {
        cart = [];
        const custInput = document.getElementById('cartCustomer');
        if (custInput) custInput.value = '';
        const notesInput = document.getElementById('cartOrderNotes');
        if (notesInput) notesInput.value = '';
      }
    }
  } else if (isOutdoor) {
    // Handling Outdoor Order State
    const order = currentTableOrder;
    if (order) {
      if (refNo) refNo.textContent = `Ref: ${order.billNumber} • ${order.outdoorToken || 'OUT'}`;
      if (staffContainer && staffNameEl) {
        staffNameEl.textContent = order.createdByName || 'Staff';
        staffContainer.classList.remove('hidden');
      }
      if (statusBadge) {
        statusBadge.classList.remove('hidden');
        if (order.status === 'KOT_REQUESTED') {
          statusBadge.textContent = 'KOT REQUESTED';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-orange-500/20 text-orange-400 border border-orange-500/30';
        } else if (order.status === 'KOT_PRINTED') {
          statusBadge.textContent = 'PREPARING';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-cyan-500/20 text-cyan-400 border border-cyan-500/30';
        } else if (order.status === 'BILL_REQUESTED') {
          statusBadge.textContent = 'BILL REQUESTED';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-purple-500/20 text-purple-400 border border-purple-500/30';
        } else if (order.status === 'BILL_PRINTED') {
          statusBadge.textContent = 'PENDING PAYMENT';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/40 animate-pulse';
        } else {
          statusBadge.textContent = 'OUTDOOR ACTIVE';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30';
        }
      }

      if (order.status === 'BILL_PRINTED') {
        cart = [];
        isCartDirty = false;
      } else if (!isCartDirty) {
        const custInput = document.getElementById('cartCustomer');
        if (custInput) custInput.value = order.customerName || '';
        const notesInput = document.getElementById('cartOrderNotes');
        if (notesInput) {
          let clean = (order.notes || '').replace(/^(Takeaway Order|Outdoor Order|Table Order|Outdoor POS Order|POS Order|Outdoor Kitchen Order|Kitchen Order Ticket)(:\s*)?/i, '');
          notesInput.value = clean.trim();
        }

        cart = (order.items || []).map(it => {
          const matchedMenu = menuItems.find(m => m.id === it.menuItemId);
          return {
            item: matchedMenu || { id: it.menuItemId, name: it.itemName, price: it.price, isVeg: true },
            quantity: it.quantity,
            customization: it.customization || '',
            isTakeaway: Boolean(it.isTakeaway)
          };
        });
      }
    } else {
      if (refNo) refNo.textContent = '';
      if (statusBadge) statusBadge.classList.add('hidden');
      if (staffContainer) staffContainer.classList.add('hidden');
      if (!isCartDirty) {
        cart = [];
        const custInput = document.getElementById('cartCustomer');
        if (custInput) custInput.value = '';
        const notesInput = document.getElementById('cartOrderNotes');
        if (notesInput) notesInput.value = '';
      }
    }
  } else {
    // Handling Table Order State
    if (!tableNo) {
      currentTableOrder = null;
      if (refNo) refNo.textContent = '';
      if (statusBadge) statusBadge.classList.add('hidden');
      if (staffContainer) staffContainer.classList.add('hidden');
      if (!isCartDirty) {
        cart = [];
        const custInput = document.getElementById('cartCustomer');
        if (custInput) custInput.value = '';
        const notesInput = document.getElementById('cartOrderNotes');
        if (notesInput) notesInput.value = '';
      }
      if (!isManagerOrAdmin) {
        if (payModeSection) payModeSection.classList.add('hidden');
        if (btnPayPrint) btnPayPrint.classList.add('hidden');
      } else {
        if (payModeSection) payModeSection.classList.remove('hidden');
        if (btnPayPrint) btnPayPrint.classList.remove('hidden');
      }
      renderCart();
      return;
    }

    const order = activeOrders.find(o => o.tableNumber === tableNo);
    currentTableOrder = order || null;

    if (order) {
      if (refNo) refNo.textContent = `Ref: ${order.billNumber}`;
      if (staffContainer && staffNameEl) {
        staffNameEl.textContent = order.createdByName || 'Staff';
        staffContainer.classList.remove('hidden');
      }
      if (statusBadge) {
        statusBadge.classList.remove('hidden');
        if (order.status === 'KOT_REQUESTED') {
          statusBadge.textContent = 'KOT REQUESTED';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-orange-500/20 text-orange-400 border border-orange-500/30';
        } else if (order.status === 'KOT_PRINTED') {
          statusBadge.textContent = 'KOT PRINTED (PREPARING)';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-cyan-500/20 text-cyan-400 border border-cyan-500/30';
        } else if (order.status === 'BILL_REQUESTED') {
          statusBadge.textContent = 'BILL REQUESTED';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-purple-500/20 text-purple-400 border border-purple-500/30';
        } else if (order.status === 'BILL_PRINTED') {
          statusBadge.textContent = 'PENDING PAYMENT';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/40 animate-pulse';
        } else {
          statusBadge.textContent = 'OCCUPIED';
          statusBadge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30';
        }
      }

      if (order.status === 'BILL_PRINTED') {
        cart = [];
        isCartDirty = false;
      } else if (!isCartDirty) {
        const custInput = document.getElementById('cartCustomer');
        if (custInput) custInput.value = order.customerName || '';
        const notesInput = document.getElementById('cartOrderNotes');
        if (notesInput) {
          let clean = (order.notes || '').replace(/^(Takeaway Order|Outdoor Order|Table Order|Outdoor POS Order|POS Order|Outdoor Kitchen Order|Kitchen Order Ticket)(:\s*)?/i, '');
          notesInput.value = clean.trim();
        }

        cart = (order.items || []).map(it => {
          const matchedMenu = menuItems.find(m => m.id === it.menuItemId);
          return {
            item: matchedMenu || { id: it.menuItemId, name: it.itemName, price: it.price, isVeg: true },
            quantity: it.quantity,
            customization: it.customization || '',
            isTakeaway: Boolean(it.isTakeaway)
          };
        });
      }
    } else {
      if (refNo) refNo.textContent = '';
      if (statusBadge) statusBadge.classList.add('hidden');
      if (staffContainer) staffContainer.classList.add('hidden');
      if (!isCartDirty) {
        cart = [];
        const custInput = document.getElementById('cartCustomer');
        if (custInput) custInput.value = '';
        const notesInput = document.getElementById('cartOrderNotes');
        if (notesInput) notesInput.value = '';
      }
    }
  }

  // Adjust Manager vs Staff UI visibility
  const btnAddTableTop = document.getElementById('btnAddTableTop');
  const btnManageTablesTop = document.getElementById('btnManageTablesTop');
  const btnAddTableCart = document.getElementById('btnAddTableCart');
  const btnDeleteTableCart = document.getElementById('btnDeleteTableCart');

  const cartDiscountWrapper = document.getElementById('cartDiscountWrapper');
  const cartGstWrapper = document.getElementById('cartGstWrapper');
  const cartStaffTaxWrapper = document.getElementById('cartStaffTaxWrapper');
  const cartStaffDiscountWrapper = document.getElementById('cartStaffDiscountWrapper');
  const cartDiscountPct = document.getElementById('cartDiscountPct');
  const cartGstSelect = document.getElementById('cartGstSelect');

  if (!isManagerOrAdmin) {
    if (payModeSection) payModeSection.classList.add('hidden');
    if (btnPayPrint) btnPayPrint.classList.add('hidden');
    if (btnAddTableTop) btnAddTableTop.classList.add('hidden');
    if (btnManageTablesTop) btnManageTablesTop.classList.add('hidden');
    if (btnAddTableCart) btnAddTableCart.classList.add('hidden');
    if (btnDeleteTableCart) btnDeleteTableCart.classList.add('hidden');

    // Remove GST and discount controls from staff interface
    if (cartDiscountWrapper) cartDiscountWrapper.classList.add('hidden');
    if (cartGstWrapper) cartGstWrapper.classList.add('hidden');
    if (cartStaffTaxWrapper) cartStaffTaxWrapper.classList.remove('hidden');
    if (cartDiscountPct) {
      cartDiscountPct.disabled = true;
      cartDiscountPct.value = 0;
    }
    if (cartGstSelect) cartGstSelect.disabled = true;

    // If order already has a manager-applied discount, show read-only indicator
    if (currentTableOrder && currentTableOrder.discountPercent && currentTableOrder.discountPercent > 0) {
      if (cartStaffDiscountWrapper) {
        cartStaffDiscountWrapper.classList.remove('hidden');
        const staffDiscVal = document.getElementById('cartStaffDiscount');
        if (staffDiscVal) staffDiscVal.textContent = `${currentTableOrder.discountPercent}%`;
      }
    } else {
      if (cartStaffDiscountWrapper) cartStaffDiscountWrapper.classList.add('hidden');
    }
  } else {
    if (payModeSection) payModeSection.classList.remove('hidden');
    if (btnPayPrint) btnPayPrint.classList.remove('hidden');
    if (btnAddTableTop) btnAddTableTop.classList.remove('hidden');
    if (btnManageTablesTop) btnManageTablesTop.classList.remove('hidden');
    if (btnAddTableCart) btnAddTableCart.classList.remove('hidden');
    if (btnDeleteTableCart) {
      if (!isOutdoor && tableNo) btnDeleteTableCart.classList.remove('hidden');
      else btnDeleteTableCart.classList.add('hidden');
    }

    // Keep Manager and Admin controls fully available
    if (cartDiscountWrapper) cartDiscountWrapper.classList.remove('hidden');
    if (cartGstWrapper) cartGstWrapper.classList.remove('hidden');
    if (cartStaffTaxWrapper) cartStaffTaxWrapper.classList.add('hidden');
    if (cartStaffDiscountWrapper) cartStaffDiscountWrapper.classList.add('hidden');
    if (cartDiscountPct) {
      cartDiscountPct.disabled = false;
      if (currentTableOrder && currentTableOrder.discountPercent != null) {
        cartDiscountPct.value = currentTableOrder.discountPercent;
      }
    }
    if (cartGstSelect) cartGstSelect.disabled = false;
  }

  // Handle Pending Payment banner vs standard action buttons
  const posStdActions = document.getElementById('posStandardActionButtons');
  const posPendingContainer = document.getElementById('posPendingPaymentContainer');
  const pendingDetailsEl = document.getElementById('pendingPaymentOrderDetails');
  const pendingAmountEl = document.getElementById('pendingPaymentAmount');
  const pendingMgrActions = document.getElementById('pendingPaymentManagerActions');
  const pendingStaffNotice = document.getElementById('pendingPaymentStaffNotice');

  if (currentTableOrder && currentTableOrder.status === 'BILL_PRINTED') {
    if (posStdActions) posStdActions.classList.add('hidden');
    if (payModeSection) payModeSection.classList.add('hidden');
    if (posPendingContainer) {
      posPendingContainer.classList.remove('hidden');
      if (pendingDetailsEl) {
        pendingDetailsEl.textContent = isOutdoor
          ? `Outdoor • ${escapeHtml(currentTableOrder.customerName || 'Guest')} (${escapeHtml(currentTableOrder.outdoorToken || 'OUT')}) • Bill #${currentTableOrder.billNumber}`
          : `Table ${currentTableOrder.tableNumber} • Bill #${currentTableOrder.billNumber}`;
      }
      if (pendingAmountEl) {
        pendingAmountEl.textContent = `₹${(currentTableOrder.netAmount || 0).toFixed(2)}`;
      }
      if (isManagerOrAdmin) {
        if (pendingMgrActions) pendingMgrActions.classList.remove('hidden');
        if (pendingStaffNotice) pendingStaffNotice.classList.add('hidden');
      } else {
        if (pendingMgrActions) pendingMgrActions.classList.add('hidden');
        if (pendingStaffNotice) pendingStaffNotice.classList.remove('hidden');
      }
    }
  } else {
    if (posStdActions) posStdActions.classList.remove('hidden');
    if (posPendingContainer) posPendingContainer.classList.add('hidden');
  }

  const parcelInp = document.getElementById('cartParcelChargeInput');
  if (parcelInp && !isCartDirty) {
    if (currentTableOrder && currentTableOrder.parcelCharge != null && !isNaN(Number(currentTableOrder.parcelCharge))) {
      parcelInp.value = Number(currentTableOrder.parcelCharge).toFixed(2);
    } else {
      parcelInp.value = (defaultParcelCharge || 10).toFixed(2);
    }
  }

  renderCart();
  updateKotButtonState();
}

async function saveTableOrder() {
  const isOutdoor = currentOrderLocation === 'OUTDOOR';
  const isTakeaway = currentOrderLocation === 'TAKEAWAY';
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  let tableNo = null;
  let customer = (document.getElementById('cartCustomer')?.value || '').trim();

  if (!isOutdoor && !isTakeaway) {
    tableNo = document.getElementById('cartTableNo')?.value?.trim();
    if (!tableNo) {
      showToast('Please select a table.', 'error');
      document.getElementById('cartTableNo')?.focus();
      return;
    }
  } else if (isOutdoor) {
    if (!customer) {
      showToast('Customer name is required for outdoor orders.', 'error');
      document.getElementById('cartCustomer')?.focus();
      return;
    }
  }

  if (cart.length === 0) {
    showToast('Add at least one item to save the order', 'error');
    return;
  }

  if (isSavingOrder) return;

  if (!hasOrderChanges()) {
    showToast('Order is already saved. No changes to save.', 'info');
    updateKotButtonState();
    return;
  }

  const customNotes = (document.getElementById('cartOrderNotes')?.value || '').trim();
  const defaultNotes = isTakeaway ? 'Takeaway Order' : (isOutdoor ? 'Outdoor Order' : 'Table Order');
  const orderNotes = customNotes ? `${defaultNotes}: ${customNotes}` : defaultNotes;

  const parcelRow = document.getElementById('cartParcelChargeRow');
  const parcelInput = document.getElementById('cartParcelChargeInput');
  let parcelChargeVal = null;
  if (parcelRow && !parcelRow.classList.contains('hidden') && parcelInput) {
    const parsed = parseFloat(parcelInput.value);
    if (!isNaN(parsed) && parsed >= 0) parcelChargeVal = parsed;
  }

  const payload = {
    orderId: currentTableOrder?.id || null,
    orderType: isTakeaway ? 'TAKEAWAY' : (isOutdoor ? 'OUTDOOR' : 'TABLE'),
    tableNumber: (isOutdoor || isTakeaway) ? null : tableNo,
    customerName: customer || (isTakeaway ? 'Guest' : ''),
    outdoorToken: isOutdoor ? (currentTableOrder?.outdoorToken || null) : null,
    takeawayToken: isTakeaway ? (currentTableOrder?.takeawayToken || null) : null,
    notes: orderNotes,
    parcelCharge: parcelChargeVal,
    items: cart.map(({ item, quantity, customization, isTakeaway: itemTakeaway }) => ({
      menuItemId: item.id,
      itemName: item.name,
      quantity,
      price: item.price,
      customization: (customization || '').trim(),
      isTakeaway: isTakeaway ? true : Boolean(itemTakeaway)
    }))
  };

  // Only manager and admin can set or change discount and GST
  if (isManagerOrAdmin) {
    const discountPct = parseFloat(document.getElementById('cartDiscountPct')?.value || 0);
    if (!isNaN(discountPct) && discountPct >= 0) {
      payload.discountPercent = discountPct;
    }
    let gstPct = 0;
    const gstSel = document.getElementById('cartGstSelect')?.value || '0';
    if (gstSel === 'custom') {
      gstPct = parseFloat(document.getElementById('cartGstCustom')?.value || 0);
    } else {
      gstPct = parseFloat(gstSel);
    }
    if (!isNaN(gstPct) && gstPct >= 0) {
      const isGstEnabled = Boolean(currentGstConfig && currentGstConfig.enabled && gstPct > 0);
      payload.gstEnabled = isGstEnabled;
      payload.taxPercent = isGstEnabled ? gstPct : 0.0;
      payload.cgstPercent = isGstEnabled ? ((currentGstConfig && currentGstConfig.cgstPercent != null) ? currentGstConfig.cgstPercent : (gstPct / 2.0)) : 0.0;
      payload.sgstPercent = isGstEnabled ? ((currentGstConfig && currentGstConfig.sgstPercent != null) ? currentGstConfig.sgstPercent : (gstPct / 2.0)) : 0.0;
    }
  }

  isSavingOrder = true;
  const saveBtn = document.getElementById('btnSaveTableOrder');
  const originalSaveBtnContent = saveBtn ? saveBtn.innerHTML : '';
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> <span>SAVING...</span>';
  }
  updateKotButtonState();

  try {
    const saved = await apiRequest('/bills/order', {
      method: 'POST',
      body: JSON.stringify(payload)
    });
    currentTableOrder = saved;
    if (isTakeaway) {
      currentTakeawayToken = saved.takeawayToken;
      const tokenDisp = document.getElementById('cartTakeawayTokenDisplay');
      if (tokenDisp && saved.takeawayToken) tokenDisp.textContent = saved.takeawayToken;
    } else if (isOutdoor) {
      currentOutdoorToken = saved.outdoorToken;
      const tokenDisp = document.getElementById('cartOutdoorTokenDisplay');
      if (tokenDisp && saved.outdoorToken) tokenDisp.textContent = saved.outdoorToken;
    }
    // Sync cart with saved items to ensure exact match and clear dirty state
    if (saved.items && saved.items.length > 0) {
      cart = saved.items.map(it => {
        const matchedMenu = menuItems.find(m => m.id === it.menuItemId);
        return {
          item: matchedMenu || { id: it.menuItemId, name: it.itemName, price: it.price, isVeg: true },
          quantity: it.quantity,
          customization: it.customization || '',
          isTakeaway: it.isTakeaway != null ? Boolean(it.isTakeaway) : (isTakeaway ? true : false)
        };
      });
    }
    isCartDirty = false;
    const identifier = isTakeaway
      ? `Takeaway ${saved.takeawayToken || 'TAK'}`
      : (isOutdoor ? `${saved.customerName} • ${saved.outdoorToken || 'OUT'}` : `Table ${saved.tableNumber}`);
    showToast(`Order for ${identifier} saved successfully! (Ref #${saved.billNumber})`, 'success');
    syncTableOrderState(isTakeaway || isOutdoor ? '' : saved.tableNumber);
    updateKotButtonState();
    // The save response already holds the full order, so the buttons are usable immediately. The fresh table and
    // active-order data is fetched in the background and re-synced afterwards (only if the same order is still open).
    refreshActiveOrders().then(() => {
      if (!currentTableOrder || currentTableOrder.id !== saved.id) return;
      if (!isOutdoor && !isTakeaway && saved.tableNumber) {
        syncTableOrderState(saved.tableNumber);
      } else if (isOutdoor || isTakeaway) {
        syncTableOrderState('');
      }
      updateKotButtonState();
    }).catch(() => { /* non-fatal: the live stream / next refresh will catch up */ });
  } catch (err) {
    showToast('Failed to save order: ' + err.message, 'error');
  } finally {
    isSavingOrder = false;
    if (saveBtn && originalSaveBtnContent) {
      saveBtn.innerHTML = originalSaveBtnContent;
    }
    updateKotButtonState();
  }
}

async function requestKitchenTicket() {
  const isOutdoor = currentOrderLocation === 'OUTDOOR';
  const isTakeaway = currentOrderLocation === 'TAKEAWAY';
  let tableNo = null;
  let customer = (document.getElementById('cartCustomer')?.value || '').trim();

  if (!isOutdoor && !isTakeaway) {
    tableNo = document.getElementById('cartTableNo')?.value?.trim();
    if (!tableNo) {
      showToast('Please select a table.', 'error');
      document.getElementById('cartTableNo')?.focus();
      return;
    }
  } else if (isOutdoor) {
    if (!customer) {
      showToast('Customer name is required for outdoor orders.', 'error');
      document.getElementById('cartCustomer')?.focus();
      return;
    }
  }

  if (cart.length === 0) {
    showToast('Add dishes before sending to kitchen', 'error');
    return;
  }

  // Multi-click prevention guard
  if (isSendingKot || isSavingOrder) return;

  // Order must be saved before sending to kitchen
  if (!currentTableOrder || !currentTableOrder.id) {
    showToast('Please click SAVE ORDER first before sending dishes to kitchen', 'warning');
    updateKotButtonState();
    return;
  }

  // If order has unsaved changes, user must save first
  if (hasOrderChanges() || isCartDirty) {
    showToast('Please click SAVE ORDER first before sending new dishes to kitchen', 'warning');
    updateKotButtonState();
    return;
  }

  // If order already requested to kitchen, prevent sending again
  if (currentTableOrder.status === 'KOT_REQUESTED') {
    showToast('Kitchen ticket has already been sent to kitchen and is awaiting print', 'warning');
    updateKotButtonState();
    return;
  }

  if (currentTableOrder.status === 'BILL_REQUESTED' || currentTableOrder.status === 'BILL_PRINTED' || currentTableOrder.status === 'PAID') {
    showToast('Cannot send to kitchen: Order is already billed or completed.', 'warning');
    updateKotButtonState();
    return;
  }

  // If order exists and all items have already been printed:
  const hasUnprinted = (currentTableOrder.items || []).some(it => {
    const printed = it.printedQuantity || 0;
    return (it.quantity || 0) > printed;
  });
  const hasKotChanges = Boolean(currentTableOrder.kotLastChanges && currentTableOrder.kotLastChanges.trim());
  if (!hasUnprinted && !hasKotChanges) {
    showToast('All items have already been printed. Add or modify dishes and click SAVE ORDER to send more.', 'warning');
    updateKotButtonState();
    return;
  }

  isSendingKot = true;
  const kotBtn = document.getElementById('btnSendToKitchen');
  const originalKotBtnContent = kotBtn ? kotBtn.innerHTML : '';
  if (kotBtn) {
    kotBtn.disabled = true;
    kotBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> <span>SENDING...</span>';
  }
  updateKotButtonState();

  try {
    const targetOrder = currentTableOrder;
    // Send and print KOT immediately without waiting for manager approval
    const updated = await apiRequest(`/bills/${targetOrder.id}/print-kot`, { method: 'POST' });
    currentTableOrder = updated;
    const targetLabel = (targetOrder.orderType === 'TAKEAWAY' || targetOrder.takeawayToken)
      ? `Takeaway ${targetOrder.takeawayToken || 'TAK'}`
      : ((targetOrder.orderType === 'OUTDOOR' || targetOrder.outdoorToken) ? `${targetOrder.customerName} • ${targetOrder.outdoorToken || 'OUT'}` : `Table ${tableNo}`);
    showToast(`Kitchen Ticket sent for ${targetLabel} (Ref #${updated.kotNumber || targetOrder.billNumber})`, 'success');
    displayKotReceiptModal(updated);
    await refreshActiveOrders();
    syncTableOrderState(isTakeaway || isOutdoor ? '' : tableNo);

    // Trigger resilient print queue / bridge for KOT with idempotency key to prevent duplicates
    const idempotencyKey = `KOT_${updated.id}_v${updated.kotUpdateCount || 0}`;
    apiRequest(`/printer/print-kot/${updated.id}`, {
      method: 'POST',
      headers: { 'Idempotency-Key': idempotencyKey }
    }).then(res => {
      if (res && res.jobId) {
        trackPrintJobStatus(res.jobId, res.status, `KOT #${updated.kotNumber || updated.billNumber}`);
      } else if (res && res.success) {
        showToast(`KOT sent to printer (${res.host})`, 'success');
      }
    }).catch(err => {
      console.warn('KOT background print warning:', err);
    });
  } catch (err) {
    showToast('Failed to send order to kitchen: ' + err.message, 'error');
  } finally {
    isSendingKot = false;
    if (kotBtn && originalKotBtnContent) {
      kotBtn.innerHTML = originalKotBtnContent;
    }
    updateKotButtonState();
  }
}

async function requestFinalBill() {
  const isOutdoor = currentOrderLocation === 'OUTDOOR';
  const isTakeaway = currentOrderLocation === 'TAKEAWAY';
  if (!isOutdoor && !isTakeaway) {
    const tableNo = document.getElementById('cartTableNo')?.value?.trim();
    if (!tableNo) {
      showToast('Please select a table.', 'error');
      document.getElementById('cartTableNo')?.focus();
      return;
    }
  } else if (isOutdoor) {
    const cust = (document.getElementById('cartCustomer')?.value || '').trim();
    if (!cust) {
      showToast('Customer name is required for outdoor orders.', 'error');
      return;
    }
  }

  if (!currentTableOrder) {
    showToast('No active saved order found', 'error');
    return;
  }

  if (currentTableOrder.status === 'BILL_REQUESTED') {
    showToast('Bill has already been requested from manager', 'info');
    return;
  }

  if (currentTableOrder.status !== 'KOT_PRINTED' || !currentTableOrder.kotPrintedAt) {
    if (currentTableOrder.status === 'KOT_REQUESTED') {
      showToast('Kitchen ticket requested. Print KOT before bill can be requested.', 'warning');
    } else {
      showToast('Order must be sent to kitchen and KOT printed before requesting bill.', 'warning');
    }
    return;
  }

  const hasUnprinted = (currentTableOrder.items || []).some(it => {
    const printed = it.printedQuantity || 0;
    return (it.quantity || 0) > printed;
  });
  if (hasUnprinted || isCartDirty) {
    showToast('There are unprinted dishes in this order. Save and send to kitchen first.', 'warning');
    return;
  }

  try {
    const res = await apiRequest(`/bills/${currentTableOrder.id}/request-bill`, { method: 'POST' });
    const locLabel = (res.orderType === 'TAKEAWAY' || res.takeawayToken)
      ? `Takeaway ${res.takeawayToken || 'TAK'}`
      : ((res.orderType === 'OUTDOOR' || res.outdoorToken) ? `${res.customerName} • ${res.outdoorToken}` : `Table ${res.tableNumber}`);
    showToast(`Bill requested from Manager for ${locLabel} (Bill #${res.billNumber})`, 'success');
    await refreshActiveOrders();
  } catch (err) {
    showToast('Failed to request bill: ' + err.message, 'error');
  }
}

// ============================================================
// ESC/POS DIRECT THERMAL PRINTER & RESILIENT PRINT QUEUE
// ============================================================
let activeReceiptBill = null;
let activeKotBill = null;
let currentPrinterConfig = null;

async function trackPrintJobStatus(jobId, initialStatus, printLabel = 'Print job') {
  if (!jobId) return;
  if (initialStatus === 'COMPLETED') {
    showToast(`${printLabel} printed successfully!`, 'success');
    return;
  }

  showToast(`${printLabel} queued for printing (${jobId.slice(0, 8)})...`, 'info');

  let attempts = 0;
  const maxPolls = 10;
  let pollInterval = null;

  const checkStatus = async () => {
    attempts++;
    try {
      const statusRes = await apiRequest(`/printer/jobs/${jobId}/status`);
      if (!statusRes) return false;

      if (statusRes.status === 'COMPLETED') {
        if (pollInterval) clearInterval(pollInterval);
        showToast(`${printLabel} printed successfully!`, 'success');
        return true;
      } else if (statusRes.status === 'NEEDS_REVIEW') {
        if (pollInterval) clearInterval(pollInterval);
        showToast(`${printLabel} needs review (printer issue or uncertain delivery)`, 'warning');
        return true;
      } else if (statusRes.status === 'FAILED') {
        if (pollInterval) clearInterval(pollInterval);
        showToast(`${printLabel} failed: ${statusRes.lastErrorMessage || 'Check printer connection'}`, 'error');
        return true;
      } else if (attempts >= maxPolls) {
        if (pollInterval) clearInterval(pollInterval);
        console.log(`[PRINT-JOB ${jobId}] Still queued (${statusRes.status}). Print queue will deliver it.`);
        return true;
      }
    } catch (e) {
      if (attempts >= maxPolls && pollInterval) clearInterval(pollInterval);
    }
    return false;
  };

  // Immediate check at 350ms, then 750ms for low-latency feedback
  setTimeout(async () => {
    const done = await checkStatus();
    if (!done) {
      setTimeout(async () => {
        const done2 = await checkStatus();
        if (!done2) {
          pollInterval = setInterval(checkStatus, 1200);
        }
      }, 400);
    }
  }, 350);
}


function displayKotReceiptModal(bill) {
  activeKotBill = bill;

  const isUpdatedKot = (bill.kotNoticeType === 'UPDATED' || (bill.kotUpdateCount && bill.kotUpdateCount > 0))
    && (bill.latestKotItems && bill.latestKotItems.length > 0 && bill.latestKotItems.some(it => it.updateType));

  // Bind KOT header, subheader, and footer from active printer config
  const kotTitleEl = document.getElementById('kotRcptTitle');
  if (kotTitleEl) {
    if (isUpdatedKot) {
      kotTitleEl.textContent = `*** KITCHEN ORDER (UPDATE #${bill.kotUpdateCount || 1}) ***`;
    } else {
      kotTitleEl.textContent = currentPrinterConfig?.kotHeaderTitle || '*** KITCHEN ORDER ***';
    }
  }

  const noticeBannerEl = document.getElementById('kotRcptNoticeBanner');
  if (noticeBannerEl) {
    if (isUpdatedKot) {
      noticeBannerEl.classList.remove('hidden');
    } else {
      noticeBannerEl.classList.add('hidden');
    }
  }

  const colDescEl = document.getElementById('kotRcptColDesc');
  if (colDescEl) colDescEl.textContent = isUpdatedKot ? 'UPDATED ITEM' : 'ITEM DESCRIPTION';

  const colQtyEl = document.getElementById('kotRcptColQty');
  if (colQtyEl) colQtyEl.textContent = isUpdatedKot ? 'CHANGE' : 'QTY';

  const totalLabelEl = document.getElementById('kotRcptTotalLabel');
  if (totalLabelEl) totalLabelEl.textContent = isUpdatedKot ? 'TOTAL UPDATED ITEMS:' : 'TOTAL ITEMS / QTY:';

  const kotSubEl = document.getElementById('kotRcptSubTitle');
  if (kotSubEl) kotSubEl.textContent = currentPrinterConfig?.kotSubheader || 'NERAM - MAIN KITCHEN';

  const kotFooterEl = document.getElementById('kotRcptFooterMsg');
  if (kotFooterEl) kotFooterEl.textContent = currentPrinterConfig?.kotFooterMessage || '--- END OF KOT ---';

  const refNumber = bill.kotNumber || bill.billNumber || 'NRM-0000';
  const billNoEl = document.getElementById('kotRcptBillNo');
  if (billNoEl) billNoEl.textContent = `REF: ${refNumber}`;

  const isOutdoor = bill.orderType === 'OUTDOOR' || Boolean(bill.outdoorToken);
  const isOrderTakeaway = bill.orderType === 'TAKEAWAY' || Boolean(bill.takeawayToken);
  const tableBannerEl = document.getElementById('kotRcptTableBanner');
  if (tableBannerEl) {
    if (isOrderTakeaway) {
      tableBannerEl.innerHTML = `
        <div class="font-black text-xs tracking-wider uppercase text-black">TAKEAWAY &bull; TOKEN: ${escapeHtml(bill.takeawayToken || 'TAK')}</div>
        <div class="text-[10px] font-bold text-gray-800 mt-0.5">Guest: ${escapeHtml(bill.customerName || 'Takeaway Guest')}</div>
      `;
    } else if (isOutdoor) {
      tableBannerEl.innerHTML = `
        <div class="font-black text-xs tracking-wider uppercase text-black">OUTDOOR &bull; TOKEN: ${escapeHtml(bill.outdoorToken || 'OUT')}</div>
        <div class="text-[10px] font-bold text-gray-800 mt-0.5">Guest: ${escapeHtml(bill.customerName || 'Guest')}</div>
      `;
    } else {
      tableBannerEl.innerHTML = `<span id="kotRcptTableNo" class="font-black text-[15px] tracking-widest uppercase text-black">TABLE: ${escapeHtml(bill.tableNumber || 'Takeaway')}</span>`;
    }
  }

  const dateEl = document.getElementById('kotRcptDate');
  if (dateEl) dateEl.textContent = formatISTDateTime(bill.createdAt || new Date());

  const serverEl = document.getElementById('kotRcptServer');
  if (serverEl) serverEl.textContent = `Server: ${bill.createdByName || (currentUser ? currentUser.username : 'Staff')}`;

  const orderRefEl = document.getElementById('kotRcptOrderRef');
  if (orderRefEl) {
    const parts = refNumber.split('-');
    const shortRef = parts.length > 1 ? '#' + parts[parts.length - 1] : '';
    orderRefEl.textContent = shortRef ? `Order ${shortRef}` : '';
  }

  const tbody = document.getElementById('kotRcptItemsBody');
  // If incremental KOT items exist, print only the updated items
  const itemsToPrint = (bill.latestKotItems && bill.latestKotItems.length > 0) ? bill.latestKotItems : (bill.items || []);
  let totalKotCount = itemsToPrint.length;
  let totalKotQty = 0;
  tbody.innerHTML = itemsToPrint.map(it => {
    const qty = it.quantity || 1;
    let badgeHtml = '';
    let itemStyle = '';
    let updateMsgHtml = '';

    if (it.updateType === 'ADDED' || it.updateType === 'INCREASED') {
      const delta = it.deltaQuantity || qty;
      totalKotQty += delta;
      badgeHtml = `<span class="kot-badge font-black text-black border border-black">+${delta}</span>`;
      if (it.updateMessage) {
        updateMsgHtml = `<div class="text-[10.5px] font-black text-emerald-800 mt-0.5">${escapeHtml(it.updateMessage)}</div>`;
      }
    } else if (it.updateType === 'DECREASED') {
      const delta = it.deltaQuantity || qty;
      badgeHtml = `<span class="kot-badge font-black text-rose-700 border border-rose-500">${delta}</span>`;
      if (it.updateMessage) {
        updateMsgHtml = `<div class="text-[10.5px] font-black text-rose-700 mt-0.5">${escapeHtml(it.updateMessage)}</div>`;
      }
    } else if (it.updateType === 'REMOVED') {
      itemStyle = 'text-decoration: line-through; color: #b91c1c;';
      badgeHtml = `<span class="kot-badge font-black text-rose-700 border border-rose-500 text-[10px]">CANCEL</span>`;
      if (it.updateMessage) {
        updateMsgHtml = `<div class="text-[10.5px] font-black text-rose-700 mt-0.5">${escapeHtml(it.updateMessage)}</div>`;
      }
    } else if (it.updateType === 'NOTE_UPDATED') {
      badgeHtml = `<span class="kot-badge font-black text-blue-700 border border-blue-500 text-[10px]">NOTE</span>`;
      if (it.updateMessage) {
        updateMsgHtml = `<div class="text-[10.5px] font-black text-blue-800 mt-0.5">${escapeHtml(it.updateMessage)}</div>`;
      }
    } else {
      totalKotQty += qty;
      badgeHtml = `<span class="kot-badge">${qty}</span>`;
    }

    const custNote = (it.customization && it.customization.trim()) ? it.customization.trim() : '';
    const matchedItem = (bill.items || []).find(b => (b.id && it.id && b.id === it.id) || (b.menuItemId && it.menuItemId && b.menuItemId === it.menuItemId && Boolean(b.isTakeaway)));
    const isItemTakeaway = Boolean(it.isTakeaway) || (matchedItem && Boolean(matchedItem.isTakeaway)) || isOrderTakeaway;
    return `
    <tr class="border-b border-dashed border-gray-400">
      <td class="py-1.5 text-black font-extrabold text-[13px] text-left leading-tight" style="width: 74%; word-break: break-word; ${itemStyle}">
        ${escapeHtml(it.itemName)}
        ${isItemTakeaway ? `<div class="text-[10px] font-black text-black mt-0.5 tracking-tight" style="color: #000 !important; font-weight: 900 !important;"><i class="fa-solid fa-box mr-1"></i>*** [PARCEL / TAKEAWAY PACK] ***</div>` : ''}
        ${updateMsgHtml}
        ${custNote ? `<div class="text-[10px] font-bold text-black italic mt-0.5 pl-1.5 border-l-2 border-black">Note: ${escapeHtml(custNote)}</div>` : ''}
      </td>
      <td class="py-1.5 text-right align-middle" style="width: 26%; padding-right: 2mm;">
        ${badgeHtml}
      </td>
    </tr>
      </td>
    </tr>
  `}).join('');

  const totalEl = document.getElementById('kotRcptTotalQty');
  if (totalEl) {
    if (isUpdatedKot) {
      totalEl.textContent = `${totalKotCount} Item${totalKotCount === 1 ? '' : 's'}`;
    } else {
      totalEl.textContent = `${totalKotCount} Item${totalKotCount === 1 ? '' : 's'} (Qty: ${totalKotQty})`;
    }
  }

  const notesEl = document.getElementById('kotRcptNotes');
  if (notesEl) notesEl.textContent = bill.notes || 'None';

  document.getElementById('kotReceiptModal').classList.remove('hidden');
}

function closeKotReceiptModal() {
  document.getElementById('kotReceiptModal').classList.add('hidden');
  activeKotBill = null;
}

async function directPrintActiveKot() {
  if (!activeKotBill || !activeKotBill.id) {
    showToast('No active KOT selected to print', 'error');
    return;
  }
  const btn = document.getElementById('btnDirectPrintKot');
  const btnText = document.getElementById('btnDirectPrintKotText');
  if (btn) btn.disabled = true;
  if (btnText) btnText.textContent = 'PRINTING...';

  try {
    const idempotencyKey = `KOT_${activeKotBill.id}_v${activeKotBill.kotUpdateCount || 0}`;
    const res = await apiRequest(`/printer/print-kot/${activeKotBill.id}`, {
      method: 'POST',
      headers: { 'Idempotency-Key': idempotencyKey }
    });
    if (res && res.jobId) {
      trackPrintJobStatus(res.jobId, res.status, `KOT #${activeKotBill.kotNumber || activeKotBill.billNumber}`);
    } else if (res && res.success) {
      showToast(`KOT printed directly to thermal printer (${res.host}:${res.port})!`, 'success');
    } else {
      showToast(`Print warning: ${res.message || 'Check printer connection'}`, 'warning');
    }
  } catch (err) {
    showToast('Direct print failed: ' + err.message, 'error');
  } finally {
    if (btn) btn.disabled = false;
    if (btnText) btnText.textContent = 'DIRECT PRINT KOT (THERMAL)';
  }
}

function printElementContent(elementId, title) {
  const srcEl = document.getElementById(elementId);
  if (!srcEl) {
    window.print();
    return;
  }

  // Remove existing print iframe if any
  const existingIframe = document.getElementById('neramPrintIframe');
  if (existingIframe) {
    existingIframe.remove();
  }

  const iframe = document.createElement('iframe');
  iframe.id = 'neramPrintIframe';
  iframe.style.position = 'fixed';
  iframe.style.right = '0';
  iframe.style.bottom = '0';
  iframe.style.width = '0';
  iframe.style.height = '0';
  iframe.style.border = '0';
  document.body.appendChild(iframe);

  const doc = iframe.contentWindow.document;
  doc.open();
  doc.write(`
    <!DOCTYPE html>
    <html>
      <head>
        <title>${title || 'Receipt'}</title>
        <style>
          @page {
            size: 70mm auto;
            margin: 0;
          }
          *, *::before, *::after {
            box-sizing: border-box !important;
          }
          html, body {
            width: 70mm !important;
            max-width: 70mm !important;
            margin: 0 auto !important;
            padding: 2mm 3.5mm 2mm 1.5mm !important;
            background: #fff !important;
            color: #000 !important;
            font-family: 'Outfit', system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
            font-size: 10.5px !important;
            font-weight: 600 !important;
            font-variant-numeric: tabular-nums;
            line-height: 1.25;
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
            overflow-x: hidden !important;
            word-break: break-word;
          }
          table {
            width: 100% !important;
            table-layout: fixed !important;
            border-collapse: collapse;
          }
          th, td {
            padding: 2px 0;
            color: #000 !important;
          }
          .receipt-divider {
            border-top: 1.5px dashed #000;
            margin: 5px 0;
          }
          .kot-badge {
            display: inline-block;
            background: #000 !important;
            color: #fff !important;
            font-weight: 900 !important;
            font-size: 11px !important;
            padding: 1.5px 7px !important;
            border-radius: 4px !important;
            min-width: 24px !important;
            text-align: center !important;
            line-height: 1.3 !important;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
          }
          .kot-table-banner {
            background: #000 !important;
            color: #fff !important;
            padding: 4px 6px !important;
            text-align: center !important;
            border-radius: 4px !important;
            margin: 4px 0 3px 0 !important;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
          }
          .text-center { text-align: center; }
          .text-left { text-align: left; }
          .text-right { text-align: right; }
          .font-bold { font-weight: 700 !important; }
          .font-black { font-weight: 900 !important; }
          .font-extrabold { font-weight: 800 !important; }
          .uppercase { text-transform: uppercase; }
          .flex { display: flex; }
          .justify-between { display: flex; justify-content: space-between; }
          .w-full { width: 100%; }
          .text-gray-600, .text-gray-700, .text-gray-800 { color: #000 !important; }
          img.receipt-logo {
            max-width: 44mm;
            max-height: 16mm;
            object-fit: contain;
            display: block;
            margin: 0 auto 0px auto;
            padding: 0;
            filter: grayscale(100%) contrast(200%);
          }
        </style>
      </head>
      <body>
        ${srcEl.innerHTML}
      </body>
    </html>
  `);
  doc.close();

  // Print iframe once images and content are loaded
  const doPrint = () => {
    try {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
    } catch (e) {
      console.error('Print iframe failed, fallback to window.print():', e);
      window.print();
    }
  };

  const imgs = doc.getElementsByTagName('img');
  if (imgs.length > 0) {
    let loaded = 0;
    let printed = false;
    const checkAllLoaded = () => {
      loaded++;
      if (loaded >= imgs.length && !printed) {
        printed = true;
        setTimeout(doPrint, 100);
      }
    };
    for (let i = 0; i < imgs.length; i++) {
      if (imgs[i].complete) {
        checkAllLoaded();
      } else {
        imgs[i].onload = checkAllLoaded;
        imgs[i].onerror = checkAllLoaded;
      }
    }
    // Fallback timeout in case of hanging image load
    setTimeout(() => {
      if (!printed) {
        printed = true;
        doPrint();
      }
    }, 600);
  } else {
    setTimeout(doPrint, 150);
  }
}

function triggerPrintKotReceipt() {
  printElementContent('thermalKotReceiptContent', 'Kitchen Order Ticket (KOT)');
}

async function submitPrintBillOnly() {
  const isOutdoor = currentOrderLocation === 'OUTDOOR';
  const isTakeaway = currentOrderLocation === 'TAKEAWAY';
  let tableNo = null;
  let customer = (document.getElementById('cartCustomer')?.value || '').trim();

  if (!isOutdoor && !isTakeaway) {
    tableNo = document.getElementById('cartTableNo')?.value?.trim();
    if (!tableNo) {
      showToast('Please select a table.', 'error');
      document.getElementById('cartTableNo')?.focus();
      return;
    }
  } else if (isOutdoor) {
    if (!customer) {
      showToast('Customer name is required for outdoor orders.', 'error');
      document.getElementById('cartCustomer')?.focus();
      return;
    }
  }

  if (!currentTableOrder) {
    showToast('Order must be saved, sent to kitchen, printed by manager, and bill requested before printing.', 'warning');
    return;
  }

  if (currentTableOrder.status !== 'BILL_REQUESTED') {
    if (currentTableOrder.status === 'BILL_PRINTED') {
      showToast('Bill is already printed and awaiting payment confirmation.', 'info');
    } else if (currentTableOrder.status === 'KOT_PRINTED') {
      showToast('Please click REQUEST BILL first before printing bill.', 'warning');
    } else if (currentTableOrder.status === 'KOT_REQUESTED') {
      showToast('KOT must be printed and bill must be requested first.', 'warning');
    } else {
      showToast('Order must be sent to kitchen, KOT printed, and bill requested before printing.', 'warning');
    }
    return;
  }

  const discountPct = parseFloat(document.getElementById('cartDiscountPct')?.value || 0);

  let gstPct = 0;
  const gstSel = document.getElementById('cartGstSelect')?.value || '0';
  if (gstSel === 'custom') {
    gstPct = parseFloat(document.getElementById('cartGstCustom')?.value || 0);
  } else {
    gstPct = parseFloat(gstSel);
  }
  if (isNaN(gstPct) || gstPct < 0) gstPct = 0;

  const isGstEnabled = Boolean(currentGstConfig && currentGstConfig.enabled && gstPct > 0);
  const cgstRate = isGstEnabled ? ((currentGstConfig && currentGstConfig.cgstPercent != null) ? currentGstConfig.cgstPercent : (gstPct / 2.0)) : 0.0;
  const sgstRate = isGstEnabled ? ((currentGstConfig && currentGstConfig.sgstPercent != null) ? currentGstConfig.sgstPercent : (gstPct / 2.0)) : 0.0;

  const parcelRow = document.getElementById('cartParcelChargeRow');
  const parcelInput = document.getElementById('cartParcelChargeInput');
  let parcelChargeVal = null;
  if (parcelRow && !parcelRow.classList.contains('hidden') && parcelInput) {
    const parsed = parseFloat(parcelInput.value);
    if (!isNaN(parsed) && parsed >= 0) parcelChargeVal = parsed;
  }

  const billPayload = {
    discountPercent: discountPct,
    gstEnabled: isGstEnabled,
    taxPercent: isGstEnabled ? gstPct : 0.0,
    cgstPercent: cgstRate,
    sgstPercent: sgstRate,
    parcelCharge: parcelChargeVal
  };

  try {
    const printedBill = await apiRequest(`/bills/${currentTableOrder.id}/print-bill`, {
      method: 'POST',
      body: JSON.stringify(billPayload)
    });

    showToast(`Bill #${printedBill.billNumber} printed! Awaiting payment confirmation.`, 'success');

    // Wipe cart & clear selection immediately as requested
    cart = [];
    isCartDirty = false;
    currentTableOrder = null;
    currentTakeawayToken = null;
    loadTableOptions('');
    const d1 = document.getElementById('cartCustomer'); if (d1) d1.value = '';
    const d2 = document.getElementById('cartDiscountPct'); if (d2) d2.value = 0;
    const dNotes = document.getElementById('cartOrderNotes'); if (dNotes) dNotes.value = '';
    syncCartGstUI();
    syncTableOrderState('');
    renderTableBadges();
    renderOutdoorBadges();
    renderTakeawayBadges();
    renderCart();

    await refreshActiveOrders();
    displayReceiptModal(printedBill);

    // Automatically trigger resilient print queue / bridge for customer bill
    apiRequest(`/printer/print-bill/${printedBill.id}`, { method: 'POST' })
      .then(res => {
        if (res && res.jobId) {
          trackPrintJobStatus(res.jobId, res.status, `Bill #${printedBill.billNumber}`);
        } else if (res && res.success) {
          showToast(`Bill #${printedBill.billNumber} sent to printer (${res.host})`, 'success');
        } else if (res && !res.success) {
          console.warn('Thermal printer notice:', res.message);
        }
      })
      .catch(err => {
        console.warn('Bill background print warning:', err);
      });

  } catch (err) {
    showToast('Error printing bill: ' + err.message, 'error');
  }
}

// Backward-compatible alias
async function submitBillAndPrint() {
  return submitPrintBillOnly();
}

// ============================================================
// CONFIRM PAYMENT WORKFLOW (Manager / Admin)
// ============================================================
function openConfirmPaymentModal(orderId) {
  let order = null;
  if (orderId) {
    order = (activeOrders || []).find(o => o.id === orderId);
  } else if (currentTableOrder) {
    order = currentTableOrder;
  }

  if (!order) {
    showToast('No active bill found to confirm payment.', 'warning');
    return;
  }

  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  if (!isManagerOrAdmin) {
    showToast('Only Manager or Admin can confirm and settle payments.', 'error');
    return;
  }

  document.getElementById('confirmPaymentOrderId').value = order.id;
  document.getElementById('confirmPayOrderRef').textContent = `#${order.billNumber || order.id}`;
  document.getElementById('confirmPayLocation').textContent = (order.orderType === 'TAKEAWAY' || Boolean(order.takeawayToken))
    ? `Takeaway (${order.customerName || 'Guest'} • ${order.takeawayToken || 'TAK'})`
    : ((order.orderType === 'OUTDOOR' || Boolean(order.outdoorToken))
      ? `Outdoor (${order.customerName || 'Guest'} • ${order.outdoorToken || 'OUT'})`
      : `Table ${order.tableNumber || '-'}`);
  document.getElementById('confirmPayStaff').textContent = order.createdByName || 'Staff';
  document.getElementById('confirmPayAmount').textContent = `₹${(order.netAmount || 0).toFixed(2)}`;

  const notesEl = document.getElementById('confirmPayNotes');
  if (notesEl) notesEl.value = '';

  const cashRadio = document.querySelector('input[name="confirmPayMode"][value="CASH"]');
  if (cashRadio) cashRadio.checked = true;

  const modal = document.getElementById('confirmPaymentModal');
  if (modal) modal.classList.remove('hidden');
}

function closeConfirmPaymentModal() {
  const modal = document.getElementById('confirmPaymentModal');
  if (modal) modal.classList.add('hidden');
}

async function executeConfirmPayment() {
  const orderId = document.getElementById('confirmPaymentOrderId')?.value;
  if (!orderId) {
    showToast('Missing order reference.', 'error');
    return;
  }

  const payMode = document.querySelector('input[name="confirmPayMode"]:checked')?.value || 'CASH';
  const notes = (document.getElementById('confirmPayNotes')?.value || '').trim();

  const btn = document.getElementById('btnExecuteConfirmPayment');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> <span>Processing...</span>`;
  }

  try {
    const settledBill = await apiRequest(`/bills/${orderId}/confirm-payment`, {
      method: 'POST',
      body: JSON.stringify({
        paymentMode: payMode,
        notes: notes
      })
    });

    showToast(`Payment confirmed & settled for Bill #${settledBill.billNumber}! Table released.`, 'success');
    closeConfirmPaymentModal();
    closeActiveOrdersModal();

    // If currently on POS viewing this order/table, reset POS cart
    if (currentTableOrder && String(currentTableOrder.id) === String(orderId)) {
      cart = [];
      isCartDirty = false;
      currentTableOrder = null;
      currentTakeawayToken = null;
      loadTableOptions('');
      const d1 = document.getElementById('cartCustomer'); if (d1) d1.value = '';
      const d2 = document.getElementById('cartDiscountPct'); if (d2) d2.value = 0;
      const dNotes = document.getElementById('cartOrderNotes'); if (dNotes) dNotes.value = '';
      syncCartGstUI();
      syncTableOrderState('');
      renderTableBadges();
      renderOutdoorBadges();
      renderTakeawayBadges();
      renderCart();
    }

    await refreshActiveOrders();

  } catch (err) {
    showToast('Failed to confirm payment: ' + err.message, 'error');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = `<i class="fa-solid fa-check-circle"></i> <span>Confirm Payment</span>`;
    }
  }
}

// ============================================================
// ESC/POS THERMAL BILL RECEIPT MODAL
// ============================================================
function displayReceiptModal(bill) {
  activeReceiptBill = bill;

  // Sync Store Name, Subheader, Logo, and Footer with active printer config
  const storeNameEl = document.getElementById('rcptStoreName');
  if (storeNameEl) storeNameEl.textContent = currentPrinterConfig?.headerTitle || 'NERAM';

  const subHeaderEl = document.getElementById('rcptSubHeader');
  if (subHeaderEl) {
    const sub = currentPrinterConfig?.subheader || '';
    if (sub.trim()) {
      subHeaderEl.textContent = sub.trim();
      subHeaderEl.classList.remove('hidden');
    } else {
      subHeaderEl.textContent = '';
      subHeaderEl.classList.add('hidden');
    }
  }

  const subHeader2El = document.getElementById('rcptSubHeader2');
  if (subHeader2El) {
    const sub2 = currentPrinterConfig?.subheader2 || '';
    if (sub2.trim()) {
      subHeader2El.textContent = sub2.trim();
      subHeader2El.classList.remove('hidden');
    } else {
      subHeader2El.textContent = '';
      subHeader2El.classList.add('hidden');
    }
  }

  const logoImg = document.getElementById('rcptLogoImg');
  if (logoImg) {
    if (currentPrinterConfig?.logoEnabled === false) {
      logoImg.classList.add('hidden');
    } else {
      logoImg.classList.remove('hidden');
    }
  }

  const footerMsgEl = document.getElementById('rcptFooterMsg');
  if (footerMsgEl) footerMsgEl.textContent = currentPrinterConfig?.footerMessage || 'THANK YOU! VISIT AGAIN';

  document.getElementById('rcptBillNo').textContent = `Bill: ${bill.billNumber}`;

  const isTakeaway = bill.orderType === 'TAKEAWAY' || Boolean(bill.takeawayToken);
  const isOutdoor = bill.orderType === 'OUTDOOR' || Boolean(bill.outdoorToken);
  const tableEl = document.getElementById('rcptTableNo');
  if (tableEl) {
    if (isTakeaway) {
      tableEl.innerHTML = `Order: <strong>Takeaway</strong><br>Customer: <strong>${escapeHtml(bill.customerName || 'Guest')}</strong><br>Token: <strong>${escapeHtml(bill.takeawayToken || '')}</strong>`;
    } else if (isOutdoor) {
      tableEl.innerHTML = `Location: <strong>Outdoor</strong><br>Customer: <strong>${escapeHtml(bill.customerName || 'Guest')}</strong><br>Token: <strong>${escapeHtml(bill.outdoorToken || '')}</strong>`;
    } else {
      tableEl.textContent = `Table: ${bill.tableNumber || '-'}`;
    }
  }

  document.getElementById('rcptDate').textContent = `Date: ${formatISTDateTime(bill.createdAt || new Date())}`;
  document.getElementById('rcptCashier').textContent = `Cashier: ${bill.printedByName || currentUser.username}`;
  const staffEl = document.getElementById('rcptStaff');
  if (staffEl) staffEl.textContent = `Staff Attended: ${bill.createdByName || 'Staff'}`;

  const tbody = document.getElementById('rcptItemsBody');
  tbody.innerHTML = bill.items.map(it => {
    const parcelBadge = it.isTakeaway ? '<span class="text-[9px] text-gray-700 font-bold block">(Parcel)</span>' : '';
    return `
    <tr class="border-b border-dashed border-gray-400">
      <td class="py-1 text-black font-bold text-left" style="width: 44%; word-break: break-word;">${escapeHtml(it.itemName)}${parcelBadge}</td>
      <td class="py-1 text-black font-bold text-center" style="width: 14%;">${it.quantity}</td>
      <td class="py-1 text-black font-bold text-right" style="width: 20%; white-space: nowrap;">₹${it.price.toFixed(2)}</td>
      <td class="py-1 text-black font-bold text-right" style="width: 22%; white-space: nowrap; padding-right: 2.5mm;">₹${it.subtotal.toFixed(2)}</td>
    </tr>
  `;
  }).join('');

  const isGstActive = bill.gstEnabled != null ? bill.gstEnabled : ((bill.taxAmount != null && bill.taxAmount > 0) || (bill.taxPercent != null && bill.taxPercent > 0));
  const gstinRow = document.getElementById('rcptGstinRow');
  const gstinEl = document.getElementById('rcptGstin');
  const docTitleEl = document.getElementById('rcptDocTitle');

  if (isGstActive) {
    if (gstinRow && gstinEl) {
      gstinRow.classList.remove('hidden');
      gstinEl.textContent = bill.gstin || (currentGstConfig ? currentGstConfig.gstin : '32CQRPS5214H3ZK');
    }
    if (docTitleEl) docTitleEl.textContent = 'TAX INVOICE';
  } else {
    if (gstinRow) gstinRow.classList.add('hidden');
    if (docTitleEl) docTitleEl.textContent = 'CASH BILL / RECEIPT';
  }

  // Total quantity
  const totalQty = bill.items ? bill.items.reduce((acc, it) => acc + (it.quantity || 0), 0) : 0;
  const rcptTotalQty = document.getElementById('rcptTotalQty');
  if (rcptTotalQty) rcptTotalQty.textContent = totalQty;

  document.getElementById('rcptSubtotal').textContent = `₹${bill.subtotal.toFixed(2)}`;
  if (bill.discountAmount && bill.discountAmount > 0) {
    document.getElementById('rcptDiscountRow').style.display = 'flex';
    document.getElementById('rcptDiscount').textContent = `-₹${bill.discountAmount.toFixed(2)}`;
  } else {
    document.getElementById('rcptDiscountRow').style.display = 'none';
  }

  const rcptParcelRow = document.getElementById('rcptParcelChargeRow');
  const rcptParcelVal = document.getElementById('rcptParcelCharge');
  if (bill.parcelCharge && Number(bill.parcelCharge) > 0) {
    if (rcptParcelRow) rcptParcelRow.style.display = 'flex';
    if (rcptParcelVal) rcptParcelVal.textContent = `₹${Number(bill.parcelCharge).toFixed(2)}`;
  } else {
    if (rcptParcelRow) rcptParcelRow.style.display = 'none';
  }

  // CGST & SGST & Round-off breakdown
  const cgstRow = document.getElementById('rcptCgstRow');
  const sgstRow = document.getElementById('rcptSgstRow');
  const roundOffRow = document.getElementById('rcptRoundOffRow');
  const taxRow = document.getElementById('rcptTaxRow');

  if (isGstActive) {
    const cgstRate = bill.cgstPercent != null ? bill.cgstPercent : (bill.taxPercent != null ? bill.taxPercent / 2.0 : 2.5);
    const sgstRate = bill.sgstPercent != null ? bill.sgstPercent : (bill.taxPercent != null ? bill.taxPercent / 2.0 : 2.5);
    const cgstAmt = bill.cgstAmount != null ? bill.cgstAmount : (bill.taxAmount != null ? bill.taxAmount / 2.0 : 0.0);
    const sgstAmt = bill.sgstAmount != null ? bill.sgstAmount : (bill.taxAmount != null ? bill.taxAmount / 2.0 : 0.0);

    if (cgstRow) {
      cgstRow.style.display = 'flex';
      const r = document.getElementById('rcptCgstRate');
      const a = document.getElementById('rcptCgst');
      if (r) r.textContent = cgstRate.toFixed(1);
      if (a) a.textContent = `₹${cgstAmt.toFixed(2)}`;
    }
    if (sgstRow) {
      sgstRow.style.display = 'flex';
      const r = document.getElementById('rcptSgstRate');
      const a = document.getElementById('rcptSgst');
      if (r) r.textContent = sgstRate.toFixed(1);
      if (a) a.textContent = `₹${sgstAmt.toFixed(2)}`;
    }
    if (roundOffRow) {
      if (bill.roundOff != null && Math.abs(bill.roundOff) > 0.001) {
        roundOffRow.style.display = 'flex';
        const sign = bill.roundOff >= 0 ? '+' : '';
        const a = document.getElementById('rcptRoundOff');
        if (a) a.textContent = `${sign}₹${bill.roundOff.toFixed(2)}`;
      } else {
        roundOffRow.style.display = 'none';
      }
    }
    if (taxRow) taxRow.style.display = 'none';
  } else {
    if (cgstRow) cgstRow.style.display = 'none';
    if (sgstRow) sgstRow.style.display = 'none';
    if (roundOffRow) roundOffRow.style.display = 'none';
    if (taxRow) taxRow.style.display = 'none';
  }

  const promoRow = document.getElementById('rcptPromotionRow');
  if (promoRow) {
    if (bill.promotionDiscountAmount && Number(bill.promotionDiscountAmount) > 0) {
      promoRow.style.display = 'flex';
      const label = document.getElementById('rcptPromotionLabel');
      const val = document.getElementById('rcptPromotionDiscount');
      if (label) label.textContent = `Promo (${escapeHtml(bill.promotionName || 'Promotion')} ${bill.promotionPercentage || 0}%):`;
      if (val) val.textContent = `-₹${Number(bill.promotionDiscountAmount).toFixed(2)}`;
    } else {
      promoRow.style.display = 'none';
    }
  }

  document.getElementById('rcptGrandTotal').textContent = `₹${bill.netAmount.toFixed(2)}`;
  document.getElementById('rcptPayMode').textContent = bill.paymentMode || 'CASH';

  document.getElementById('receiptModal').classList.remove('hidden');

  // Trigger mark as printed in background
  apiRequest(`/bills/${bill.id}/print`, { method: 'POST' }).catch(() => { });
}

async function directPrintActiveBill() {
  if (!activeReceiptBill || !activeReceiptBill.id) {
    showToast('No active bill selected to print', 'error');
    return;
  }
  const btn = document.getElementById('btnDirectPrintReceipt');
  const btnText = document.getElementById('btnDirectPrintReceiptText');
  if (btn) btn.disabled = true;
  if (btnText) btnText.textContent = 'PRINTING...';

  try {
    const res = await apiRequest(`/printer/print-bill/${activeReceiptBill.id}`, { method: 'POST' });
    if (res && res.jobId) {
      trackPrintJobStatus(res.jobId, res.status, `Bill #${activeReceiptBill.billNumber}`);
    } else if (res && res.success) {
      showToast(`Bill #${activeReceiptBill.billNumber} printed directly to thermal printer (${res.host}:${res.port})!`, 'success');
    } else {
      showToast(`Print warning: ${res.message || 'Check printer connection'}`, 'warning');
    }
  } catch (err) {
    showToast('Direct print failed: ' + err.message, 'error');
  } finally {
    if (btn) btn.disabled = false;
    if (btnText) btnText.textContent = 'DIRECT PRINT (THERMAL)';
  }
}

function triggerPrintReceipt() {
  printElementContent('thermalReceiptContent', 'Customer Bill Receipt');
}

function closeReceiptModal() {
  document.getElementById('receiptModal').classList.add('hidden');
  activeReceiptBill = null;
}

// ============================================================
// GST CONFIGURATION & MANAGEMENT MODULE
// ============================================================
let currentGstConfig = {
  enabled: true,
  gstin: '32CQRPS5214H3ZK',
  cgstPercent: 2.5,
  sgstPercent: 2.5,
  totalGstPercent: 5.0,
  roundOffEnabled: false
};

async function loadGstConfig() {
  try {
    const cfg = await apiRequest('/gst/config');
    if (cfg) {
      currentGstConfig = cfg;
      populateGstForm();
      syncCartGstUI();
    }
  } catch (err) {
    console.warn('Could not load GST config:', err);
  }
  loadParcelChargeSetting();
}

async function loadParcelChargeSetting() {
  try {
    const res = await apiRequest('/settings/parcel-charge');
    if (res && res.defaultParcelCharge != null) {
      defaultParcelCharge = Number(res.defaultParcelCharge);
      const input = document.getElementById('defaultParcelChargeInput');
      if (input) input.value = defaultParcelCharge;
    }
  } catch (err) {
    console.warn('Could not load parcel charge setting:', err);
  }
}

function syncCartGstUI() {
  const gstSel = document.getElementById('cartGstSelect');
  if (!gstSel) return;

  const isEnabled = Boolean(currentGstConfig && currentGstConfig.enabled);
  const configuredRate = (currentGstConfig && currentGstConfig.totalGstPercent != null) ? currentGstConfig.totalGstPercent : 5.0;

  if (isEnabled && configuredRate > 0) {
    let exists = false;
    for (let i = 0; i < gstSel.options.length; i++) {
      if (parseFloat(gstSel.options[i].value) === configuredRate) {
        exists = true;
        break;
      }
    }
    if (!exists) {
      const opt = document.createElement('option');
      opt.value = String(configuredRate);
      opt.textContent = `${configuredRate}% (GST)`;
      const customOpt = gstSel.querySelector('option[value="custom"]');
      if (customOpt) gstSel.insertBefore(opt, customOpt);
      else gstSel.appendChild(opt);
    }
    gstSel.value = String(configuredRate);
  } else {
    gstSel.value = '0';
  }

  const customGst = document.getElementById('cartGstCustom');
  if (customGst) customGst.classList.add('hidden');

  if (typeof renderCart === 'function') {
    renderCart();
  }
}

function populateGstForm() {
  const toggle = document.getElementById('gstEnabledToggle');
  const gstinInp = document.getElementById('gstinInput');
  const cgstInp = document.getElementById('cgstPercentInput');
  const sgstInp = document.getElementById('sgstPercentInput');
  const roundOffToggle = document.getElementById('gstRoundOffToggle');
  const lastUpdated = document.getElementById('gstLastUpdatedAt');
  const lastUpdatedBy = document.getElementById('gstLastUpdatedBy');

  if (toggle) toggle.checked = Boolean(currentGstConfig.enabled);
  if (gstinInp) gstinInp.value = currentGstConfig.gstin || '';
  if (cgstInp) cgstInp.value = currentGstConfig.cgstPercent != null ? currentGstConfig.cgstPercent : 2.5;
  if (sgstInp) sgstInp.value = currentGstConfig.sgstPercent != null ? currentGstConfig.sgstPercent : 2.5;
  if (roundOffToggle) roundOffToggle.checked = Boolean(currentGstConfig.roundOffEnabled);

  if (lastUpdated) {
    lastUpdated.textContent = currentGstConfig.updatedAt ? formatISTDateTime(currentGstConfig.updatedAt) : 'Default';
  }
  if (lastUpdatedBy) {
    lastUpdatedBy.textContent = currentGstConfig.updatedByName || 'System';
  }

  updateGstStatusBadge(currentGstConfig.enabled);
  updateGstRatesCalculation();
}

function updateGstStatusBadge(isEnabled) {
  const badge = document.getElementById('gstActiveStatusBadge');
  if (!badge) return;

  if (isEnabled) {
    badge.className = 'px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-2 bg-emerald-500/10 text-emerald-400 border border-emerald-500/30';
    badge.innerHTML = `<span class="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span><span id="gstActiveStatusBadgeText">GST ENABLED</span>`;
  } else {
    badge.className = 'px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-2 bg-rose-500/10 text-rose-400 border border-rose-500/30';
    badge.innerHTML = `<span class="w-2 h-2 rounded-full bg-rose-400"></span><span id="gstActiveStatusBadgeText">GST DISABLED</span>`;
  }
}

function handleGstToggleChange() {
  const isEnabled = document.getElementById('gstEnabledToggle')?.checked ?? true;
  updateGstStatusBadge(isEnabled);
  updateGstPreview();
}

function updateGstRatesCalculation() {
  const cgst = parseFloat(document.getElementById('cgstPercentInput')?.value || 0);
  const sgst = parseFloat(document.getElementById('sgstPercentInput')?.value || 0);
  const total = Math.round((cgst + sgst) * 100) / 100;
  const disp = document.getElementById('totalGstPercentDisplay');
  if (disp) {
    disp.textContent = `${total.toFixed(1)}% (CGST ${cgst.toFixed(1)}% + SGST ${sgst.toFixed(1)}%)`;
  }
  updateGstPreview();
}

function updateGstPreview() {
  const isEnabled = document.getElementById('gstEnabledToggle')?.checked ?? true;
  const gstinVal = (document.getElementById('gstinInput')?.value || '').trim();
  const cgstVal = parseFloat(document.getElementById('cgstPercentInput')?.value || 0);
  const sgstVal = parseFloat(document.getElementById('sgstPercentInput')?.value || 0);
  const isRoundOff = document.getElementById('gstRoundOffToggle')?.checked ?? false;

  const modeTag = document.getElementById('previewModeTag');
  const gstinRow = document.getElementById('previewGstinRow');
  const gstinText = document.getElementById('previewGstinText');
  const titleText = document.getElementById('previewReceiptTitle');
  const cgstRow = document.getElementById('previewCgstRow');
  const sgstRow = document.getElementById('previewSgstRow');
  const cgstRateText = document.getElementById('previewCgstRateText');
  const sgstRateText = document.getElementById('previewSgstRateText');
  const cgstAmtText = document.getElementById('previewCgstAmtText');
  const sgstAmtText = document.getElementById('previewSgstAmtText');
  const roundOffRow = document.getElementById('previewRoundOffRow');
  const roundOffText = document.getElementById('previewRoundOffText');
  const grandTotalText = document.getElementById('previewGrandTotalText');

  const sampleSubtotal = 200.0;

  if (isEnabled) {
    if (modeTag) {
      modeTag.textContent = 'TAX INVOICE';
      modeTag.className = 'text-[10px] font-bold px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-400 border border-emerald-500/30';
    }
    if (gstinRow) gstinRow.classList.remove('hidden');
    if (gstinText) gstinText.textContent = gstinVal || '32CQRPS5214H3ZK';
    if (titleText) titleText.textContent = 'TAX INVOICE';

    const cgstAmt = Math.round(((sampleSubtotal * cgstVal) / 100.0) * 100) / 100;
    const sgstAmt = Math.round(((sampleSubtotal * sgstVal) / 100.0) * 100) / 100;

    if (cgstRow) cgstRow.classList.remove('hidden');
    if (sgstRow) sgstRow.classList.remove('hidden');
    if (cgstRateText) cgstRateText.textContent = cgstVal.toFixed(1);
    if (sgstRateText) sgstRateText.textContent = sgstVal.toFixed(1);
    if (cgstAmtText) cgstAmtText.textContent = `₹${cgstAmt.toFixed(2)}`;
    if (sgstAmtText) sgstAmtText.textContent = `₹${sgstAmt.toFixed(2)}`;

    const exactTotal = sampleSubtotal + cgstAmt + sgstAmt;
    if (isRoundOff) {
      const rounded = Math.round(exactTotal);
      const diff = Math.round((rounded - exactTotal) * 100) / 100;
      if (roundOffRow) {
        roundOffRow.classList.remove('hidden');
        if (roundOffText) roundOffText.textContent = `${diff >= 0 ? '+' : ''}₹${diff.toFixed(2)}`;
      }
      if (grandTotalText) grandTotalText.textContent = `₹${rounded.toFixed(2)}`;
    } else {
      if (roundOffRow) roundOffRow.classList.add('hidden');
      if (grandTotalText) grandTotalText.textContent = `₹${exactTotal.toFixed(2)}`;
    }
  } else {
    if (modeTag) {
      modeTag.textContent = 'GST DISABLED';
      modeTag.className = 'text-[10px] font-bold px-2 py-0.5 rounded bg-gray-700 text-gray-300 border border-gray-600';
    }
    if (gstinRow) gstinRow.classList.add('hidden');
    if (titleText) titleText.textContent = 'CASH BILL / RECEIPT';
    if (cgstRow) cgstRow.classList.add('hidden');
    if (sgstRow) sgstRow.classList.add('hidden');
    if (roundOffRow) roundOffRow.classList.add('hidden');
    if (grandTotalText) grandTotalText.textContent = `₹${sampleSubtotal.toFixed(2)}`;
  }
}

async function saveGstConfig() {
  const isEnabled = document.getElementById('gstEnabledToggle')?.checked ?? true;
  const gstin = (document.getElementById('gstinInput')?.value || '').trim();
  const cgstPercent = parseFloat(document.getElementById('cgstPercentInput')?.value || 0);
  const sgstPercent = parseFloat(document.getElementById('sgstPercentInput')?.value || 0);
  const roundOffEnabled = document.getElementById('gstRoundOffToggle')?.checked ?? false;

  if (isNaN(cgstPercent) || cgstPercent < 0) {
    showToast('Invalid CGST percentage rate', 'error');
    return;
  }
  if (isNaN(sgstPercent) || sgstPercent < 0) {
    showToast('Invalid SGST percentage rate', 'error');
    return;
  }

  const btnTop = document.getElementById('btnSaveGstTop');
  const btnBottom = document.getElementById('btnSaveGstBottom');
  if (btnTop) btnTop.disabled = true;
  if (btnBottom) btnBottom.disabled = true;

  try {
    const payload = {
      enabled: isEnabled,
      gstin: gstin || '32CQRPS5214H3ZK',
      cgstPercent,
      sgstPercent,
      roundOffEnabled
    };
    const updated = await apiRequest('/gst/config', {
      method: 'PUT',
      body: JSON.stringify(payload)
    });
    if (updated) {
      currentGstConfig = updated;
      populateGstForm();
      syncCartGstUI();

      const parcelChargeInp = document.getElementById('defaultParcelChargeInput');
      if (parcelChargeInp) {
        const pcVal = parseFloat(parcelChargeInp.value);
        if (!isNaN(pcVal) && pcVal >= 0) {
          try {
            const pcRes = await apiRequest('/settings/parcel-charge', {
              method: 'POST',
              body: JSON.stringify({ defaultParcelCharge: pcVal })
            });
            if (pcRes && pcRes.defaultParcelCharge != null) {
              defaultParcelCharge = Number(pcRes.defaultParcelCharge);
            }
          } catch (e) {
            console.warn('Could not save parcel charge setting:', e);
          }
        }
      }

      showToast('GST & Parcel charge settings updated successfully! Applied to all future bills.', 'success');
      if (typeof renderCart === 'function') {
        renderCart();
      }
    }
  } catch (err) {
    showToast('Failed to save GST settings: ' + err.message, 'error');
  } finally {
    if (btnTop) btnTop.disabled = false;
    if (btnBottom) btnBottom.disabled = false;
  }
}

function resetGstDefaults() {
  const t = document.getElementById('gstEnabledToggle');
  const gi = document.getElementById('gstinInput');
  const cp = document.getElementById('cgstPercentInput');
  const sp = document.getElementById('sgstPercentInput');
  const ro = document.getElementById('gstRoundOffToggle');

  if (t) t.checked = true;
  if (gi) gi.value = '32CQRPS5214H3ZK';
  if (cp) cp.value = '2.5';
  if (sp) sp.value = '2.5';
  if (ro) ro.checked = false;

  updateGstStatusBadge(true);
  updateGstRatesCalculation();
  showToast('Reset GST fields to standard 2.5% CGST + 2.5% SGST defaults. Click Save Changes to apply.', 'info');
}

// ============================================================
// THERMAL PRINTER SETTINGS & CONNECTION STATUS
// ============================================================

async function openPrinterSettingsModal() {
  if (!currentUser || !['ADMIN', 'MANAGER'].includes(currentUser.role)) {
    showToast('Thermal printer settings are restricted to Manager and Admin accounts.', 'warning');
    return;
  }
  const modal = document.getElementById('printerSettingsModal');
  if (!modal) return;
  modal.classList.remove('hidden');
  await loadPrinterConfig();
  await checkPrinterConnectionStatus(false);
}

function closePrinterSettingsModal() {
  const modal = document.getElementById('printerSettingsModal');
  if (modal) modal.classList.add('hidden');
}

async function loadPrinterConfig() {
  try {
    const cfg = await apiRequest('/printer/config');
    if (cfg) {
      currentPrinterConfig = cfg;
      const hostInput = document.getElementById('cfgPrinterHost');
      const portInput = document.getElementById('cfgPrinterPort');
      const enabledCheck = document.getElementById('cfgPrinterEnabled');

      // Dedicated Bill Printer inputs
      const billHostInput = document.getElementById('cfgBillPrinterHost');
      const billPortInput = document.getElementById('cfgBillPrinterPort');
      const billEnabledCheck = document.getElementById('cfgBillPrinterEnabled');

      // Dedicated KOT Printer inputs
      const kotHostInput = document.getElementById('cfgKotPrinterHost');
      const kotPortInput = document.getElementById('cfgKotPrinterPort');
      const kotEnabledCheck = document.getElementById('cfgKotPrinterEnabled');

      // Dedicated Juice KOT Printer inputs
      const juiceKotHostInput = document.getElementById('cfgJuiceKotPrinterHost');
      const juiceKotPortInput = document.getElementById('cfgJuiceKotPrinterPort');
      const juiceKotEnabledCheck = document.getElementById('cfgJuiceKotPrinterEnabled');

      const headerInput = document.getElementById('cfgPrinterHeader');
      const subheaderInput = document.getElementById('cfgPrinterSubheader');
      const subheader2Input = document.getElementById('cfgPrinterSubheader2');
      const footerInput = document.getElementById('cfgPrinterFooter');
      const autoCutCheck = document.getElementById('cfgPrinterAutoCut');
      const logoCheck = document.getElementById('cfgPrinterLogoEnabled');

      // KOT template inputs
      const kotHeaderInput = document.getElementById('cfgKotHeader');
      const kotSubheaderInput = document.getElementById('cfgKotSubheader');
      const kotFooterInput = document.getElementById('cfgKotFooter');

      // Juice KOT template inputs
      const juiceKotHeaderInput = document.getElementById('cfgJuiceKotHeader');
      const juiceKotSubheaderInput = document.getElementById('cfgJuiceKotSubheader');
      const juiceKotFooterInput = document.getElementById('cfgJuiceKotFooter');

      const billHost = cfg.billHost || cfg.host || '192.168.1.37';
      const billPort = cfg.billPort || cfg.port || 9100;
      const billEnabled = cfg.billEnabled !== false && cfg.enabled !== false;

      const kotHost = cfg.kotHost || '192.168.1.47';
      const kotPort = cfg.kotPort || 9100;
      const kotEnabled = cfg.kotEnabled !== false;

      const juiceKotHost = cfg.juiceKotHost || '192.168.1.42';
      const juiceKotPort = cfg.juiceKotPort || 9100;
      const juiceKotEnabled = cfg.juiceKotEnabled !== false;

      if (billHostInput) billHostInput.value = billHost;
      if (billPortInput) billPortInput.value = billPort;
      if (billEnabledCheck) billEnabledCheck.checked = billEnabled;

      if (kotHostInput) kotHostInput.value = kotHost;
      if (kotPortInput) kotPortInput.value = kotPort;
      if (kotEnabledCheck) kotEnabledCheck.checked = kotEnabled;

      if (juiceKotHostInput) juiceKotHostInput.value = juiceKotHost;
      if (juiceKotPortInput) juiceKotPortInput.value = juiceKotPort;
      if (juiceKotEnabledCheck) juiceKotEnabledCheck.checked = juiceKotEnabled;

      if (hostInput) hostInput.value = billHost;
      if (portInput) portInput.value = billPort;
      if (enabledCheck) enabledCheck.checked = billEnabled;

      if (headerInput) headerInput.value = cfg.headerTitle || 'NERAM';
      if (subheaderInput) subheaderInput.value = cfg.subheader || 'Where time tastes better';
      if (subheader2Input) subheader2Input.value = cfg.subheader2 || 'Infopark Expy, Rajagiri Valley, Chittethukara, Kakkanad, Kochi, Keralam 682037';
      if (footerInput) footerInput.value = cfg.footerMessage || 'THANK YOU! VISIT AGAIN';
      if (autoCutCheck) autoCutCheck.checked = cfg.autoCut !== false;
      if (logoCheck) logoCheck.checked = cfg.logoEnabled !== false;

      if (kotHeaderInput) kotHeaderInput.value = cfg.kotHeaderTitle || '*** KITCHEN ORDER ***';
      if (kotSubheaderInput) kotSubheaderInput.value = cfg.kotSubheader || 'NERAM - MAIN KITCHEN';
      if (kotFooterInput) kotFooterInput.value = cfg.kotFooterMessage || '--- END OF KOT ---';

      if (juiceKotHeaderInput) juiceKotHeaderInput.value = cfg.juiceKotHeaderTitle || '*** JUICE ORDER ***';
      if (juiceKotSubheaderInput) juiceKotSubheaderInput.value = cfg.juiceKotSubheader || 'NERAM - JUICE BAR';
      if (juiceKotFooterInput) juiceKotFooterInput.value = cfg.juiceKotFooterMessage || '--- END OF JUICE KOT ---';

      // Load typography & spacing options into inputs
      if (document.getElementById('cfgLogoSize')) {
        document.getElementById('cfgLogoSize').value = cfg.logoSize || 48;
        if (document.getElementById('cfgLogoSizeValue')) {
          document.getElementById('cfgLogoSizeValue').textContent = (cfg.logoSize || 48) + 'px';
        }
      }
      if (document.getElementById('cfgLogoGap')) {
        document.getElementById('cfgLogoGap').value = cfg.logoGap != null ? cfg.logoGap : 0;
        if (document.getElementById('cfgLogoGapValue')) {
          document.getElementById('cfgLogoGapValue').textContent = (cfg.logoGap != null ? cfg.logoGap : 0) + 'px';
        }
      }
      if (document.getElementById('cfgPrinterLineSpacing')) {
        document.getElementById('cfgPrinterLineSpacing').value = cfg.lineSpacing || 24;
      }
      if (document.getElementById('cfgPrinterHeaderSize')) {
        document.getElementById('cfgPrinterHeaderSize').value = cfg.fontSize || 'DOUBLE_HEIGHT';
      }
      if (document.getElementById('cfgPrinterPrintStyle')) {
        document.getElementById('cfgPrinterPrintStyle').value = cfg.printStyle || 'CRISP_DARK';
      }
      if (document.getElementById('cfgPrinterFooterSpacing')) {
        document.getElementById('cfgPrinterFooterSpacing').value = cfg.footerSpacing != null ? cfg.footerSpacing : 1;
        if (document.getElementById('cfgPrinterFooterSpacingValue')) {
          const val = cfg.footerSpacing != null ? cfg.footerSpacing : 1;
          document.getElementById('cfgPrinterFooterSpacingValue').textContent = val + (val === 1 ? ' line' : ' lines');
        }
      }

      // Render Juice KOT Assigned Routing Categories
      renderJuiceKotCategorySelector(cfg.juiceKotCategoryIds || '');

      // Update live preview
      updateLiveReceiptPreview();

      // Update header label
      const headerLabel = document.getElementById('headerPrinterLabel');
      if (headerLabel) {
        headerLabel.textContent = `${billHost}`;
      }
    }
  } catch (err) {
    console.warn('Could not load printer config:', err);
  }
}

let currentJuiceKotCategoryIds = '';

async function renderJuiceKotCategorySelector(savedCategoryIdsStr) {
  const container = document.getElementById('juiceKotCategoriesList');
  if (!container) return;
  currentJuiceKotCategoryIds = savedCategoryIdsStr || '';

  if (!categories || categories.length === 0) {
    try {
      categories = await apiRequest('/categories');
    } catch (e) {
      console.warn('Could not load categories for printer routing:', e);
    }
  }

  const savedIds = new Set(
    (currentJuiceKotCategoryIds || '')
      .split(',')
      .map(s => s.trim())
      .filter(Boolean)
  );

  if (!categories || categories.length === 0) {
    container.innerHTML = '<div class="text-xs text-gray-500 italic py-2 col-span-full">No menu categories found.</div>';
    updateJuiceKotCategoryCount();
    return;
  }

  container.innerHTML = categories.map(cat => {
    const isChecked = savedIds.has(String(cat.id));
    return `
      <label class="flex items-center gap-2 p-2 rounded-lg bg-gray-900/80 border border-gray-800 hover:border-emerald-600/60 cursor-pointer transition select-none group">
        <input type="checkbox" name="juiceKotCategory" value="${cat.id}" ${isChecked ? 'checked' : ''}
          class="rounded border-gray-700 text-emerald-500 focus:ring-emerald-500 bg-gray-800 w-4 h-4 cursor-pointer"
          onchange="onJuiceKotCategoryChange()" />
        <span class="text-xs text-gray-300 group-hover:text-white font-medium truncate" title="${escapeHtml(cat.name)}">${escapeHtml(cat.name)}</span>
      </label>
    `;
  }).join('');

  updateJuiceKotCategoryCount();
}

function onJuiceKotCategoryChange() {
  updateJuiceKotCategoryCount();
}

function updateJuiceKotCategoryCount() {
  const checkboxes = document.querySelectorAll('input[name="juiceKotCategory"]:checked');
  const countSpan = document.getElementById('juiceKotCategorySelectedCount');
  if (countSpan) {
    const count = checkboxes.length;
    countSpan.textContent = `${count} categor${count === 1 ? 'y' : 'ies'} assigned`;
  }
}

function selectAllJuiceKotCategories(selectAll) {
  const checkboxes = document.querySelectorAll('input[name="juiceKotCategory"]');
  checkboxes.forEach(cb => {
    cb.checked = !!selectAll;
  });
  updateJuiceKotCategoryCount();
}

function getSelectedJuiceKotCategoryIds() {
  const checkboxes = document.querySelectorAll('input[name="juiceKotCategory"]:checked');
  return Array.from(checkboxes).map(cb => cb.value.trim()).filter(Boolean).join(',');
}

async function savePrinterSettings(event) {
  if (event) event.preventDefault();
  const billHost = document.getElementById('cfgBillPrinterHost')?.value?.trim() || document.getElementById('cfgPrinterHost')?.value?.trim() || '192.168.1.37';
  const billPort = parseInt(document.getElementById('cfgBillPrinterPort')?.value || document.getElementById('cfgPrinterPort')?.value) || 9100;
  const billEnabled = document.getElementById('cfgBillPrinterEnabled') ? document.getElementById('cfgBillPrinterEnabled').checked : (document.getElementById('cfgPrinterEnabled')?.checked !== false);

  const kotHost = document.getElementById('cfgKotPrinterHost')?.value?.trim() || '192.168.1.47';
  const kotPort = parseInt(document.getElementById('cfgKotPrinterPort')?.value) || 9100;
  const kotEnabled = document.getElementById('cfgKotPrinterEnabled')?.checked !== false;

  const juiceKotHost = document.getElementById('cfgJuiceKotPrinterHost')?.value?.trim() || '192.168.1.42';
  const juiceKotPort = parseInt(document.getElementById('cfgJuiceKotPrinterPort')?.value) || 9100;
  const juiceKotEnabled = document.getElementById('cfgJuiceKotPrinterEnabled')?.checked !== false;

  const juiceKotCategoryIds = getSelectedJuiceKotCategoryIds();

  const headerTitle = document.getElementById('cfgPrinterHeader')?.value?.trim() || 'NERAM';
  const subheader = document.getElementById('cfgPrinterSubheader')?.value?.trim() || '';
  const subheader2 = document.getElementById('cfgPrinterSubheader2')?.value?.trim() || '';
  const footerMessage = document.getElementById('cfgPrinterFooter')?.value?.trim() || 'THANK YOU! VISIT AGAIN';
  const autoCut = document.getElementById('cfgPrinterAutoCut')?.checked !== false;
  const logoEnabled = document.getElementById('cfgPrinterLogoEnabled')?.checked !== false;

  const kotHeaderTitle = document.getElementById('cfgKotHeader')?.value?.trim() || '*** KITCHEN ORDER ***';
  const kotSubheader = document.getElementById('cfgKotSubheader')?.value?.trim() || 'NERAM - MAIN KITCHEN';
  const kotFooterMessage = document.getElementById('cfgKotFooter')?.value?.trim() || '--- END OF KOT ---';

  const juiceKotHeaderTitle = document.getElementById('cfgJuiceKotHeader')?.value?.trim() || '*** JUICE ORDER ***';
  const juiceKotSubheader = document.getElementById('cfgJuiceKotSubheader')?.value?.trim() || 'NERAM - JUICE BAR';
  const juiceKotFooterMessage = document.getElementById('cfgJuiceKotFooter')?.value?.trim() || '--- END OF JUICE KOT ---';

  const logoGap = parseInt(document.getElementById('cfgLogoGap')?.value || '2');
  const logoSize = parseInt(document.getElementById('cfgLogoSize')?.value || '130');
  const lineSpacing = parseInt(document.getElementById('cfgPrinterLineSpacing')?.value || '24');
  const fontSize = document.getElementById('cfgPrinterHeaderSize')?.value || 'DOUBLE_HEIGHT';
  const printStyle = document.getElementById('cfgPrinterPrintStyle')?.value || 'CRISP_DARK';
  const footerSpacing = parseInt(document.getElementById('cfgPrinterFooterSpacing')?.value || '1');

  const payload = {
    host: billHost,
    port: billPort,
    enabled: billEnabled,
    billHost,
    billPort,
    billEnabled,
    kotHost,
    kotPort,
    kotEnabled,
    juiceKotHost,
    juiceKotPort,
    juiceKotEnabled,
    juiceKotCategoryIds,
    headerTitle,
    subheader,
    subheader2,
    footerMessage,
    autoCut,
    logoEnabled,
    kotHeaderTitle,
    kotSubheader,
    kotFooterMessage,
    juiceKotHeaderTitle,
    juiceKotSubheader,
    juiceKotFooterMessage,
    paperWidthMm: 80,
    logoSize,
    logoGap,
    lineSpacing,
    headerSpacing: 1,
    footerSpacing,
    fontSize,
    printStyle
  };

  try {
    const updated = await apiRequest('/printer/config', {
      method: 'PUT',
      body: JSON.stringify(payload)
    });
    currentPrinterConfig = updated;
    currentJuiceKotCategoryIds = juiceKotCategoryIds;
    showToast('Thermal printer settings saved successfully!', 'success');
    const headerLabel = document.getElementById('headerPrinterLabel');
    if (headerLabel && updated.billHost) headerLabel.textContent = `${updated.billHost}`;
    if (activeReceiptBill) {
      displayReceiptModal(activeReceiptBill);
    }
    if (activeKotBill) {
      displayKotReceiptModal(activeKotBill);
    }
    updateLiveReceiptPreview();
    await checkPrinterConnectionStatus(true);
  } catch (err) {
    showToast('Failed to save printer settings: ' + err.message, 'error');
  }
}

function switchPrinterSetupTab(tab) {
  const billModule = document.getElementById('printerModuleBill');
  const kotModule = document.getElementById('printerModuleKot');
  const juiceKotModule = document.getElementById('printerModuleJuiceKot');
  const netModule = document.getElementById('printerModuleNetwork');

  const btnBill = document.getElementById('tabBtnPrinterBill');
  const btnKot = document.getElementById('tabBtnPrinterKot');
  const btnJuiceKot = document.getElementById('tabBtnPrinterJuiceKot');
  const btnNet = document.getElementById('tabBtnPrinterNetwork');

  const activeBtnClasses = 'flex-1 py-2 px-3 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 bg-emerald-600 text-white shadow-md';
  const inactiveBtnClasses = 'flex-1 py-2 px-3 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 bg-transparent text-gray-400 hover:text-white';

  if (tab === 'bill') {
    if (billModule) billModule.classList.remove('hidden');
    if (kotModule) kotModule.classList.add('hidden');
    if (juiceKotModule) juiceKotModule.classList.add('hidden');
    if (netModule) netModule.classList.add('hidden');

    if (btnBill) btnBill.className = activeBtnClasses;
    if (btnKot) btnKot.className = inactiveBtnClasses;
    if (btnJuiceKot) btnJuiceKot.className = inactiveBtnClasses;
    if (btnNet) btnNet.className = inactiveBtnClasses;

    toggleLivePreview('bill');
  } else if (tab === 'kot') {
    if (billModule) billModule.classList.add('hidden');
    if (kotModule) kotModule.classList.remove('hidden');
    if (juiceKotModule) juiceKotModule.classList.add('hidden');
    if (netModule) netModule.classList.add('hidden');

    if (btnBill) btnBill.className = inactiveBtnClasses;
    if (btnKot) btnKot.className = activeBtnClasses;
    if (btnJuiceKot) btnJuiceKot.className = inactiveBtnClasses;
    if (btnNet) btnNet.className = inactiveBtnClasses;

    toggleLivePreview('kot');
  } else if (tab === 'juice_kot') {
    if (billModule) billModule.classList.add('hidden');
    if (kotModule) kotModule.classList.add('hidden');
    if (juiceKotModule) juiceKotModule.classList.remove('hidden');
    if (netModule) netModule.classList.add('hidden');

    if (btnBill) btnBill.className = inactiveBtnClasses;
    if (btnKot) btnKot.className = inactiveBtnClasses;
    if (btnJuiceKot) btnJuiceKot.className = activeBtnClasses;
    if (btnNet) btnNet.className = inactiveBtnClasses;

    toggleLivePreview('juice_kot');
  } else if (tab === 'network') {
    if (billModule) billModule.classList.add('hidden');
    if (kotModule) kotModule.classList.add('hidden');
    if (juiceKotModule) juiceKotModule.classList.add('hidden');
    if (netModule) netModule.classList.remove('hidden');

    if (btnBill) btnBill.className = inactiveBtnClasses;
    if (btnKot) btnKot.className = inactiveBtnClasses;
    if (btnJuiceKot) btnJuiceKot.className = inactiveBtnClasses;
    if (btnNet) btnNet.className = activeBtnClasses;
  }
}

function toggleLivePreview(type) {
  const billPreview = document.getElementById('liveBillPreviewContainer');
  const kotPreview = document.getElementById('liveKotPreviewContainer');
  const juiceKotPreview = document.getElementById('liveJuiceKotPreviewContainer');
  const btnBill = document.getElementById('livePreviewBtnBill');
  const btnKot = document.getElementById('livePreviewBtnKot');
  const btnJuiceKot = document.getElementById('livePreviewBtnJuiceKot');

  const activeBtnClass = 'px-2.5 py-1 rounded font-bold transition bg-emerald-600 text-white shadow-sm';
  const inactiveBtnClass = 'px-2.5 py-1 rounded font-bold transition text-gray-400 hover:text-white';

  if (type === 'bill') {
    if (billPreview) billPreview.classList.remove('hidden');
    if (kotPreview) kotPreview.classList.add('hidden');
    if (juiceKotPreview) juiceKotPreview.classList.add('hidden');
    if (btnBill) btnBill.className = activeBtnClass;
    if (btnKot) btnKot.className = inactiveBtnClass;
    if (btnJuiceKot) btnJuiceKot.className = inactiveBtnClass;
  } else if (type === 'kot') {
    if (billPreview) billPreview.classList.add('hidden');
    if (kotPreview) kotPreview.classList.remove('hidden');
    if (juiceKotPreview) juiceKotPreview.classList.add('hidden');
    if (btnBill) btnBill.className = inactiveBtnClass;
    if (btnKot) btnKot.className = activeBtnClass;
    if (btnJuiceKot) btnJuiceKot.className = inactiveBtnClass;
  } else if (type === 'juice_kot') {
    if (billPreview) billPreview.classList.add('hidden');
    if (kotPreview) kotPreview.classList.add('hidden');
    if (juiceKotPreview) juiceKotPreview.classList.remove('hidden');
    if (btnBill) btnBill.className = inactiveBtnClass;
    if (btnKot) btnKot.className = inactiveBtnClass;
    if (btnJuiceKot) btnJuiceKot.className = activeBtnClass;
  }
  updateLiveReceiptPreview();
}

function updateLiveReceiptPreview() {
  const header = document.getElementById('cfgPrinterHeader')?.value?.trim() || 'NERAM';
  const sub1 = document.getElementById('cfgPrinterSubheader')?.value?.trim() || 'Where time tastes better';
  const sub2 = document.getElementById('cfgPrinterSubheader2')?.value?.trim() || 'Infopark Expy, Rajagiri Valley, Chittethukara, Kakkanad, Kochi, Keralam 682037';
  const footer = document.getElementById('cfgPrinterFooter')?.value?.trim() || 'THANK YOU! VISIT AGAIN';
  const logoEnabled = document.getElementById('cfgPrinterLogoEnabled')?.checked !== false;

  const kotHeader = document.getElementById('cfgKotHeader')?.value?.trim() || '*** KITCHEN ORDER ***';
  const kotSub = document.getElementById('cfgKotSubheader')?.value?.trim() || 'NERAM - MAIN KITCHEN';
  const kotFooter = document.getElementById('cfgKotFooter')?.value?.trim() || '--- END OF KOT ---';

  const juiceKotHeader = document.getElementById('cfgJuiceKotHeader')?.value?.trim() || '*** JUICE ORDER ***';
  const juiceKotSub = document.getElementById('cfgJuiceKotSubheader')?.value?.trim() || 'NERAM - JUICE BAR';
  const juiceKotFooter = document.getElementById('cfgJuiceKotFooter')?.value?.trim() || '--- END OF JUICE KOT ---';

  // Live Bill Preview elements
  const headerSize = document.getElementById('cfgPrinterHeaderSize')?.value || 'DOUBLE_HEIGHT';
  const lineSpacing = parseInt(document.getElementById('cfgPrinterLineSpacing')?.value || '24');
  const footerSpacing = parseInt(document.getElementById('cfgPrinterFooterSpacing')?.value || '1');

  const liveHeader = document.getElementById('livePreviewHeader');
  if (liveHeader) {
    liveHeader.textContent = header;
    if (headerSize === 'DOUBLE_W_H') {
      liveHeader.className = 'font-black text-lg uppercase tracking-wider text-black m-0 p-0 leading-tight';
    } else {
      liveHeader.className = 'font-black text-base uppercase tracking-normal text-black m-0 p-0 leading-tight';
    }
  }

  const liveBillContainer = document.getElementById('liveBillPreviewContainer');
  if (liveBillContainer) {
    if (lineSpacing <= 20) {
      liveBillContainer.style.lineHeight = '1.1';
    } else if (lineSpacing <= 24) {
      liveBillContainer.style.lineHeight = '1.25';
    } else {
      liveBillContainer.style.lineHeight = '1.45';
    }
  }

  const liveSub1 = document.getElementById('livePreviewSubheader1');
  if (liveSub1) {
    if (sub1) {
      liveSub1.textContent = sub1;
      liveSub1.classList.remove('hidden');
    } else {
      liveSub1.textContent = '';
      liveSub1.classList.add('hidden');
    }
  }

  const liveSub2 = document.getElementById('livePreviewSubheader2');
  if (liveSub2) {
    if (sub2) {
      liveSub2.textContent = sub2;
      liveSub2.classList.remove('hidden');
    } else {
      liveSub2.textContent = '';
      liveSub2.classList.add('hidden');
    }
  }

  const liveFooter = document.getElementById('livePreviewFooter');
  if (liveFooter) {
    liveFooter.textContent = footer;
    liveFooter.style.paddingBottom = (footerSpacing * 4) + 'px';
  }

  const liveLogo = document.getElementById('livePreviewLogo');
  if (liveLogo) {
    // Logo gap slider: controls space between logo bottom and store name
    const logoGap = parseInt(document.getElementById('cfgLogoGap')?.value || '0');
    const logoSize = parseInt(document.getElementById('cfgLogoSize')?.value || '48');

    if (logoEnabled) {
      liveLogo.classList.remove('hidden');
      liveLogo.style.marginBottom = logoGap + 'px';
      liveLogo.style.maxHeight = logoSize + 'px';
    } else {
      liveLogo.classList.add('hidden');
      liveLogo.style.marginBottom = '0px';
    }

    // Also apply same gap to actual receipt modal logo for preview parity
    const rcptLogo = document.getElementById('rcptLogoImg');
    if (rcptLogo) {
      rcptLogo.style.marginBottom = logoEnabled ? logoGap + 'px' : '0px';
      rcptLogo.style.maxHeight = logoSize + 'px';
    }
  }

  // Live KOT Preview elements
  const liveKotH = document.getElementById('liveKotPreviewHeader');
  if (liveKotH) liveKotH.textContent = kotHeader;

  const liveKotS = document.getElementById('liveKotPreviewSubheader');
  if (liveKotS) {
    if (kotSub) {
      liveKotS.textContent = kotSub;
      liveKotS.classList.remove('hidden');
    } else {
      liveKotS.textContent = '';
      liveKotS.classList.add('hidden');
    }
  }

  const liveKotF = document.getElementById('liveKotPreviewFooter');
  if (liveKotF) {
    liveKotF.textContent = kotFooter;
    liveKotF.style.paddingBottom = (footerSpacing * 4) + 'px';
  }

  // Live Juice KOT Preview elements
  const liveJuiceKotH = document.getElementById('liveJuiceKotPreviewHeader');
  if (liveJuiceKotH) liveJuiceKotH.textContent = juiceKotHeader;

  const liveJuiceKotS = document.getElementById('liveJuiceKotPreviewSubheader');
  if (liveJuiceKotS) {
    if (juiceKotSub) {
      liveJuiceKotS.textContent = juiceKotSub;
      liveJuiceKotS.classList.remove('hidden');
    } else {
      liveJuiceKotS.textContent = '';
      liveJuiceKotS.classList.add('hidden');
    }
  }

  const liveJuiceKotF = document.getElementById('liveJuiceKotPreviewFooter');
  if (liveJuiceKotF) {
    liveJuiceKotF.textContent = juiceKotFooter;
    liveJuiceKotF.style.paddingBottom = (footerSpacing * 4) + 'px';
  }
}

async function checkPrinterConnectionStatus(showToastNotice = false, allowCached = false) {
  const dot = document.getElementById('printerStatusIndicatorDot');
  const text = document.getElementById('printerStatusIndicatorText');
  const sub = document.getElementById('printerStatusIndicatorSub');
  const headerDot = document.getElementById('headerPrinterDot');
  const bridgeBadge = document.getElementById('printerBridgeBadge');

  const miniBillHostText = document.getElementById('miniBillHostText');
  const miniBillStatusBadge = document.getElementById('miniBillStatusBadge');
  const miniKotHostText = document.getElementById('miniKotHostText');
  const miniKotStatusBadge = document.getElementById('miniKotStatusBadge');
  const miniJuiceKotHostText = document.getElementById('miniJuiceKotHostText');
  const miniJuiceKotStatusBadge = document.getElementById('miniJuiceKotStatusBadge');

  const esp32Pill = document.getElementById('esp32BridgeLiveStatusPill');
  const esp32IpVal = document.getElementById('esp32BridgeIpVal');
  const esp32PsramVal = document.getElementById('esp32PsramVal');
  const esp32QueueVal = document.getElementById('esp32QueueVal');
  const esp32UptimeVal = document.getElementById('esp32UptimeVal');

  // Query bridge status in parallel
  let bridgeStatus = null;
  try {
    bridgeStatus = await apiRequest('/printer/bridge/status');
    if (bridgeBadge) {
      if (bridgeStatus && bridgeStatus.bridgeOnline) {
        bridgeBadge.className = 'text-[9px] px-1.5 py-0.5 rounded font-mono bg-emerald-950 text-emerald-400 border border-emerald-800/60';
        bridgeBadge.textContent = `ESP32 Bridge (${bridgeStatus.bridgeIp || 'Online'})`;
      } else {
        bridgeBadge.className = 'text-[9px] px-1.5 py-0.5 rounded font-mono bg-gray-800 text-gray-400';
        bridgeBadge.textContent = 'Direct LAN';
      }
    }
  } catch (bridgeErr) {
    if (bridgeBadge) {
      bridgeBadge.className = 'text-[9px] px-1.5 py-0.5 rounded font-mono bg-gray-800 text-gray-400';
      bridgeBadge.textContent = 'Direct LAN';
    }
  }

  // Update ESP32 Hardware Card telemetry
  if (bridgeStatus && bridgeStatus.bridgeOnline) {
    if (esp32Pill) {
      esp32Pill.className = 'text-[10px] px-2 py-0.5 rounded-full font-bold bg-emerald-950 text-emerald-400 border border-emerald-800/60';
      esp32Pill.textContent = 'ONLINE (Ready)';
    }
    if (esp32IpVal) esp32IpVal.textContent = bridgeStatus.bridgeIp || '192.168.1.x';
    if (esp32PsramVal) {
      const freeMb = bridgeStatus.freePsramBytes ? (bridgeStatus.freePsramBytes / (1024 * 1024)).toFixed(1) : '7.9';
      esp32PsramVal.textContent = `${freeMb} MB / 8 MB`;
    }
    if (esp32QueueVal) esp32QueueVal.textContent = `${bridgeStatus.pendingJobs || 0} pending`;
    if (esp32UptimeVal) {
      const sec = bridgeStatus.uptimeSeconds || 0;
      const mins = Math.floor(sec / 60);
      esp32UptimeVal.textContent = mins > 0 ? `${mins}m ${sec % 60}s` : `${sec}s`;
    }
  } else {
    if (esp32Pill) {
      esp32Pill.className = 'text-[10px] px-2 py-0.5 rounded-full font-bold bg-gray-800 text-gray-400';
      esp32Pill.textContent = 'OFFLINE (Direct LAN)';
    }
    if (esp32IpVal) esp32IpVal.textContent = 'Local Server';
    if (esp32PsramVal) esp32PsramVal.textContent = '8 MB PSRAM (N16R8)';
    if (esp32QueueVal) esp32QueueVal.textContent = '0 pending';
    if (esp32UptimeVal) esp32UptimeVal.textContent = '--';
  }

  // Triple Printer mini cards
  const bHost = (bridgeStatus && bridgeStatus.billPrinterHost) || currentPrinterConfig?.billHost || currentPrinterConfig?.host || '192.168.1.37';
  const bPort = (bridgeStatus && bridgeStatus.billPrinterPort) || currentPrinterConfig?.billPort || currentPrinterConfig?.port || 9100;
  if (miniBillHostText) miniBillHostText.textContent = `${bHost}:${bPort}`;

  const kHost = (bridgeStatus && bridgeStatus.kotPrinterHost) || currentPrinterConfig?.kotHost || '192.168.1.47';
  const kPort = (bridgeStatus && bridgeStatus.kotPrinterPort) || currentPrinterConfig?.kotPort || 9100;
  if (miniKotHostText) miniKotHostText.textContent = `${kHost}:${kPort}`;

  const jkHost = (bridgeStatus && bridgeStatus.juiceKotPrinterHost) || currentPrinterConfig?.juiceKotHost || '192.168.1.42';
  const jkPort = (bridgeStatus && bridgeStatus.juiceKotPrinterPort) || currentPrinterConfig?.juiceKotPort || 9100;
  if (miniJuiceKotHostText) miniJuiceKotHostText.textContent = `${jkHost}:${jkPort}`;

  if (bridgeStatus && bridgeStatus.bridgeOnline) {
    if (miniBillStatusBadge) {
      if (bridgeStatus.billPrinterReachable) {
        miniBillStatusBadge.className = 'font-bold text-emerald-400 text-[10px]';
        miniBillStatusBadge.textContent = `ONLINE (${bridgeStatus.billPrinterLatencyMs || 2}ms)`;
      } else {
        miniBillStatusBadge.className = 'font-bold text-rose-400 text-[10px]';
        miniBillStatusBadge.textContent = 'OFFLINE';
      }
    }
    if (miniKotStatusBadge) {
      if (bridgeStatus.kotPrinterReachable) {
        miniKotStatusBadge.className = 'font-bold text-emerald-400 text-[10px]';
        miniKotStatusBadge.textContent = `ONLINE (${bridgeStatus.kotPrinterLatencyMs || 2}ms)`;
      } else {
        miniKotStatusBadge.className = 'font-bold text-rose-400 text-[10px]';
        miniKotStatusBadge.textContent = 'OFFLINE';
      }
    }
    if (miniJuiceKotStatusBadge) {
      if (bridgeStatus.juiceKotPrinterReachable) {
        miniJuiceKotStatusBadge.className = 'font-bold text-emerald-400 text-[10px]';
        miniJuiceKotStatusBadge.textContent = `ONLINE (${bridgeStatus.juiceKotPrinterLatencyMs || 2}ms)`;
      } else {
        miniJuiceKotStatusBadge.className = 'font-bold text-rose-400 text-[10px]';
        miniJuiceKotStatusBadge.textContent = 'OFFLINE';
      }
    }
  }

  // Only the automatic check at login accepts a recent result; manual pings and the settings modal always probe live.
  const cachedSuffix = allowCached ? '&cached=1' : '';
  try {
    const [billRes, kotRes, juiceKotRes] = await Promise.allSettled([
      apiRequest('/printer/status?type=BILL' + cachedSuffix),
      apiRequest('/printer/status?type=KOT' + cachedSuffix),
      apiRequest('/printer/status?type=JUICE_KOT' + cachedSuffix)
    ]);

    const billData = billRes.status === 'fulfilled' ? billRes.value : null;
    const kotData = kotRes.status === 'fulfilled' ? kotRes.value : null;
    const juiceKotData = juiceKotRes.status === 'fulfilled' ? juiceKotRes.value : null;

    if (!bridgeStatus || !bridgeStatus.bridgeOnline) {
      if (miniBillStatusBadge) {
        if (billData && billData.success) {
          miniBillStatusBadge.className = 'font-bold text-emerald-400 text-[10px]';
          miniBillStatusBadge.textContent = 'ONLINE (LAN)';
        } else {
          miniBillStatusBadge.className = 'font-bold text-rose-400 text-[10px]';
          miniBillStatusBadge.textContent = 'OFFLINE';
        }
      }
      if (miniKotStatusBadge) {
        if (kotData && kotData.success) {
          miniKotStatusBadge.className = 'font-bold text-emerald-400 text-[10px]';
          miniKotStatusBadge.textContent = 'ONLINE (LAN)';
        } else {
          miniKotStatusBadge.className = 'font-bold text-rose-400 text-[10px]';
          miniKotStatusBadge.textContent = 'OFFLINE';
        }
      }
      if (miniJuiceKotStatusBadge) {
        if (juiceKotData && juiceKotData.success) {
          miniJuiceKotStatusBadge.className = 'font-bold text-emerald-400 text-[10px]';
          miniJuiceKotStatusBadge.textContent = 'ONLINE (LAN)';
        } else {
          miniJuiceKotStatusBadge.className = 'font-bold text-rose-400 text-[10px]';
          miniJuiceKotStatusBadge.textContent = 'OFFLINE';
        }
      }
    }

    // Determine overall system health
    const isBridgeOnline = bridgeStatus && bridgeStatus.bridgeOnline;
    const isBillOnline = isBridgeOnline ? !!bridgeStatus.billPrinterReachable : (billData && billData.success);
    const isKotOnline = isBridgeOnline ? !!bridgeStatus.kotPrinterReachable : (kotData && kotData.success);
    const isJuiceKotOnline = isBridgeOnline ? !!bridgeStatus.juiceKotPrinterReachable : (juiceKotData && juiceKotData.success);

    const offlinePrinters = [];
    if (!isBillOnline) offlinePrinters.push('Bill');
    if (!isKotOnline) offlinePrinters.push('Kitchen KOT');
    if (!isJuiceKotOnline) offlinePrinters.push('Juice KOT');

    if (offlinePrinters.length === 0) {
      if (dot) dot.className = 'w-3 h-3 rounded-full bg-emerald-400 animate-pulse';
      if (text) {
        text.className = 'text-xs font-bold text-emerald-400';
        text.textContent = 'PRINTER SYSTEM ONLINE & READY';
      }
      if (sub) sub.textContent = 'All printers (Bill, Kitchen KOT, Juice KOT) reachable & ready';
      if (headerDot) headerDot.className = 'w-2 h-2 rounded-full bg-emerald-400 animate-pulse';
      if (showToastNotice) {
        showToast('All printers online & reachable!', 'success');
      }
    } else {
      if (dot) dot.className = 'w-3 h-3 rounded-full bg-rose-500';
      if (text) {
        text.className = 'text-xs font-bold text-rose-400';
        text.textContent = 'PRINTER SYSTEM NOTICE / OFFLINE';
      }
      const firstErrMsg = (!isBillOnline && billData?.message) || (!isKotOnline && kotData?.message) || (!isJuiceKotOnline && juiceKotData?.message) || `${offlinePrinters.join(', ')} printer(s) offline or unreachable`;
      if (sub) sub.textContent = firstErrMsg;
      if (headerDot) headerDot.className = 'w-2 h-2 rounded-full bg-rose-500';
      if (showToastNotice) {
        showToast(`${offlinePrinters.join(', ')} printer(s) offline`, 'warning');
      }
    }
  } catch (err) {
    if (dot) dot.className = 'w-3 h-3 rounded-full bg-rose-500';
    if (text) {
      text.className = 'text-xs font-bold text-rose-400';
      text.textContent = 'PRINTER ERROR';
    }
    if (sub) sub.textContent = err.message;
    if (headerDot) headerDot.className = 'w-2 h-2 rounded-full bg-rose-500';
    if (showToastNotice) {
      showToast('Printer check error: ' + err.message, 'error');
    }
  }
}

async function printPhysicalTestPage(type = 'BILL') {
  try {
    const label = type === 'JUICE_KOT' ? 'Juice KOT Printer' : (type === 'KOT' ? 'KOT Kitchen Printer' : 'Bill Counter Printer');
    showToast(`Sending test slip to ${label}...`, 'info');
    const res = await apiRequest(`/printer/test?type=${encodeURIComponent(type)}`, { method: 'POST' });
    if (res && res.success) {
      showToast(`Test slip printed successfully on ${label} (${res.host}:${res.port})!`, 'success');
    } else {
      showToast(`Test print notice: ${res.message}`, 'warning');
    }
  } catch (err) {
    showToast('Failed to print test page: ' + err.message, 'error');
  }
}

function renderCategoryPills() {
  const container = document.getElementById('posCategoryPills');
  container.innerHTML = `
    <button onclick="selectCategory(null)" class="px-3 py-1.5 rounded-lg text-xs font-semibold ${selectedCategoryId === null ? 'bg-amber-500 text-gray-950 shadow-md shadow-amber-500/20' : 'bg-gray-900 text-gray-400 hover:text-white'}">
      All Items
    </button>
  `;

  categories.forEach(cat => {
    const btn = document.createElement('button');
    btn.className = `px-3 py-1.5 rounded-lg text-xs font-semibold whitespace-nowrap ${selectedCategoryId === cat.id ? 'bg-amber-500 text-gray-950 shadow-md shadow-amber-500/20' : 'bg-gray-900 text-gray-400 hover:text-white'}`;
    btn.onclick = () => selectCategory(cat.id);
    btn.innerHTML = `<i class="fa-solid ${escapeHtml(cat.icon || 'fa-utensils')} mr-1"></i>${escapeHtml(cat.name)}`;
    container.appendChild(btn);
  });
}

function selectCategory(id) {
  selectedCategoryId = id;
  renderCategoryPills();
  renderDishesGrid();
}

function handlePosSearchInput() {
  const input = document.getElementById('posSearchInput');
  const clearBtn = document.getElementById('posSearchClearBtn');
  if (clearBtn) {
    if (input && input.value.trim().length > 0) {
      clearBtn.classList.remove('hidden');
    } else {
      clearBtn.classList.add('hidden');
    }
  }
  filterDishes();
}

function clearPosSearch() {
  const input = document.getElementById('posSearchInput');
  const clearBtn = document.getElementById('posSearchClearBtn');
  if (input) {
    input.value = '';
    input.focus();
  }
  if (clearBtn) clearBtn.classList.add('hidden');
  filterDishes();
}

function filterDishes() {
  renderDishesGrid();
}

function renderDishesGrid() {
  const container = document.getElementById('posDishesGrid');
  const query = document.getElementById('posSearchInput')?.value.toLowerCase() || '';

  let filtered = menuItems;
  if (selectedCategoryId !== null) {
    filtered = filtered.filter(item => item.categoryId === selectedCategoryId);
  }
  if (query) {
    filtered = filtered.filter(item => item.name.toLowerCase().includes(query));
  }

  if (filtered.length === 0) {
    container.innerHTML = `<div class="col-span-3 text-center py-12 text-gray-500 text-xs">No dishes found</div>`;
    return;
  }

  const isMobile = window.innerWidth < 640;

  container.innerHTML = filtered.map(item => {
    const isAvail = (item.isAvailable !== false) && (item.active !== false);

    if (!isAvail) {
      if (isMobile) {
        // Mobile compact list row — unavailable
        return `
          <div onclick="showUnavailableDishToast('${escapeHtml(item.name)}')"
               class="flex items-center justify-between px-3 py-2.5 rounded-xl bg-gray-950/80 border border-rose-950/40 opacity-45 cursor-not-allowed select-none"
               title="${escapeHtml(item.name)} is currently unavailable">
            <div class="flex items-center gap-2.5 truncate pr-2">
              <span class="shrink-0 w-3 h-3 border border-${item.isVeg ? 'emerald' : 'rose'}-500/50 flex items-center justify-center rounded-sm">
                <span class="w-1.5 h-1.5 rounded-full bg-${item.isVeg ? 'emerald' : 'rose'}-500/50"></span>
              </span>
              <div class="truncate">
                <h4 class="font-bold text-xs text-gray-400 truncate">${escapeHtml(item.name)}</h4>
                <span class="text-[10px] text-gray-600">${escapeHtml(item.categoryName || '')}</span>
              </div>
            </div>
            <div class="flex items-center gap-2 shrink-0">
              <span class="font-extrabold text-gray-500 text-xs line-through">₹${item.price.toFixed(2)}</span>
              <button disabled type="button" class="w-7 h-7 rounded-lg bg-gray-800 text-gray-600 flex items-center justify-center text-xs cursor-not-allowed">
                <i class="fa-solid fa-lock text-[9px]"></i>
              </button>
            </div>
          </div>
        `;
      }
      return `
        <div onclick="showUnavailableDishToast('${escapeHtml(item.name)}')" 
             class="glass-card p-3 rounded-xl flex flex-col justify-between h-32 opacity-45 bg-gray-950/80 border border-rose-950/40 cursor-not-allowed select-none relative overflow-hidden"
             title="${escapeHtml(item.name)} is currently unavailable / out of stock">
          <div>
            <div class="flex justify-between items-start mb-1">
              <span class="w-3.5 h-3.5 border ${item.isVeg ? 'border-emerald-500/50' : 'border-rose-500/50'} flex items-center justify-center p-0.5 rounded-sm">
                <span class="w-1.5 h-1.5 rounded-full ${item.isVeg ? 'bg-emerald-500/50' : 'bg-rose-500/50'}"></span>
              </span>
              <span class="px-1.5 py-0.5 rounded text-[9px] font-black bg-rose-500/20 text-rose-400 border border-rose-500/30 uppercase tracking-wider flex items-center gap-1">
                <i class="fa-solid fa-ban text-[8px]"></i> Unavailable
              </span>
            </div>
            <h4 class="font-bold text-xs text-gray-400 line-clamp-2">${escapeHtml(item.name)}</h4>
          </div>
          <div class="flex justify-between items-center pt-2 border-t border-gray-800/60">
            <span class="font-extrabold text-gray-500 text-sm line-through">₹${item.price.toFixed(2)}</span>
            <button disabled type="button" class="w-6 h-6 rounded bg-gray-800 text-gray-600 flex items-center justify-center text-xs cursor-not-allowed" title="Item is unavailable">
              <i class="fa-solid fa-lock text-[10px]"></i>
            </button>
          </div>
        </div>
      `;
    }

    if (isMobile) {
      // Mobile compact list row — available
      return `
        <div onclick="addToCart(${item.id})"
             class="flex items-center justify-between px-3 py-2.5 rounded-xl bg-gray-900/70 border border-gray-800 hover:border-amber-500/40 active:scale-[0.98] transition cursor-pointer">
          <div class="flex items-center gap-2.5 truncate pr-2">
            <span class="shrink-0 w-3 h-3 border border-${item.isVeg ? 'emerald' : 'rose'}-500 flex items-center justify-center rounded-sm">
              <span class="w-1.5 h-1.5 rounded-full bg-${item.isVeg ? 'emerald' : 'rose'}-500"></span>
            </span>
            <div class="truncate">
              <h4 class="font-bold text-xs text-white truncate">${escapeHtml(item.name)}</h4>
              <span class="text-[10px] text-gray-400">${escapeHtml(item.categoryName || '')}</span>
            </div>
          </div>
          <div class="flex items-center gap-2.5 shrink-0">
            <span class="font-extrabold text-amber-400 text-xs">₹${item.price.toFixed(2)}</span>
            <button type="button" onclick="event.stopPropagation(); addToCart(${item.id})" class="w-7 h-7 rounded-lg bg-amber-500/20 text-amber-400 hover:bg-amber-500 hover:text-gray-950 flex items-center justify-center text-sm font-bold transition">
              +
            </button>
          </div>
        </div>
      `;
    }

    return `
      <div onclick="addToCart(${item.id})" class="glass-card p-3 rounded-xl cursor-pointer flex flex-col justify-between h-32 hover:border-amber-500/50 transition">
        <div>
          <div class="flex justify-between items-start mb-1">
            <span class="w-3.5 h-3.5 border ${item.isVeg ? 'border-emerald-500' : 'border-rose-500'} flex items-center justify-center p-0.5 rounded-sm">
              <span class="w-1.5 h-1.5 rounded-full ${item.isVeg ? 'bg-emerald-500' : 'bg-rose-500'}"></span>
            </span>
            <span class="text-[10px] text-gray-400 truncate max-w-[80px]">${escapeHtml(item.categoryName || '')}</span>
          </div>
          <h4 class="font-bold text-xs text-white line-clamp-2">${escapeHtml(item.name)}</h4>
        </div>
        <div class="flex justify-between items-center pt-2 border-t border-gray-800">
          <span class="font-extrabold text-amber-400 text-sm">₹${item.price.toFixed(2)}</span>
          <button type="button" class="w-6 h-6 rounded bg-amber-500/20 text-amber-400 hover:bg-amber-500 hover:text-gray-950 flex items-center justify-center text-xs transition">
            <i class="fa-solid fa-plus"></i>
          </button>
        </div>
      </div>
    `;
  }).join('');

  if (isMobile) {
    // Add generous bottom spacing so the last dishes scroll completely above the Take Order bar
    container.innerHTML += `<div class="h-28 sm:hidden pointer-events-none" aria-hidden="true"></div>`;
  }
}

function showUnavailableDishToast(dishName) {
  showToast(`"${dishName}" is currently unavailable/out of stock and cannot be added to orders.`, 'warning');
}

function addToCart(itemId) {
  if (currentTableOrder && currentTableOrder.status === 'BILL_PRINTED') {
    showToast('Bill is already printed for this table. Manager must confirm payment before placing new orders.', 'warning');
    return;
  }

  if (currentOrderLocation === 'TABLE') {
    const tableNo = document.getElementById('cartTableNo')?.value?.trim();
    if (!tableNo) {
      pendingDishToAddAfterTableSelect = itemId;
      const dish = menuItems.find(m => m.id === itemId);
      const dishName = dish ? dish.name : 'dish';
      showToast(`Please select a table to add "${dishName}"`, 'info');
      openMobileTablePicker(`Select table for "${dishName}":`);
      return;
    }
  } else if (currentOrderLocation === 'OUTDOOR') {
    const cust = document.getElementById('cartCustomer')?.value?.trim();
    if (!cust) {
      showToast('Customer name is required for outdoor orders.', 'error');
      document.getElementById('cartCustomer')?.focus();
      return;
    }
  } else if (currentOrderLocation === 'TAKEAWAY') {
    if (!currentTakeawayToken) {
      currentTakeawayToken = nextTakeawayTokenPreview || 'TAK-001';
      const tokEl = document.getElementById('cartTakeawayTokenDisplay');
      if (tokEl) tokEl.textContent = currentTakeawayToken;
    }
  }

  const dish = menuItems.find(m => m.id === itemId);
  if (!dish) return;

  if (dish.isAvailable === false || dish.active === false) {
    showToast(`"${dish.name}" is currently unavailable and cannot be added to orders.`, 'warning');
    return;
  }

  isCartDirty = true;
  const isTakeawayDefault = (currentOrderLocation === 'TAKEAWAY');
  const existing = cart.find(c => c.item.id === itemId && Boolean(c.isTakeaway) === isTakeawayDefault);
  if (existing) {
    existing.quantity += 1;
  } else {
    cart.push({
      item: dish,
      quantity: 1,
      customization: '',
      isTakeaway: isTakeawayDefault
    });
  }

  renderCart();
}

function updateCartCustomization(indexOrId, value) {
  let item = null;
  if (typeof indexOrId === 'number' && indexOrId >= 0 && indexOrId < cart.length && cart[indexOrId]) {
    item = cart[indexOrId];
  } else {
    item = cart.find(c => c.item.id === indexOrId);
  }
  if (item) {
    item.customization = value;
    isCartDirty = true;
    updateKotButtonState();
  }
}

function updateCartQuantity(indexOrId, delta) {
  let item = null;
  if (typeof indexOrId === 'number' && indexOrId >= 0 && indexOrId < cart.length && cart[indexOrId]) {
    item = cart[indexOrId];
  } else {
    item = cart.find(c => c.item.id === indexOrId);
  }
  if (!item) return;

  isCartDirty = true;
  item.quantity += delta;
  if (item.quantity <= 0) {
    cart = cart.filter(c => c !== item);
  }

  renderCart();
}

function removeFromCart(indexOrId) {
  isCartDirty = true;
  if (typeof indexOrId === 'number' && indexOrId >= 0 && indexOrId < cart.length && cart[indexOrId]) {
    cart.splice(indexOrId, 1);
  } else {
    cart = cart.filter(c => c.item.id !== indexOrId);
  }
  renderCart();
}

function toggleCartItemTakeaway(indexOrId) {
  let item = null;
  if (typeof indexOrId === 'number' && indexOrId >= 0 && indexOrId < cart.length && cart[indexOrId]) {
    item = cart[indexOrId];
  } else {
    item = cart.find(c => c.item.id === indexOrId);
  }
  if (!item) return;

  isCartDirty = true;
  item.isTakeaway = !item.isTakeaway;
  renderCart();
}

async function clearCart() {
  if (currentOrderLocation === 'TAKEAWAY') {
    let liveOrder = currentTableOrder;
    if (liveOrder && liveOrder.id) {
      const status = liveOrder.status;
      if (status !== 'ACTIVE') {
        showToast(`Cannot clear — order is in "${status.replace(/_/g, ' ')}" stage. Complete the bill workflow first.`, 'error');
        return;
      }

      if (!confirm(`Cancel the saved takeaway order for ${liveOrder.customerName || 'Guest'} (${liveOrder.takeawayToken || currentTakeawayToken || 'TAK'})?\nThis will remove the order permanently.`)) return;

      activeOrders = activeOrders.filter(o => o.id !== liveOrder.id);
      const cancelId = liveOrder.id;
      const cancelDesc = `${liveOrder.customerName || 'Guest'} (${liveOrder.takeawayToken || currentTakeawayToken || 'TAK'})`;
      currentTableOrder = null;
      currentTakeawayToken = null;
      cart = [];
      isCartDirty = false;

      const c1 = document.getElementById('cartCustomer'); if (c1) c1.value = '';
      const c2 = document.getElementById('cartDiscountPct'); if (c2) c2.value = 0;
      const cNotes = document.getElementById('cartOrderNotes'); if (cNotes) cNotes.value = '';
      syncCartGstUI();
      syncTableOrderState('');
      renderTakeawayBadges();
      renderCart();

      apiRequest(`/bills/${cancelId}/cancel`, { method: 'POST' })
        .then(() => {
          showToast(`Takeaway order for ${cancelDesc} cancelled.`, 'info');
        })
        .catch(err => {
          showToast('Server cancel failed: ' + err.message, 'error');
          refreshActiveOrders();
        });

      return;
    }

    // Unsaved takeaway cart
    cart = [];
    isCartDirty = false;
    currentTableOrder = null;
    currentTakeawayToken = null;
    const d1 = document.getElementById('cartCustomer'); if (d1) d1.value = '';
    const d2 = document.getElementById('cartDiscountPct'); if (d2) d2.value = 0;
    const dNotes = document.getElementById('cartOrderNotes'); if (dNotes) dNotes.value = '';
    syncCartGstUI();
    syncTableOrderState('');
    renderTakeawayBadges();
    renderCart();
    return;
  }

  if (currentOrderLocation === 'OUTDOOR') {
    let liveOrder = currentTableOrder;
    if (liveOrder && liveOrder.id) {
      const status = liveOrder.status;
      if (status !== 'ACTIVE') {
        showToast(`Cannot clear — order is in "${status.replace(/_/g, ' ')}" stage. Complete the bill workflow first.`, 'error');
        return;
      }

      if (!confirm(`Cancel the saved outdoor order for ${liveOrder.customerName || 'Customer'} (${liveOrder.outdoorToken || 'OUT'})?\nThis will remove the order permanently.`)) return;

      activeOrders = activeOrders.filter(o => o.id !== liveOrder.id);
      const cancelId = liveOrder.id;
      const cancelDesc = `${liveOrder.customerName || ''} (${liveOrder.outdoorToken || ''})`;
      currentTableOrder = null;
      currentOutdoorToken = null;
      cart = [];
      isCartDirty = false;

      const c1 = document.getElementById('cartCustomer'); if (c1) c1.value = '';
      const c2 = document.getElementById('cartDiscountPct'); if (c2) c2.value = 0;
      const cNotes = document.getElementById('cartOrderNotes'); if (cNotes) cNotes.value = '';
      syncCartGstUI();
      syncTableOrderState('');
      renderOutdoorBadges();
      renderCart();

      apiRequest(`/bills/${cancelId}/cancel`, { method: 'POST' })
        .then(() => {
          showToast(`Outdoor order for ${cancelDesc} cancelled.`, 'info');
        })
        .catch(err => {
          showToast('Server cancel failed: ' + err.message, 'error');
          refreshActiveOrders();
        });

      return;
    }

    // Unsaved outdoor cart
    cart = [];
    isCartDirty = false;
    currentTableOrder = null;
    currentOutdoorToken = null;
    const d1 = document.getElementById('cartCustomer'); if (d1) d1.value = '';
    const d2 = document.getElementById('cartDiscountPct'); if (d2) d2.value = 0;
    const dNotes = document.getElementById('cartOrderNotes'); if (dNotes) dNotes.value = '';
    syncCartGstUI();
    syncTableOrderState('');
    renderOutdoorBadges();
    renderCart();
    return;
  }

  // Read current table from dropdown
  const sel = document.getElementById('cartTableNo');
  const tableNo = sel?.value?.trim() || '';

  // Find the live order: first from activeOrders by table name, then fallback to currentTableOrder
  let liveOrder = tableNo ? activeOrders.find(o => o.tableNumber === tableNo) : null;
  if (!liveOrder && currentTableOrder?.id) {
    liveOrder = currentTableOrder;
  }

  if (liveOrder) {
    const status = liveOrder.status;

    // Block clearing in-progress orders
    if (status !== 'ACTIVE') {
      showToast(`Cannot clear — order is in "${status.replace(/_/g, ' ')}" stage. Complete the bill workflow first.`, 'error');
      return;
    }

    if (!confirm(`Cancel the saved order for Table ${liveOrder.tableNumber || tableNo}?\nThis will remove the order permanently.`)) return;

    // STEP 1: Wipe from in-memory state IMMEDIATELY (before ANY await)
    activeOrders = activeOrders.filter(o => o.id !== liveOrder.id);
    currentTableOrder = null;
    cart = [];
    isCartDirty = false;

    // STEP 2: Reset all UI fields right now
    loadTableOptions('');
    const c1 = document.getElementById('cartCustomer'); if (c1) c1.value = '';
    const c2 = document.getElementById('cartDiscountPct'); if (c2) c2.value = 0;
    const cNotes = document.getElementById('cartOrderNotes'); if (cNotes) cNotes.value = '';
    syncCartGstUI();
    syncTableOrderState('');
    renderTableBadges();   // badge turns grey NOW
    renderCart();          // cart empty NOW

    // STEP 3: Tell the backend to cancel/delete — fire-and-forget style
    // (UI is already correct; we do NOT call refreshActiveOrders on success
    //  because that would re-fetch from server and could momentarily restore the badge)
    apiRequest(`/bills/${liveOrder.id}/cancel`, { method: 'POST' })
      .then(() => {
        showToast(`Order for Table ${liveOrder.tableNumber || tableNo} cancelled.`, 'info');
      })
      .catch(err => {
        showToast('Server cancel failed: ' + err.message, 'error');
        // Only refresh on error to restore server state
        refreshActiveOrders();
      });

    return;
  }

  // No saved order on server — just reset the local cart & UI
  cart = [];
  isCartDirty = false;
  currentTableOrder = null;
  loadTableOptions('');
  const d1 = document.getElementById('cartCustomer'); if (d1) d1.value = '';
  const d2 = document.getElementById('cartDiscountPct'); if (d2) d2.value = 0;
  const dNotes = document.getElementById('cartOrderNotes'); if (dNotes) dNotes.value = '';
  syncCartGstUI();
  syncTableOrderState('');
  renderTableBadges();   // re-render badges even for unsaved carts
  renderCart();
}







function handleGstChange() {
  const gstSel = document.getElementById('cartGstSelect')?.value;
  const customGst = document.getElementById('cartGstCustom');
  if (customGst) {
    if (gstSel === 'custom') {
      customGst.classList.remove('hidden');
      customGst.focus();
    } else {
      customGst.classList.add('hidden');
    }
  }
  recalculateCart();
}

function recalculateCart() {
  renderCart();
}

function renderCart() {
  const list = document.getElementById('cartItemsList');

  if (currentTableOrder && currentTableOrder.status === 'BILL_PRINTED') {
    list.innerHTML = `
      <div class="text-center py-1 text-amber-400 text-[11px] font-semibold flex items-center justify-center gap-1.5 bg-amber-500/10 rounded border border-amber-500/20">
        <i class="fa-solid fa-receipt text-[10px]"></i>
        <span>Bill #${currentTableOrder.billNumber || ''} Printed • Awaiting Payment</span>
      </div>
    `;
    const net = (currentTableOrder.netAmount || 0).toFixed(2);
    document.getElementById('cartSubtotal').textContent = `₹${(currentTableOrder.subtotal || 0).toFixed(2)}`;
    document.getElementById('cartTax').textContent = `₹${(currentTableOrder.taxAmount || 0).toFixed(2)}`;
    document.getElementById('cartTotal').textContent = `₹${net}`;

    const pRow = document.getElementById('cartParcelChargeRow');
    const pInp = document.getElementById('cartParcelChargeInput');
    if (currentTableOrder.parcelCharge && Number(currentTableOrder.parcelCharge) > 0) {
      if (pRow) pRow.classList.remove('hidden');
      if (pInp) pInp.value = Number(currentTableOrder.parcelCharge).toFixed(2);
    } else {
      if (pRow) pRow.classList.add('hidden');
    }

    const mobileCountEl = document.getElementById('mobileCartItemCount');
    const mobileTotalEl = document.getElementById('mobileCartTotal');
    if (mobileCountEl) mobileCountEl.textContent = '0';
    if (mobileTotalEl) mobileTotalEl.textContent = `₹${net}`;
    renderMobileTableControls();
    updateKotButtonState();
    return;
  }

  if (cart.length === 0) {
    list.innerHTML = `
      <div class="text-center py-2 text-gray-500 text-xs flex items-center justify-center gap-1.5">
        <i class="fa-solid fa-basket-shopping text-gray-600 text-xs"></i>
        <span>No items added to order</span>
      </div>
    `;
    document.getElementById('cartSubtotal').textContent = '₹0.00';
    document.getElementById('cartTax').textContent = '₹0.00';
    document.getElementById('cartTotal').textContent = '₹0.00';

    const pRow = document.getElementById('cartParcelChargeRow');
    if (pRow) pRow.classList.add('hidden');

    // Update floating mobile cart indicator
    const mobileCountEl = document.getElementById('mobileCartItemCount');
    const mobileTotalEl = document.getElementById('mobileCartTotal');
    if (mobileCountEl) mobileCountEl.textContent = '0';
    if (mobileTotalEl) mobileTotalEl.textContent = '₹0.00';
    renderMobileTableControls();
    updateKotButtonState();
    return;
  }

  let subtotal = 0;
  let totalItemsCount = 0;
  list.innerHTML = cart.map(({ item, quantity, customization, isTakeaway }, idx) => {
    const lineTotal = item.price * quantity;
    subtotal += lineTotal;
    totalItemsCount += quantity;
    const custVal = customization || '';
    const isParcel = currentOrderLocation === 'TAKEAWAY' || Boolean(isTakeaway);
    return `
      <div class="px-2.5 py-2 rounded-lg bg-gray-900/60 border border-gray-800 transition">
        <div class="flex items-center justify-between gap-1">
          <div class="flex-1 truncate">
            <div class="flex items-center gap-1.5 truncate">
              <p class="font-bold text-white truncate text-sm">${escapeHtml(item.name)}</p>
              ${isParcel ? `<span class="px-1 py-0.2 rounded text-[8px] font-black bg-purple-500/20 text-purple-300 border border-purple-500/40 shrink-0">PARCEL</span>` : ''}
            </div>
            <span class="text-[9px] text-gray-500">₹${item.price.toFixed(2)} each</span>
          </div>
          <div class="flex items-center gap-1.5 shrink-0">
            <div class="flex items-center bg-gray-800 rounded border border-gray-700">
              <button type="button" onclick="updateCartQuantity(${idx}, -1)" class="w-6 h-6 flex items-center justify-center text-gray-300 hover:text-white text-base leading-none">−</button>
              <span class="px-1.5 text-xs font-bold text-amber-400">${quantity}</span>
              <button type="button" onclick="updateCartQuantity(${idx}, 1)" class="w-6 h-6 flex items-center justify-center text-gray-300 hover:text-white text-base leading-none">+</button>
            </div>
            <span class="w-14 text-right font-bold text-white text-xs">₹${lineTotal.toFixed(2)}</span>
            <button type="button" onclick="removeFromCart(${idx})" class="text-rose-400 hover:text-rose-300 w-6 h-6 flex items-center justify-center" title="Remove item">
              <i class="fa-regular fa-trash-can text-[10px]"></i>
            </button>
          </div>
        </div>
        <div class="flex items-center justify-between gap-2 mt-1">
          <div class="flex items-center gap-1 flex-1">
            <i class="fa-solid fa-pen-to-square text-[8px] text-amber-500/50 shrink-0"></i>
            <input 
              type="text" 
              placeholder="Note (e.g. less sugar)..." 
              value="${escapeHtml(custVal)}"
              oninput="updateCartCustomization(${idx}, this.value)"
              class="glass-input w-full px-1.5 py-0.5 text-[9px] rounded-md bg-gray-950/60 border border-gray-800/80 focus:border-amber-500/50 text-gray-300 placeholder-gray-600 focus:outline-none leading-tight"
            />
          </div>
          <div class="shrink-0">
            ${currentOrderLocation === 'TAKEAWAY'
        ? `<span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-purple-500/20 text-purple-300 border border-purple-500/30 flex items-center gap-1">🥡 Parcel</span>`
        : `<button type="button" onclick="toggleCartItemTakeaway(${idx})" class="px-1.5 py-0.5 rounded text-[9px] font-semibold transition flex items-center gap-1 ${isParcel ? 'bg-purple-600 text-white font-bold shadow-sm shadow-purple-900/50 hover:bg-purple-500' : 'bg-gray-800 text-gray-400 border border-gray-700 hover:text-white hover:border-gray-600'}" title="${isParcel ? 'Click to serve dine-in' : 'Click to pack as parcel for table customer'}">
                  <i class="fa-solid ${isParcel ? 'fa-box' : 'fa-utensils'} text-[8px]"></i>
                  <span>${isParcel ? 'Parcel' : 'Dine-in'}</span>
                </button>`
      }
          </div>
        </div>
      </div>
    `;
  }).join('');

  const isMgr = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  let discountPct = 0;
  if (isMgr) {
    discountPct = parseFloat(document.getElementById('cartDiscountPct')?.value || 0);
  } else if (currentTableOrder && currentTableOrder.discountPercent) {
    discountPct = currentTableOrder.discountPercent;
  }
  if (isNaN(discountPct) || discountPct < 0) discountPct = 0;

  const discountAmt = (subtotal * discountPct) / 100.0;
  const taxable = Math.max(0, subtotal - discountAmt);

  let gstPct = 0;
  if (isMgr) {
    const gstSel = document.getElementById('cartGstSelect')?.value || '0';
    if (gstSel === 'custom') {
      gstPct = parseFloat(document.getElementById('cartGstCustom')?.value || 0);
    } else {
      gstPct = parseFloat(gstSel);
    }
  } else {
    // For staff, use standard configured GST rate or existing order rate
    if (currentTableOrder && currentTableOrder.taxPercent != null) {
      gstPct = currentTableOrder.taxPercent;
    } else if (currentGstConfig && currentGstConfig.enabled) {
      gstPct = currentGstConfig.taxPercent || 0;
    } else {
      gstPct = 0;
    }
  }
  if (isNaN(gstPct) || gstPct < 0) gstPct = 0;

  const tax = Math.round(((taxable * gstPct) / 100.0) * 100) / 100;

  // Parcel charge logic
  const hasParcel = currentOrderLocation === 'TAKEAWAY' || cart.some(c => Boolean(c.isTakeaway));
  const parcelRow = document.getElementById('cartParcelChargeRow');
  const parcelInput = document.getElementById('cartParcelChargeInput');
  let parcelCharge = 0;
  if (hasParcel) {
    if (parcelRow) parcelRow.classList.remove('hidden');
    let pVal = parseFloat(parcelInput ? parcelInput.value : '');
    if (isNaN(pVal) || pVal < 0) {
      pVal = defaultParcelCharge || 10.0;
      if (parcelInput) parcelInput.value = pVal.toFixed(2);
    }
    parcelCharge = pVal;
  } else {
    if (parcelRow) parcelRow.classList.add('hidden');
    parcelCharge = 0;
  }

  const netTotal = Math.round((taxable + tax + parcelCharge) * 100) / 100;

  document.getElementById('cartSubtotal').textContent = `₹${subtotal.toFixed(2)}`;
  document.getElementById('cartTax').textContent = `₹${tax.toFixed(2)}`;
  document.getElementById('cartTotal').textContent = `₹${netTotal.toFixed(2)}`;

  const staffTaxVal = document.getElementById('cartStaffTax');
  if (staffTaxVal) {
    staffTaxVal.textContent = gstPct > 0 ? `(${gstPct}%) ₹${tax.toFixed(2)}` : '₹0.00';
  }

  // Update floating mobile cart indicator
  const mobileCountEl = document.getElementById('mobileCartItemCount');
  const mobileTotalEl = document.getElementById('mobileCartTotal');
  if (mobileCountEl) mobileCountEl.textContent = totalItemsCount;
  if (mobileTotalEl) mobileTotalEl.textContent = `₹${netTotal.toFixed(2)}`;
  renderMobileTableControls();
  updateKotButtonState();
}

// ============================================================
// TAB 2: BILL LOG (DAILY & MONTHLY)
// ============================================================
function loadBillsView(mode) {
  currentBillsMode = mode;
  const btnDaily = document.getElementById('btnBillDaily');
  const btnMonthly = document.getElementById('btnBillMonthly');

  if (mode === 'daily') {
    btnDaily.className = 'px-3 py-1 rounded bg-amber-500 text-gray-950 font-bold';
    btnMonthly.className = 'px-3 py-1 rounded text-gray-400 hover:text-white';
    document.getElementById('billsFilterDate').type = 'date';
    if (!document.getElementById('billsFilterDate').value) {
      document.getElementById('billsFilterDate').value = new Date().toISOString().split('T')[0];
    }
  } else {
    btnMonthly.className = 'px-3 py-1 rounded bg-amber-500 text-gray-950 font-bold';
    btnDaily.className = 'px-3 py-1 rounded text-gray-400 hover:text-white';
    document.getElementById('billsFilterDate').type = 'month';
    if (!document.getElementById('billsFilterDate').value) {
      document.getElementById('billsFilterDate').value = new Date().toISOString().slice(0, 7);
    }
  }

  fetchBillsByCurrentFilter();
  loadPromotions();
}

function setBillsLocationFilter(filter) {
  billsLocationFilter = filter;
  const btnAll = document.getElementById('btnBillLocAll');
  const btnTable = document.getElementById('btnBillLocTable');
  const btnOutdoor = document.getElementById('btnBillLocOutdoor');
  const btnTakeaway = document.getElementById('btnBillLocTakeaway');

  [btnAll, btnTable, btnOutdoor, btnTakeaway].forEach(b => {
    if (b) b.className = 'px-2.5 py-1 rounded text-gray-400 hover:text-white';
  });

  if (filter === 'ALL' && btnAll) btnAll.className = 'px-2.5 py-1 rounded bg-amber-500 text-gray-950 font-bold';
  if (filter === 'TABLE' && btnTable) btnTable.className = 'px-2.5 py-1 rounded bg-amber-500 text-gray-950 font-bold';
  if (filter === 'OUTDOOR' && btnOutdoor) btnOutdoor.className = 'px-2.5 py-1 rounded bg-amber-500 text-gray-950 font-bold';
  if (filter === 'TAKEAWAY' && btnTakeaway) btnTakeaway.className = 'px-2.5 py-1 rounded bg-amber-500 text-gray-950 font-bold';

  filterAndRenderBills();
}

function filterAndRenderBills() {
  let list = cachedBillsList || [];

  if (billsLocationFilter === 'TABLE') {
    list = list.filter(b => b.orderType !== 'OUTDOOR' && b.orderType !== 'TAKEAWAY' && !b.outdoorToken && !b.takeawayToken && Boolean(b.tableNumber));
  } else if (billsLocationFilter === 'OUTDOOR') {
    list = list.filter(b => b.orderType === 'OUTDOOR' || Boolean(b.outdoorToken));
  } else if (billsLocationFilter === 'TAKEAWAY') {
    list = list.filter(b => b.orderType === 'TAKEAWAY' || Boolean(b.takeawayToken));
  }

  const staffFilter = (document.getElementById('billsStaffFilter')?.value || '').trim();
  if (staffFilter) {
    list = list.filter(b => (b.createdByName === staffFilter || b.printedByName === staffFilter));
  }

  const query = (document.getElementById('billsSearchInput')?.value || '').trim().toLowerCase();
  if (query) {
    list = list.filter(b => {
      const cust = (b.customerName || '').toLowerCase();
      const token = (b.outdoorToken || '').toLowerCase();
      const takeawayTok = (b.takeawayToken || '').toLowerCase();
      const billNo = String(b.billNumber || '').toLowerCase();
      const table = (b.tableNumber || '').toLowerCase();
      const createdBy = (b.createdByName || '').toLowerCase();
      const printedBy = (b.printedByName || '').toLowerCase();
      return cust.includes(query) || token.includes(query) || takeawayTok.includes(query) || billNo.includes(query) || table.includes(query) || createdBy.includes(query) || printedBy.includes(query);
    });
  }

  renderBillsTable(list);
}

function populateBillsStaffFilter(bills) {
  const select = document.getElementById('billsStaffFilter');
  if (!select) return;
  const currentVal = select.value;
  const staffSet = new Set();
  (bills || []).forEach(b => {
    if (b.createdByName && b.createdByName.trim()) staffSet.add(b.createdByName.trim());
    if (b.printedByName && b.printedByName.trim() && !b.printedByName.includes('Pending')) staffSet.add(b.printedByName.trim());
  });
  const sortedStaff = Array.from(staffSet).sort((a, b) => a.localeCompare(b));
  select.innerHTML = '<option value="">All Users / Staff</option>' +
    sortedStaff.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join('');
  if (currentVal && staffSet.has(currentVal)) {
    select.value = currentVal;
  }
}

async function fetchBillsByCurrentFilter() {
  const dateVal = document.getElementById('billsFilterDate').value;
  let endpoint = '/bills';

  if (currentBillsMode === 'daily') {
    endpoint = dateVal ? `/bills/daily?date=${dateVal}` : '/bills/daily';
  } else {
    if (dateVal) {
      const [year, month] = dateVal.split('-');
      endpoint = `/bills/monthly?year=${year}&month=${month}`;
    } else {
      endpoint = `/bills/monthly`;
    }
  }

  try {
    const bills = await apiRequest(endpoint);
    cachedBillsList = bills || [];
    populateBillsStaffFilter(cachedBillsList);
    filterAndRenderBills();
  } catch (err) {
    showToast('Failed to load bills: ' + err.message, 'error');
  }
}

function renderBillsTable(bills) {
  const tbody = document.getElementById('billsTableBody');
  const countEl = document.getElementById('statBillCount');
  const revEl = document.getElementById('statBillRevenue');
  const avgEl = document.getElementById('statBillAvg');

  const totalRev = bills.filter(b => b.status === 'PAID' || b.status === 'PARTIALLY_REFUNDED')
    .reduce((sum, b) => sum + (Number(b.netAmount) - (Number(b.totalRefunded) || 0)), 0);
  const count = bills.length;
  const avg = count > 0 ? totalRev / count : 0;

  countEl.textContent = count;
  revEl.textContent = `₹${totalRev.toFixed(2)}`;
  avgEl.textContent = `₹${avg.toFixed(2)}`;

  if (bills.length === 0) {
    tbody.innerHTML = `<tr><td colspan="10" class="text-center py-8 text-gray-500">No bills found for selected period</td></tr>`;
    return;
  }

  tbody.innerHTML = bills.map(b => {
    const isPaid = b.status === 'PAID';
    const isPartiallyRefunded = b.status === 'PARTIALLY_REFUNDED';
    const isRefunded = b.status === 'REFUNDED';
    const isSettled = isPaid || isPartiallyRefunded || isRefunded;
    const isActive = b.status === 'ACTIVE';

    let badgeClass = 'bg-gray-500/20 text-gray-400';
    if (isPaid) badgeClass = 'bg-emerald-500/20 text-emerald-400';
    else if (isPartiallyRefunded) badgeClass = 'bg-amber-500/20 text-amber-400';
    else if (isRefunded) badgeClass = 'bg-rose-500/20 text-rose-400';
    else if (isActive) badgeClass = 'bg-blue-500/20 text-blue-400';

    return `
    <tr class="hover:bg-gray-800/40">
      <td class="p-3 font-mono font-bold text-amber-400">${b.billNumber}</td>
      <td class="p-3">${formatISTDateTime(b.createdAt)}</td>
      <td class="p-3">
        ${b.orderType === 'OUTDOOR' || b.outdoorToken
        ? `<div class="flex items-center space-x-1.5"><span class="px-1.5 py-0.5 rounded text-[9px] font-black bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">OUTDOOR</span><span class="font-mono text-xs font-bold text-emerald-300">${escapeHtml(b.outdoorToken || '')}</span></div>${b.customerName ? `<div class="text-[11px] font-semibold text-white mt-0.5">${escapeHtml(b.customerName)}</div>` : ''}`
        : (b.orderType === 'TAKEAWAY' || b.takeawayToken
          ? `<div class="flex items-center space-x-1.5"><span class="px-1.5 py-0.5 rounded text-[9px] font-black bg-purple-500/20 text-purple-400 border border-purple-500/30">TAKEAWAY</span><span class="font-mono text-xs font-bold text-purple-300">${escapeHtml(b.takeawayToken || '')}</span></div>${b.customerName ? `<div class="text-[11px] font-semibold text-white mt-0.5">${escapeHtml(b.customerName)}</div>` : ''}`
          : `<div><span class="font-semibold text-white">${escapeHtml(b.tableNumber || '-')}</span>${b.customerName ? `<div class="text-[11px] text-gray-400">${escapeHtml(b.customerName)}</div>` : ''}</div>`)
      }
      </td>
      <td class="p-3 font-medium text-amber-300"><i class="fa-solid fa-user-check text-[10px] text-amber-400 mr-1"></i>${escapeHtml(b.createdByName || 'Staff')}</td>
      <td class="p-3 font-medium text-cyan-300"><i class="fa-solid fa-user-shield text-[10px] text-cyan-400 mr-1"></i>${escapeHtml(b.printedByName || 'Pending / Staff')}</td>
      <td class="p-3">${b.items?.length || 0} items</td>
      <td class="p-3"><span class="px-2 py-0.5 rounded text-[10px] font-bold bg-gray-800 text-gray-300">${b.paymentMode}</span></td>
      <td class="p-3 font-bold text-white">₹${Number(b.netAmount || 0).toFixed(2)}</td>
      <td class="p-3">
        <span class="px-2 py-0.5 rounded text-[10px] font-bold ${badgeClass}">
          ${b.status}
        </span>
        ${b.totalRefunded && Number(b.totalRefunded) > 0 ? `<div class="text-[10px] text-rose-400 mt-0.5 font-mono">Ref: ₹${Number(b.totalRefunded).toFixed(2)}</div>` : ''}
      </td>
      <td class="p-3 text-right space-x-1 whitespace-nowrap">
        <button onclick="reprintBill(${b.id})" class="px-2 py-1 rounded bg-amber-500/20 hover:bg-amber-500/30 text-amber-300 text-[11px]" title="Print Receipt">
          <i class="fa-solid fa-print"></i>
        </button>
        ${!isRefunded ? `
          <button onclick="openEditBillModal(${b.id})" class="px-2 py-1 rounded bg-blue-500/20 hover:bg-blue-500/30 text-blue-300 text-[11px]" title="Edit Bill Details">
            <i class="fa-solid fa-pen-to-square"></i>
          </button>
        ` : ''}
        ${(isPaid || isPartiallyRefunded) ? `
          <button onclick="openBillRefundModal(${b.id})" class="px-2 py-1 rounded bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 text-[11px] font-semibold" title="Auditable Refund">
            <i class="fa-solid fa-rotate-left mr-0.5"></i> Refund
          </button>
        ` : ''}
        ${isActive ? `
          <button onclick="openVoidOrderModal(${b.id}, '${escapeHtml(b.billNumber)}')" class="px-2 py-1 rounded bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 text-[11px] font-semibold" title="Void Unpaid Order">
            <i class="fa-solid fa-ban mr-0.5"></i> Void
          </button>
        ` : ''}
        ${currentUser && currentUser.role === 'ADMIN' && !isSettled ? `
          <button onclick="deleteBill(${b.id})" class="px-2 py-1 rounded bg-red-700/20 hover:bg-red-700/30 text-red-300 text-[11px]" title="Delete Bill (Admin)">
            <i class="fa-solid fa-trash-can"></i>
          </button>
        ` : ''}
      </td>
    </tr>
  `;
  }).join('');
}

async function reprintBill(id) {
  try {
    const bill = await apiRequest(`/bills/${id}`);
    displayReceiptModal(bill);
  } catch (err) {
    showToast('Failed to fetch bill receipt: ' + err.message, 'error');
  }
}

// ============================================================
// PROMOTIONS MANAGEMENT (Admin / Manager Only in Bill Log Area)
// ============================================================

let cachedPromotionsList = [];

async function loadPromotions() {
  const section = document.getElementById('promotionsManagementSection');
  if (!section) return;

  const isMgrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  if (!isMgrAdmin) {
    section.classList.add('hidden');
    return;
  }
  section.classList.remove('hidden');

  const tbody = document.getElementById('promotionsTableBody');
  const banner = document.getElementById('activePromotionBanner');
  const bannerText = document.getElementById('activePromotionBannerText');

  try {
    const list = await apiRequest('/promotions');
    cachedPromotionsList = list || [];

    // Check if any promotion is currently active
    const activePromo = cachedPromotionsList.find(p => p.status === 'ACTIVE');
    if (activePromo && banner && bannerText) {
      bannerText.textContent = `${activePromo.name} (${activePromo.discountPercentage}%)`;
      banner.classList.remove('hidden');
    } else if (banner) {
      banner.classList.add('hidden');
    }

    if (!tbody) return;
    if (cachedPromotionsList.length === 0) {
      tbody.innerHTML = `<tr><td colspan="6" class="text-center py-5 text-gray-500">No promotions created yet. Click "New Promotion" to schedule customer discounts.</td></tr>`;
      return;
    }

    tbody.innerHTML = cachedPromotionsList.map(p => {
      let badgeClass = 'bg-gray-500/20 text-gray-400 border border-gray-600/30';
      if (p.status === 'ACTIVE') badgeClass = 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 font-black';
      else if (p.status === 'SCHEDULED') badgeClass = 'bg-blue-500/20 text-blue-400 border border-blue-500/30';
      else if (p.status === 'EXPIRED') badgeClass = 'bg-rose-500/20 text-rose-400 border border-rose-500/30';
      else if (p.status === 'INACTIVE') badgeClass = 'bg-gray-700/30 text-gray-400 border border-gray-700';

      const startStr = formatISTDateTime(p.startDateTime);
      const endStr = formatISTDateTime(p.endDateTime);

      return `
        <tr class="hover:bg-gray-800/40">
          <td class="p-2.5 font-semibold text-white">
            ${escapeHtml(p.name)}
            ${p.description ? `<div class="text-[10px] text-gray-400 font-normal">${escapeHtml(p.description)}</div>` : ''}
          </td>
          <td class="p-2.5 text-center font-bold text-amber-400 font-mono text-sm">${p.discountPercentage}%</td>
          <td class="p-2.5 font-mono text-[11px] text-gray-300">${startStr}</td>
          <td class="p-2.5 font-mono text-[11px] text-gray-300">${endStr}</td>
          <td class="p-2.5 text-center">
            <span class="px-2 py-0.5 rounded text-[10px] font-bold ${badgeClass}">
              ${p.status}
            </span>
          </td>
          <td class="p-2.5 text-right space-x-1 whitespace-nowrap">
            <button onclick="togglePromotionActive(${p.id})" class="px-2 py-1 rounded ${p.isActive ? 'bg-amber-500/20 text-amber-300 hover:bg-amber-500/30' : 'bg-emerald-500/20 text-emerald-300 hover:bg-emerald-500/30'} text-[11px] font-semibold" title="${p.isActive ? 'Deactivate' : 'Activate'}">
              <i class="fa-solid ${p.isActive ? 'fa-pause' : 'fa-play'} mr-0.5"></i> ${p.isActive ? 'Deactivate' : 'Activate'}
            </button>
            <button onclick="openEditPromotionModal(${p.id})" class="px-2 py-1 rounded bg-blue-500/20 hover:bg-blue-500/30 text-blue-300 text-[11px]" title="Edit Promotion">
              <i class="fa-solid fa-pen-to-square"></i>
            </button>
            <button onclick="deletePromotion(${p.id})" class="px-2 py-1 rounded bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 text-[11px]" title="Delete Promotion">
              <i class="fa-solid fa-trash-can"></i>
            </button>
          </td>
        </tr>
      `;
    }).join('');
  } catch (err) {
    console.error('Failed to load promotions:', err);
    if (tbody) {
      tbody.innerHTML = `<tr><td colspan="6" class="text-center py-4 text-rose-400">Error loading promotions: ${escapeHtml(err.message)}</td></tr>`;
    }
  }
}

function openCreatePromotionModal() {
  document.getElementById('promotionModalTitle').textContent = 'Create New Promotion';
  document.getElementById('promoId').value = '';
  document.getElementById('promoName').value = '';
  document.getElementById('promoDiscountPct').value = '';
  document.getElementById('promoIsActive').checked = true;
  document.getElementById('promoDescription').value = '';
  document.getElementById('promotionFormError').classList.add('hidden');

  // Format local current time and +7 days for datetime-local (YYYY-MM-DDTHH:mm)
  const now = new Date();
  const pad = n => String(n).padStart(2, '0');
  const formatLocalDt = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;

  document.getElementById('promoStartDateTime').value = formatLocalDt(now);
  const end = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  document.getElementById('promoEndDateTime').value = formatLocalDt(end);

  document.getElementById('promotionModal').classList.remove('hidden');
}

function openEditPromotionModal(id) {
  const promo = cachedPromotionsList.find(p => p.id === id);
  if (!promo) {
    showToast('Promotion details not found', 'error');
    return;
  }

  document.getElementById('promotionModalTitle').textContent = 'Edit Promotion';
  document.getElementById('promoId').value = promo.id;
  document.getElementById('promoName').value = promo.name || '';
  document.getElementById('promoDiscountPct').value = promo.discountPercentage || '';
  document.getElementById('promoIsActive').checked = Boolean(promo.isActive);
  document.getElementById('promoDescription').value = promo.description || '';
  document.getElementById('promotionFormError').classList.add('hidden');

  if (promo.startDateTime) {
    document.getElementById('promoStartDateTime').value = promo.startDateTime.substring(0, 16);
  }
  if (promo.endDateTime) {
    document.getElementById('promoEndDateTime').value = promo.endDateTime.substring(0, 16);
  }

  document.getElementById('promotionModal').classList.remove('hidden');
}

function closePromotionModal() {
  document.getElementById('promotionModal').classList.add('hidden');
}

async function savePromotion(event) {
  event.preventDefault();
  const errEl = document.getElementById('promotionFormError');
  errEl.classList.add('hidden');

  const id = document.getElementById('promoId').value;
  const name = document.getElementById('promoName').value.trim();
  const discountPct = parseFloat(document.getElementById('promoDiscountPct').value);
  const startDt = document.getElementById('promoStartDateTime').value;
  const endDt = document.getElementById('promoEndDateTime').value;
  const isActive = document.getElementById('promoIsActive').checked;
  const description = document.getElementById('promoDescription').value.trim();

  if (!name) {
    errEl.textContent = 'Promotion name is required.';
    errEl.classList.remove('hidden');
    return;
  }
  if (isNaN(discountPct) || discountPct <= 0 || discountPct > 100) {
    errEl.textContent = 'Discount percentage must be greater than 0 and at most 100.';
    errEl.classList.remove('hidden');
    return;
  }
  if (!startDt || !endDt) {
    errEl.textContent = 'Both start date/time and end date/time are required.';
    errEl.classList.remove('hidden');
    return;
  }
  if (new Date(endDt) <= new Date(startDt)) {
    errEl.textContent = 'End date/time must be strictly after start date/time.';
    errEl.classList.remove('hidden');
    return;
  }

  const payload = {
    name: name,
    discountPercentage: discountPct,
    startDateTime: startDt,
    endDateTime: endDt,
    isActive: isActive,
    description: description
  };

  const btn = document.getElementById('btnSavePromotion');
  if (btn) btn.disabled = true;

  try {
    if (id) {
      await apiRequest(`/promotions/${id}`, {
        method: 'PUT',
        body: JSON.stringify(payload)
      });
      showToast('Promotion updated successfully', 'success');
    } else {
      await apiRequest('/promotions', {
        method: 'POST',
        body: JSON.stringify(payload)
      });
      showToast('Promotion created successfully', 'success');
    }
    closePromotionModal();
    loadPromotions();
  } catch (err) {
    errEl.textContent = err.message || 'Failed to save promotion';
    errEl.classList.remove('hidden');
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function togglePromotionActive(id) {
  try {
    const res = await apiRequest(`/promotions/${id}/toggle-active`, { method: 'PATCH' });
    showToast(`Promotion '${res.name}' is now ${res.isActive ? 'ACTIVE' : 'INACTIVE'}`, 'success');
    loadPromotions();
  } catch (err) {
    showToast('Failed to toggle promotion: ' + err.message, 'error');
  }
}

async function deletePromotion(id) {
  if (!confirm('Are you sure you want to delete this promotion? This action is logged to the audit trail.')) return;
  try {
    await apiRequest(`/promotions/${id}`, { method: 'DELETE' });
    showToast('Promotion deleted successfully', 'success');
    loadPromotions();
  } catch (err) {
    showToast('Failed to delete promotion: ' + err.message, 'error');
  }
}

async function cancelBill(id) {
  if (!confirm('Are you sure you want to cancel this bill?')) return;
  try {
    await apiRequest(`/bills/${id}/cancel`, { method: 'POST' });
    showToast('Bill cancelled and logged to audit trail', 'success');
    fetchBillsByCurrentFilter();
  } catch (err) {
    showToast('Failed to cancel bill: ' + err.message, 'error');
  }
}

let editBillState = {
  billId: null,
  originalNet: 0,
  items: []
};

async function openEditBillModal(id) {
  try {
    const bill = await apiRequest(`/bills/${id}`);
    if (!menuItems || menuItems.length === 0) {
      try {
        menuItems = await apiRequest('/menu-items');
      } catch (e) {
        console.warn('Failed to load menu items:', e);
      }
    }

    editBillState.billId = bill.id;
    editBillState.originalNet = bill.netAmount || 0;
    editBillState.items = (bill.items || []).map(i => ({
      menuItemId: i.menuItemId,
      itemName: i.itemName,
      quantity: i.quantity || 1,
      price: i.price || 0
    }));

    document.getElementById('editBillId').value = bill.id;
    document.getElementById('editBillTable').value = bill.tableNumber || '';
    document.getElementById('editBillCustomer').value = bill.customerName || '';
    document.getElementById('editBillPaymentMode').value = bill.paymentMode || 'CASH';
    document.getElementById('editBillDiscount').value = bill.discountPercent !== undefined && bill.discountPercent !== null ? bill.discountPercent : 0;
    document.getElementById('editBillTax').value = bill.taxPercent !== undefined && bill.taxPercent !== null ? bill.taxPercent : 0;
    document.getElementById('editBillNotes').value = bill.notes || '';
    document.getElementById('editBillSubtitle').textContent = `Editing Bill #${bill.billNumber} (Original Net: ₹${bill.netAmount.toFixed(2)})`;

    // Populate Dish selector
    const addSelect = document.getElementById('editBillAddSelect');
    if (addSelect) {
      addSelect.innerHTML = '<option value="">-- Select dish to add --</option>' +
        (menuItems || [])
          .filter(m => m.isAvailable !== false && m.active !== false)
          .sort((a, b) => a.name.localeCompare(b.name))
          .map(m => `<option value="${m.id}" data-name="${escapeHtml(m.name)}" data-price="${m.price}">${escapeHtml(m.name)} (₹${m.price.toFixed(2)})</option>`)
          .join('');
    }

    renderEditBillItems();
    recalculateEditBillTotals();

    document.getElementById('editBillModal').classList.remove('hidden');
  } catch (err) {
    showToast('Failed to load bill for editing: ' + err.message, 'error');
  }
}

function renderEditBillItems() {
  const container = document.getElementById('editBillItemsList');
  const countEl = document.getElementById('editBillItemsCount');
  if (!container) return;

  if (countEl) {
    countEl.textContent = `${editBillState.items.length} ${editBillState.items.length === 1 ? 'item' : 'items'}`;
  }

  if (editBillState.items.length === 0) {
    container.innerHTML = `
      <div class="text-center py-6 text-gray-500 bg-gray-900/40 rounded-lg border border-dashed border-gray-800">
        <i class="fa-solid fa-utensils text-xl mb-1 block opacity-40"></i>
        <span>No dishes in this bill. Use the dropdown above to add dishes.</span>
      </div>`;
    return;
  }

  container.innerHTML = editBillState.items.map((item, idx) => {
    const lineTotal = (item.price * item.quantity).toFixed(2);
    return `
      <div class="flex items-center justify-between gap-2 p-2 rounded-lg bg-gray-900/90 border border-gray-800 hover:border-gray-700 transition">
        <div class="flex-1 min-w-0">
          <div class="font-semibold text-gray-200 truncate text-xs">${escapeHtml(item.itemName)}</div>
          <div class="text-[11px] text-gray-400 font-mono">₹${item.price.toFixed(2)} each</div>
        </div>

        <!-- Quantity Stepper -->
        <div class="flex items-center gap-1 shrink-0">
          <button type="button" onclick="changeEditBillItemQty(${idx}, -1)" class="w-6 h-6 rounded bg-gray-800 hover:bg-gray-700 text-gray-300 flex items-center justify-center font-bold text-xs transition" title="Decrease">
            <i class="fa-solid fa-minus text-[10px]"></i>
          </button>
          <input type="number" min="1" max="99" value="${item.quantity}" onchange="setEditBillItemQty(${idx}, this.value)" class="w-10 text-center font-mono font-bold bg-gray-950 border border-gray-700 rounded py-0.5 text-xs text-white" />
          <button type="button" onclick="changeEditBillItemQty(${idx}, 1)" class="w-6 h-6 rounded bg-gray-800 hover:bg-gray-700 text-gray-300 flex items-center justify-center font-bold text-xs transition" title="Increase">
            <i class="fa-solid fa-plus text-[10px]"></i>
          </button>
        </div>

        <!-- Subtotal -->
        <div class="w-20 text-right font-mono font-bold text-amber-400 text-xs shrink-0">
          ₹${lineTotal}
        </div>

        <!-- Remove Button -->
        <button type="button" onclick="removeEditBillItem(${idx})" class="text-rose-400 hover:text-rose-300 p-1.5 rounded hover:bg-rose-500/10 transition shrink-0" title="Remove Item">
          <i class="fa-solid fa-trash-can text-xs"></i>
        </button>
      </div>
    `;
  }).join('');
}

function changeEditBillItemQty(idx, delta) {
  if (!editBillState.items[idx]) return;
  const newQty = editBillState.items[idx].quantity + delta;
  if (newQty <= 0) {
    removeEditBillItem(idx);
    return;
  }
  editBillState.items[idx].quantity = newQty;
  renderEditBillItems();
  recalculateEditBillTotals();
}

function setEditBillItemQty(idx, val) {
  if (!editBillState.items[idx]) return;
  const parsed = parseInt(val, 10);
  if (isNaN(parsed) || parsed <= 0) {
    removeEditBillItem(idx);
    return;
  }
  editBillState.items[idx].quantity = parsed;
  renderEditBillItems();
  recalculateEditBillTotals();
}

function removeEditBillItem(idx) {
  if (editBillState.items.length <= 1) {
    if (!confirm('This is the only item in the bill. Removing it will leave the bill empty. Are you sure?')) return;
  }
  editBillState.items.splice(idx, 1);
  renderEditBillItems();
  recalculateEditBillTotals();
}

function addDishToEditBill() {
  const sel = document.getElementById('editBillAddSelect');
  if (!sel || !sel.value) {
    showToast('Please select a dish to add', 'warning');
    return;
  }
  const opt = sel.options[sel.selectedIndex];
  const menuItemId = parseInt(sel.value, 10);
  const itemName = opt.getAttribute('data-name');
  const price = parseFloat(opt.getAttribute('data-price')) || 0;

  // Check if item already in list
  const existing = editBillState.items.find(i => i.menuItemId === menuItemId || i.itemName.toLowerCase() === itemName.toLowerCase());
  if (existing) {
    existing.quantity += 1;
    showToast(`Increased quantity for ${itemName}`, 'info');
  } else {
    editBillState.items.push({
      menuItemId: menuItemId,
      itemName: itemName,
      quantity: 1,
      price: price
    });
    showToast(`Added ${itemName} to bill`, 'success');
  }

  sel.value = '';
  renderEditBillItems();
  recalculateEditBillTotals();
}

function recalculateEditBillTotals() {
  const subtotal = editBillState.items.reduce((acc, it) => acc + (it.price * it.quantity), 0);
  const discPct = parseFloat(document.getElementById('editBillDiscount').value) || 0;
  const taxPct = parseFloat(document.getElementById('editBillTax').value) || 0;

  const discAmt = (subtotal * discPct) / 100;
  const taxable = Math.max(0, subtotal - discAmt);
  const taxAmt = (taxable * taxPct) / 100;
  const newNet = taxable + taxAmt;

  const subEl = document.getElementById('editBillCalcSubtotal');
  if (subEl) subEl.textContent = `₹${subtotal.toFixed(2)}`;
  const netEl = document.getElementById('editBillCalcNet');
  if (netEl) netEl.textContent = `₹${newNet.toFixed(2)}`;

  const diffBadge = document.getElementById('editBillDiffBadge');
  if (diffBadge) {
    const diff = Math.round((newNet - editBillState.originalNet) * 100) / 100;
    if (Math.abs(diff) < 0.01) {
      diffBadge.textContent = '';
      diffBadge.className = '';
    } else if (diff > 0) {
      diffBadge.textContent = `(+₹${diff.toFixed(2)})`;
      diffBadge.className = 'text-[11px] font-mono text-emerald-400 font-bold bg-emerald-500/10 px-1.5 py-0.5 rounded border border-emerald-500/20';
    } else {
      diffBadge.textContent = `(Diff: -₹${Math.abs(diff).toFixed(2)})`;
      diffBadge.className = 'text-[11px] font-mono text-rose-400 font-bold bg-rose-500/10 px-1.5 py-0.5 rounded border border-rose-500/20';
    }
  }
}

async function deleteBill(id) {
  if (!confirm('Are you sure you want to permanently delete this bill? This will be permanently logged in the audit trail.')) return;
  try {
    await apiRequest(`/bills/${id}`, { method: 'DELETE' });
    showToast('Bill deleted and recorded in audit log', 'success');
    fetchBillsByCurrentFilter();
  } catch (err) {
    showToast('Failed to delete bill: ' + err.message, 'error');
  }
}

// ============================================================
// TAB 3: MENU & PRICING
// ============================================================
async function loadMenuData() {
  try {
    [categories, menuItems] = await Promise.all([
      apiRequest('/categories'),
      apiRequest('/menu-items')
    ]);
    renderMenuTable();
    renderDishesGrid();
    loadPublicMenuStatus();
  } catch (err) {
    showToast('Failed to load menu: ' + err.message, 'error');
  }
}

let isPublicMenuEnabled = true;

async function loadPublicMenuStatus() {
  try {
    const res = await apiRequest('/settings/public-menu');
    isPublicMenuEnabled = (res && res.enabled === true);
    updatePublicMenuUI();
  } catch (err) {
    console.warn('Failed to load public menu status:', err);
  }
}

function updatePublicMenuUI() {
  const badge = document.getElementById('publicMenuStatusBadge');
  const btn = document.getElementById('btnTogglePublicMenu');
  if (!badge || !btn) return;

  if (isPublicMenuEnabled) {
    badge.className = 'inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30';
    badge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse mr-1"></span> Live & Online';

    btn.className = 'px-3.5 py-1.5 text-xs rounded-lg font-bold transition flex items-center gap-1.5 bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 border border-rose-500/30';
    btn.innerHTML = '<i class="fa-solid fa-power-off"></i> Disable Menu';
  } else {
    badge.className = 'inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold bg-rose-500/15 text-rose-400 border border-rose-500/30';
    badge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-rose-400 mr-1"></span> Disabled / Offline';

    btn.className = 'px-3.5 py-1.5 text-xs rounded-lg font-bold transition flex items-center gap-1.5 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-300 border border-emerald-500/30';
    btn.innerHTML = '<i class="fa-solid fa-circle-check"></i> Enable Menu';
  }
}

async function togglePublicMenuStatus() {
  const targetState = !isPublicMenuEnabled;
  const actionText = targetState ? 'ENABLE' : 'DISABLE';
  if (!confirm(`Are you sure you want to ${actionText} the public customer menu?`)) {
    return;
  }

  try {
    const res = await apiRequest('/settings/public-menu', {
      method: 'PUT',
      body: JSON.stringify({ enabled: targetState })
    });
    isPublicMenuEnabled = (res && res.enabled === true);
    updatePublicMenuUI();
    showToast(res.message || `Public menu ${targetState ? 'enabled' : 'disabled'}`, 'success');
  } catch (err) {
    showToast('Failed to update public menu: ' + err.message, 'error');
  }
}

function copyPublicMenuLink() {
  const url = window.location.origin + '/menu.html';
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).then(() => {
      showToast('Public menu link copied to clipboard: ' + url, 'success');
    }).catch(() => {
      prompt('Copy public menu URL:', url);
    });
  } else {
    prompt('Copy public menu URL:', url);
  }
}

let currentMenuSubTab = 'all'; // 'all' | 'available' | 'unavailable'
let menuSearchQuery = '';

function switchMenuSubTab(subTab) {
  currentMenuSubTab = subTab;

  const allBtn = document.getElementById('menuSubTab-all');
  const availBtn = document.getElementById('menuSubTab-available');
  const unavailBtn = document.getElementById('menuSubTab-unavailable');

  const baseActive = 'px-3 py-1.5 rounded-md font-bold transition flex items-center gap-1.5 shadow-md ';
  const baseInactive = 'px-3 py-1.5 rounded-md font-medium text-gray-400 hover:text-white transition flex items-center gap-1.5 bg-transparent';

  if (allBtn) {
    allBtn.className = (subTab === 'all')
      ? baseActive + 'bg-amber-500 text-gray-950'
      : baseInactive;
  }
  if (availBtn) {
    availBtn.className = (subTab === 'available')
      ? baseActive + 'bg-emerald-500 text-gray-950'
      : baseInactive;
  }
  if (unavailBtn) {
    unavailBtn.className = (subTab === 'unavailable')
      ? baseActive + 'bg-rose-500 text-white'
      : baseInactive;
  }

  renderMenuTable();
}

function filterMenuTable() {
  const input = document.getElementById('menuSearchInput');
  const clearBtn = document.getElementById('btnClearMenuSearch');
  menuSearchQuery = input ? input.value.trim().toLowerCase() : '';

  if (clearBtn) {
    if (menuSearchQuery.length > 0) {
      clearBtn.classList.remove('hidden');
    } else {
      clearBtn.classList.add('hidden');
    }
  }

  renderMenuTable();
}

function clearMenuSearch() {
  const input = document.getElementById('menuSearchInput');
  const clearBtn = document.getElementById('btnClearMenuSearch');
  if (input) input.value = '';
  if (clearBtn) clearBtn.classList.add('hidden');
  menuSearchQuery = '';
  renderMenuTable();
}

async function makeAllUnavailableDishesAvailable() {
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  if (!isManagerOrAdmin) {
    showToast('Permission denied: Only managers and admins can change item availability.', 'error');
    return;
  }
  const unavailItems = menuItems.filter(i => (i.isAvailable === false) || (i.active === false));
  if (unavailItems.length === 0) {
    showToast('No unavailable items to restore.', 'info');
    return;
  }
  if (!confirm(`Are you sure you want to make all ${unavailItems.length} unavailable item(s) available again?`)) {
    return;
  }
  try {
    for (const item of unavailItems) {
      await apiRequest(`/menu-items/${item.id}/toggle-availability`, { method: 'PATCH' });
    }
    showToast(`All ${unavailItems.length} dish(es) are now marked Available!`, 'success');
    await loadMenuData();
  } catch (err) {
    showToast('Failed to update some dishes: ' + err.message, 'error');
    await loadMenuData();
  }
}

function renderMenuTable() {
  const tbody = document.getElementById('menuTableBody');
  if (!tbody) return;

  // 1. Calculate badge counts across all dishes
  const totalCount = menuItems.length;
  const availCount = menuItems.filter(item => (item.isAvailable !== false) && (item.active !== false)).length;
  const unavailCount = totalCount - availCount;

  const cAll = document.getElementById('menuCountAll');
  const cAvail = document.getElementById('menuCountAvail');
  const cUnavail = document.getElementById('menuCountUnavail');
  if (cAll) cAll.textContent = totalCount;
  if (cAvail) cAvail.textContent = availCount;
  if (cUnavail) cUnavail.textContent = unavailCount;

  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');

  // 2. Control "Make All Available" button visibility in Unavailable tab
  const btnMakeAll = document.getElementById('btnMakeAllAvailable');
  if (btnMakeAll) {
    if (currentMenuSubTab === 'unavailable' && unavailCount > 0 && isManagerOrAdmin) {
      btnMakeAll.classList.remove('hidden');
    } else {
      btnMakeAll.classList.add('hidden');
    }
  }

  // 3. Filter items by selected sub-menu tab
  let filtered = menuItems;
  if (currentMenuSubTab === 'available') {
    filtered = filtered.filter(item => (item.isAvailable !== false) && (item.active !== false));
  } else if (currentMenuSubTab === 'unavailable') {
    filtered = filtered.filter(item => (item.isAvailable === false) || (item.active === false));
  }

  // 4. Filter by search input query
  if (menuSearchQuery) {
    filtered = filtered.filter(item => {
      const name = (item.name || '').toLowerCase();
      const cat = (item.categoryName || '').toLowerCase();
      const desc = (item.description || '').toLowerCase();
      const diet = item.isVeg ? 'veg' : 'non-veg nonveg';
      return name.includes(menuSearchQuery) || cat.includes(menuSearchQuery) || desc.includes(menuSearchQuery) || diet.includes(menuSearchQuery);
    });
  }

  // 5. Friendly empty state displays
  if (filtered.length === 0) {
    if (menuItems.length === 0) {
      tbody.innerHTML = `<tr><td colspan="6" class="text-center py-8 text-gray-500">No dishes in menu</td></tr>`;
      return;
    }
    if (currentMenuSubTab === 'unavailable' && !menuSearchQuery) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" class="text-center py-12">
            <div class="flex flex-col items-center justify-center text-gray-400">
              <div class="w-12 h-12 rounded-full bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400 text-xl mb-3">
                <i class="fa-solid fa-circle-check"></i>
              </div>
              <p class="text-sm font-bold text-white">All Dishes Are Currently Available</p>
              <p class="text-xs text-gray-500 mt-1">There are no out-of-stock items. To mark a dish unavailable, switch to "Available" or "All Dishes" and use the toggle switch.</p>
            </div>
          </td>
        </tr>
      `;
      return;
    }
    if (currentMenuSubTab === 'available' && !menuSearchQuery) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" class="text-center py-12">
            <div class="flex flex-col items-center justify-center text-gray-400">
              <div class="w-12 h-12 rounded-full bg-rose-500/10 border border-rose-500/20 flex items-center justify-center text-rose-400 text-xl mb-3">
                <i class="fa-solid fa-ban"></i>
              </div>
              <p class="text-sm font-bold text-white">No Dishes Available</p>
              <p class="text-xs text-gray-500 mt-1">All items in the menu are currently marked unavailable.</p>
            </div>
          </td>
        </tr>
      `;
      return;
    }
    if (menuSearchQuery) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" class="text-center py-12 text-gray-400">
            <div class="flex flex-col items-center justify-center">
              <i class="fa-solid fa-magnifying-glass text-2xl text-gray-600 mb-2"></i>
              <p class="text-xs">No dishes match "<strong>${escapeHtml(menuSearchQuery)}</strong>"</p>
              <button type="button" onclick="clearMenuSearch()" class="mt-2 text-xs text-amber-400 hover:underline">Clear search filter</button>
            </div>
          </td>
        </tr>
      `;
      return;
    }
    tbody.innerHTML = `<tr><td colspan="6" class="text-center py-8 text-gray-500">No dishes found</td></tr>`;
    return;
  }

  // 6. Render table rows
  tbody.innerHTML = filtered.map(item => {
    const isAvail = (item.isAvailable !== false) && (item.active !== false);

    let toggleHtml;
    if (isManagerOrAdmin) {
      if (currentMenuSubTab === 'unavailable') {
        // Dedicated, prominent Make Available action for managers in the Unavailable sub-menu
        toggleHtml = `
          <div class="flex items-center gap-2">
            <button type="button"
              onclick="toggleDishAvailability(${item.id})"
              class="px-3 py-1.5 rounded-lg text-xs font-bold bg-emerald-500 hover:bg-emerald-400 text-gray-950 flex items-center gap-1.5 shadow-sm shadow-emerald-500/20 transition cursor-pointer"
              title="Click to make this item available again">
              <i class="fa-solid fa-circle-check"></i>
              <span>Make Available</span>
            </button>
          </div>
        `;
      } else {
        // Standard interactive switch toggle
        toggleHtml = `
          <div class="flex items-center gap-2.5">
            <button type="button"
              onclick="toggleDishAvailability(${item.id})"
              class="relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-amber-500/50 ${isAvail ? 'bg-emerald-500' : 'bg-gray-700'}"
              role="switch"
              aria-checked="${isAvail}"
              title="Click to toggle availability (${isAvail ? 'Currently Available' : 'Currently Unavailable'})">
              <span class="pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow-md ring-0 transition duration-200 ease-in-out ${isAvail ? 'translate-x-5' : 'translate-x-0'}"></span>
            </button>
            <span class="text-xs font-bold ${isAvail ? 'text-emerald-400' : 'text-gray-500'}">
              ${isAvail ? 'Available' : 'Unavailable'}
            </span>
          </div>
        `;
      }
    } else {
      toggleHtml = `
        <div class="flex items-center gap-2.5" title="Only Managers can toggle dish availability">
          <div class="relative inline-flex h-6 w-11 flex-shrink-0 rounded-full border-2 border-transparent opacity-50 cursor-not-allowed ${isAvail ? 'bg-emerald-500' : 'bg-gray-700'}">
            <span class="inline-block h-5 w-5 transform rounded-full bg-white shadow-md ${isAvail ? 'translate-x-5' : 'translate-x-0'}"></span>
          </div>
          <span class="text-xs font-bold ${isAvail ? 'text-emerald-400' : 'text-gray-500'}">
            ${isAvail ? 'Available' : 'Unavailable'}
          </span>
        </div>
      `;
    }

    return `
      <tr class="hover:bg-gray-800/40 transition">
        <td class="p-3 font-semibold text-white">
          <div class="flex items-center gap-2">
            <span>${escapeHtml(item.name)}</span>
            ${!isAvail ? '<span class="px-1.5 py-0.5 rounded text-[9px] font-black bg-rose-500/20 text-rose-400 border border-rose-500/30">OUT OF STOCK</span>' : ''}
          </div>
        </td>
        <td class="p-3 text-gray-400">${escapeHtml(item.categoryName || '-')}</td>
        <td class="p-3">
          <span class="px-2 py-0.5 rounded text-[10px] font-bold ${item.isVeg ? 'bg-emerald-500/20 text-emerald-400' : 'bg-rose-500/20 text-rose-400'}">
            ${item.isVeg ? 'VEG' : 'NON-VEG'}
          </span>
        </td>
        <td class="p-3 font-bold text-amber-400">₹${item.price.toFixed(2)}</td>
        <td class="p-3">
          ${toggleHtml}
        </td>
        <td class="p-3 text-right space-x-2">
          ${isManagerOrAdmin ? `
            <button onclick="editDish(${item.id})" class="text-gray-400 hover:text-amber-400" title="Edit">
              <i class="fa-regular fa-pen-to-square"></i>
            </button>
            <button onclick="deleteDish(${item.id})" class="text-gray-400 hover:text-rose-400" title="Delete">
              <i class="fa-regular fa-trash-can"></i>
            </button>
          ` : `
            <span class="text-[10px] text-gray-600 italic">View Only</span>
          `}
        </td>
      </tr>
    `;
  }).join('');
}

function openAddDishModal() {
  document.getElementById('dishModalTitle').textContent = 'Add New Dish';
  document.getElementById('dishId').value = '';
  document.getElementById('dishName').value = '';
  document.getElementById('dishPrice').value = '';
  document.getElementById('dishDescription').value = '';
  document.getElementById('dishIsVeg').checked = true;
  document.getElementById('dishIsAvailable').checked = true;

  const catSelect = document.getElementById('dishCategory');
  catSelect.innerHTML = categories.map(c => `<option value="${escapeHtml(c.id)}">${escapeHtml(c.name)}</option>`).join('');

  document.getElementById('dishModal').classList.remove('hidden');
}

function editDish(id) {
  const item = menuItems.find(m => m.id === id);
  if (!item) return;

  document.getElementById('dishModalTitle').textContent = 'Edit Dish & Price';
  document.getElementById('dishId').value = item.id;
  document.getElementById('dishName').value = item.name;
  document.getElementById('dishPrice').value = item.price;
  document.getElementById('dishDescription').value = item.description || '';
  document.getElementById('dishIsVeg').checked = item.isVeg;
  document.getElementById('dishIsAvailable').checked = item.isAvailable;

  const catSelect = document.getElementById('dishCategory');
  catSelect.innerHTML = categories.map(c => `<option value="${escapeHtml(c.id)}" ${c.id === item.categoryId ? 'selected' : ''}>${escapeHtml(c.name)}</option>`).join('');

  document.getElementById('dishModal').classList.remove('hidden');
}

async function saveDish(e) {
  e.preventDefault();
  const id = document.getElementById('dishId').value;
  const payload = {
    name: document.getElementById('dishName').value.trim(),
    categoryId: parseInt(document.getElementById('dishCategory').value),
    price: parseFloat(document.getElementById('dishPrice').value),
    description: document.getElementById('dishDescription').value.trim(),
    isVeg: document.getElementById('dishIsVeg').checked,
    isAvailable: document.getElementById('dishIsAvailable').checked,
    active: true
  };

  try {
    if (id) {
      await apiRequest(`/menu-items/${id}`, { method: 'PUT', body: JSON.stringify(payload) });
      showToast('Dish updated successfully', 'success');
    } else {
      await apiRequest('/menu-items', { method: 'POST', body: JSON.stringify(payload) });
      showToast('New dish added to menu', 'success');
    }
    closeModal('dishModal');
    loadMenuData();
  } catch (err) {
    showToast('Error saving dish: ' + err.message, 'error');
  }
}

async function toggleDishAvailability(id) {
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  if (!isManagerOrAdmin) {
    showToast('Permission denied: Only managers and admins can toggle item availability.', 'error');
    return;
  }
  try {
    const updated = await apiRequest(`/menu-items/${id}/toggle-availability`, { method: 'PATCH' });
    const statusText = updated.isAvailable ? 'Available' : 'Unavailable (Out of Stock)';
    showToast(`"${updated.name}" is now marked ${statusText}`, 'success');
    await loadMenuData();
  } catch (err) {
    showToast('Failed to toggle availability: ' + err.message, 'error');
  }
}

async function deleteDish(id) {
  if (!confirm('Are you sure you want to remove this dish from the menu?')) return;
  try {
    await apiRequest(`/menu-items/${id}`, { method: 'DELETE' });
    showToast('Dish removed', 'success');
    loadMenuData();
  } catch (err) {
    showToast('Failed to delete dish: ' + err.message, 'error');
  }
}

// Icons offered in the category editor (Font Awesome 6 free). Existing categories with another icon keep it until changed.
const CATEGORY_ICONS = [
  ['fa-utensils', 'Food'], ['fa-burger', 'Burger'], ['fa-pizza-slice', 'Pizza'], ['fa-hotdog', 'Hot dog'],
  ['fa-bowl-food', 'Bowl'], ['fa-bowl-rice', 'Rice'], ['fa-drumstick-bite', 'Chicken'], ['fa-fish', 'Fish'],
  ['fa-egg', 'Egg'], ['fa-bread-slice', 'Bread'], ['fa-cheese', 'Cheese'], ['fa-carrot', 'Veg'],
  ['fa-leaf', 'Salad'], ['fa-pepper-hot', 'Spicy'], ['fa-mug-hot', 'Hot drinks'], ['fa-mug-saucer', 'Tea / Coffee'],
  ['fa-glass-water', 'Water'], ['fa-martini-glass-citrus', 'Juice'], ['fa-wine-glass', 'Drinks'], ['fa-blender', 'Shakes'],
  ['fa-ice-cream', 'Ice cream'], ['fa-cake-candles', 'Cake'], ['fa-cookie-bite', 'Snacks'], ['fa-lemon', 'Fruit']
];
let categoryFormFromList = false;

function selectCategoryIcon(cls) {
  const hidden = document.getElementById('catIcon');
  if (hidden) hidden.value = cls;
  document.querySelectorAll('#catIconPicker button').forEach(btn => {
    const on = btn.dataset.icon === cls;
    btn.setAttribute('aria-pressed', String(on));
    btn.className = 'h-9 rounded-lg border text-sm transition flex items-center justify-center ' +
      (on ? 'bg-cyan-500 text-gray-950 border-cyan-400 shadow-md' : 'glass-card text-gray-300 border-gray-700 hover:text-white hover:border-cyan-500/50');
  });
}

function renderCategoryIconPicker(selected) {
  const picker = document.getElementById('catIconPicker');
  if (!picker) return;
  picker.innerHTML = CATEGORY_ICONS.map(([cls, label]) =>
    `<button type="button" data-icon="${cls}" title="${label}" aria-label="${label}" onclick="selectCategoryIcon('${cls}')"><i class="fa-solid ${cls}"></i></button>`
  ).join('');
  selectCategoryIcon(selected);
}

/** Show the form for a new category (cat = null) or for editing an existing one. */
function showCategoryForm(cat, fromList) {
  categoryFormFromList = Boolean(fromList);
  document.getElementById('categoryListView').classList.add('hidden');
  document.getElementById('categoryForm').classList.remove('hidden');
  document.getElementById('categoryModalTitle').textContent = cat ? `Edit Category: ${cat.name}` : 'Add Menu Category';
  document.getElementById('catId').value = cat ? cat.id : '';
  document.getElementById('catName').value = cat ? cat.name : '';
  document.getElementById('catDescription').value = cat ? (cat.description || '') : '';
  document.getElementById('catSortOrder').value = cat && cat.sortOrder != null ? cat.sortOrder : categories.length + 1;
  document.getElementById('btnSaveCategory').textContent = cat ? 'Save Changes' : 'Save Category';
  document.getElementById('btnCategoryBack').classList.toggle('hidden', !fromList);
  renderCategoryIconPicker(cat && cat.icon ? cat.icon : 'fa-utensils');
  document.getElementById('categoryModal').classList.remove('hidden');
  document.getElementById('catName').focus();
}

function openAddCategoryModal() {
  showCategoryForm(null, false);
}

function editCategory(id) {
  const cat = categories.find(c => c.id === id);
  if (cat) showCategoryForm(cat, true);
}

/** "Edit Categories": list every active category so one can be picked for editing. */
function openCategoryManager() {
  const dishCount = {};
  (menuItems || []).forEach(m => { dishCount[m.categoryId] = (dishCount[m.categoryId] || 0) + 1; });
  const sorted = [...categories].sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0) || a.name.localeCompare(b.name));
  document.getElementById('categoryManageList').innerHTML = sorted.length === 0
    ? '<div class="text-center text-gray-500 py-6">No categories yet.</div>'
    : sorted.map(c => {
      const n = dishCount[c.id] || 0;
      const icon = /^fa-[a-z0-9-]+$/.test(c.icon || '') ? c.icon : 'fa-utensils';
      return `<div class="flex items-center gap-3 p-2.5 rounded-lg bg-gray-900/60 border border-gray-800">
        <span class="w-8 h-8 rounded-lg bg-cyan-500/10 text-cyan-300 flex items-center justify-center shrink-0"><i class="fa-solid ${icon}"></i></span>
        <div class="min-w-0 flex-1">
          <div class="font-semibold text-white truncate">${escapeHtml(c.name)}</div>
          <div class="text-[10px] text-gray-500">${n} dish${n === 1 ? '' : 'es'} &middot; position ${Number(c.sortOrder) || 0}${c.description ? ' &middot; ' + escapeHtml(c.description) : ''}</div>
        </div>
        <button type="button" onclick="editCategory(${Number(c.id)})" title="Edit ${escapeHtml(c.name)}" aria-label="Edit ${escapeHtml(c.name)}"
          class="px-2.5 py-1.5 rounded-lg text-amber-400 hover:text-amber-300 hover:bg-amber-500/10 transition shrink-0">
          <i class="fa-regular fa-pen-to-square"></i>
        </button>
      </div>`;
    }).join('');
  categoryFormFromList = false;
  document.getElementById('categoryModalTitle').textContent = 'Edit Categories';
  document.getElementById('categoryForm').classList.add('hidden');
  document.getElementById('categoryListView').classList.remove('hidden');
  document.getElementById('categoryModal').classList.remove('hidden');
}

async function saveCategory(e) {
  e.preventDefault();
  const id = document.getElementById('catId').value;
  const existing = id ? categories.find(c => String(c.id) === String(id)) : null;
  const sortRaw = document.getElementById('catSortOrder').value;
  const payload = {
    name: document.getElementById('catName').value.trim(),
    description: document.getElementById('catDescription').value.trim(),
    icon: document.getElementById('catIcon').value || 'fa-utensils',
    sortOrder: sortRaw === '' ? categories.length + 1 : parseInt(sortRaw, 10),
    active: existing ? existing.active !== false : true
  };
  const saveBtn = document.getElementById('btnSaveCategory');
  if (saveBtn) saveBtn.disabled = true;
  try {
    if (id) {
      await apiRequest(`/categories/${id}`, { method: 'PUT', body: JSON.stringify(payload) });
      showToast(`Category "${payload.name}" updated`, 'success');
    } else {
      await apiRequest('/categories', { method: 'POST', body: JSON.stringify(payload) });
      showToast('Category created successfully', 'success');
    }
    await loadMenuData();
    if (id && categoryFormFromList) {
      openCategoryManager();
    } else {
      closeModal('categoryModal');
    }
  } catch (err) {
    showToast(`Failed to ${id ? 'update' : 'create'} category: ` + err.message, 'error');
  } finally {
    if (saveBtn) saveBtn.disabled = false;
  }
}

// ============================================================
// TAB 4: INVENTORY MANAGEMENT
// ============================================================
async function loadInventoryData() {
  try {
    const items = await apiRequest('/inventory');
    renderInventoryTable(items);
  } catch (err) {
    showToast('Failed to load inventory: ' + err.message, 'error');
  }
}

let inventoryItemsList = [];
let currentInventorySubTab = 'stock';
let currentInventoryCategoryFilter = 'Stock';
let inventorySearchTerm = '';
let inventoryLowOnly = false;
let lowStockListOpen = false;

function switchInventoryCategory(cat) {
  currentInventoryCategoryFilter = cat;
  const categories = ['Stock', 'Consumable', 'Small equipment', 'Fixed asset', 'ALL'];
  const tabIdMap = {
    'Stock': 'inv-cat-tab-Stock',
    'Consumable': 'inv-cat-tab-Consumable',
    'Small equipment': 'inv-cat-tab-SmallEquipment',
    'Fixed asset': 'inv-cat-tab-FixedAsset',
    'ALL': 'inv-cat-tab-ALL'
  };

  categories.forEach(c => {
    const el = document.getElementById(tabIdMap[c]);
    if (el) {
      if (c === cat) {
        el.className = 'px-3.5 py-2 text-xs font-bold rounded-lg transition flex items-center gap-2 bg-amber-500 text-gray-950 shadow-md';
      } else {
        el.className = 'px-3.5 py-2 text-xs font-semibold rounded-lg transition flex items-center gap-2 glass-card text-gray-300 hover:text-white';
      }
    }
  });

  renderInventoryTable(inventoryItemsList);
}

function getCategoryBadgeClass(category) {
  const c = (category || 'Stock').toLowerCase();
  if (c.includes('fixed')) return 'bg-purple-500/20 text-purple-300 border border-purple-500/30';
  if (c.includes('consumable')) return 'bg-sky-500/20 text-sky-300 border border-sky-500/30';
  if (c.includes('small') || c.includes('equipment')) return 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30';
  return 'bg-amber-500/20 text-amber-300 border border-amber-500/30';
}

function switchInventorySubTab(sub) {
  currentInventorySubTab = sub;
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  if (sub === 'history' && !isManagerOrAdmin) {
    showToast('Only Managers and Admins can view stock transaction history.', 'error');
    sub = 'stock';
    currentInventorySubTab = 'stock';
  }

  const stockView = document.getElementById('inventory-view-stock');
  const histView = document.getElementById('inventory-view-history');
  const btnStock = document.getElementById('inv-subtab-stock');
  const btnHist = document.getElementById('inv-subtab-history');

  if (sub === 'stock') {
    if (stockView) stockView.classList.remove('hidden');
    if (histView) histView.classList.add('hidden');
    if (btnStock) {
      btnStock.className = 'px-3 py-1.5 text-xs rounded-lg bg-amber-500 hover:bg-amber-400 text-gray-950 font-bold';
    }
    if (btnHist) {
      btnHist.className = 'px-3 py-1.5 text-xs rounded-lg glass-card text-gray-300 hover:text-white font-semibold';
    }
  } else {
    if (stockView) stockView.classList.add('hidden');
    if (histView) histView.classList.remove('hidden');
    if (btnStock) {
      btnStock.className = 'px-3 py-1.5 text-xs rounded-lg glass-card text-gray-300 hover:text-white font-semibold';
    }
    if (btnHist) {
      btnHist.className = 'px-3 py-1.5 text-xs rounded-lg bg-amber-500 hover:bg-amber-400 text-gray-950 font-bold';
    }
    populateHistoryFilters();
    loadInventoryTransactions();
  }
}

function isItemCountableUnit(unit, volUnit) {
  const u = (unit || '').toLowerCase().trim();
  const vu = (volUnit || '').toLowerCase().trim();
  const countableSet = ['piece', 'pieces', 'pcs', 'na', 'none', 'n/a', 'no volume'];
  return countableSet.includes(u) || countableSet.includes(vu);
}

function renderInventoryTable(items) {
  inventoryItemsList = items || [];
  const tbody = document.getElementById('inventoryTableBody');
  const lowStockBanner = document.getElementById('lowStockBanner');
  const btnAdd = document.getElementById('btnAddRawMaterial');
  const btnHist = document.getElementById('inv-subtab-history');
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');

  // Enforce UI permissions: Staff cannot create raw materials directly or view history
  if (btnAdd) {
    if (isManagerOrAdmin) btnAdd.classList.remove('hidden');
    else btnAdd.classList.add('hidden');
  }
  if (btnHist) {
    if (isManagerOrAdmin) btnHist.classList.remove('hidden');
    else btnHist.classList.add('hidden');
  }

  // Update counts on tabs
  const countStock = inventoryItemsList.filter(i => (i.itemCategory || 'Stock').toLowerCase() === 'stock').length;
  const countConsumable = inventoryItemsList.filter(i => (i.itemCategory || '').toLowerCase() === 'consumable').length;
  const countSmallEq = inventoryItemsList.filter(i => (i.itemCategory || '').toLowerCase() === 'small equipment').length;
  const countFixedAsset = inventoryItemsList.filter(i => (i.itemCategory || '').toLowerCase() === 'fixed asset').length;

  const countStockEl = document.getElementById('inv-count-Stock');
  const countConsumableEl = document.getElementById('inv-count-Consumable');
  const countSmallEqEl = document.getElementById('inv-count-SmallEquipment');
  const countFixedAssetEl = document.getElementById('inv-count-FixedAsset');
  const countAllEl = document.getElementById('inv-count-ALL');

  if (countStockEl) countStockEl.textContent = countStock;
  if (countConsumableEl) countConsumableEl.textContent = countConsumable;
  if (countSmallEqEl) countSmallEqEl.textContent = countSmallEq;
  if (countFixedAssetEl) countFixedAssetEl.textContent = countFixedAsset;
  if (countAllEl) countAllEl.textContent = inventoryItemsList.length;

  renderLowStockBanner(inventoryItemsList.filter(i => i.lowStock));
  renderInventoryRows();
}

/** One-line low-stock summary; the item list is collapsed by default and scrolls inside its own panel. */
function renderLowStockBanner(lowItems) {
  const banner = document.getElementById('lowStockBanner');
  if (!banner) return;
  if (lowItems.length === 0) {
    banner.classList.add('hidden');
    inventoryLowOnly = false;
    return;
  }
  banner.classList.remove('hidden');
  document.getElementById('lowStockMessage').textContent =
    `${lowItems.length} item${lowItems.length === 1 ? ' is' : 's are'} low on stock`;
  const list = document.getElementById('lowStockList');
  if (list) {
    list.innerHTML = lowItems.map(i => `
      <button type="button" onclick="focusInventoryItem(${Number(i.id)})" title="Find ${escapeHtml(i.name)} in the table"
        class="px-2 py-0.5 rounded-full bg-rose-500/15 border border-rose-500/30 text-rose-200 hover:bg-rose-500/30 transition max-w-full truncate">
        ${escapeHtml(i.name)} <span class="text-rose-400/80">${escapeHtml(String(i.quantity))}/${escapeHtml(String(i.minQuantity))} ${escapeHtml(i.unit || '')}</span>
      </button>`).join('');
  }
  applyLowStockPanelState();
}

function applyLowStockPanelState() {
  const list = document.getElementById('lowStockList');
  const label = document.getElementById('btnLowStockListLabel');
  const chev = document.getElementById('lowStockListChevron');
  const btn = document.getElementById('btnLowStockList');
  if (list) list.classList.toggle('hidden', !lowStockListOpen);
  if (label) label.textContent = lowStockListOpen ? 'Hide list' : 'View list';
  if (chev) chev.classList.toggle('rotate-180', lowStockListOpen);
  if (btn) btn.setAttribute('aria-expanded', String(lowStockListOpen));
  const onlyBtn = document.getElementById('btnLowStockOnly');
  const onlyLabel = document.getElementById('btnLowStockOnlyLabel');
  if (onlyBtn) {
    onlyBtn.setAttribute('aria-pressed', String(inventoryLowOnly));
    onlyBtn.classList.toggle('bg-rose-500/30', inventoryLowOnly);
    onlyBtn.classList.toggle('text-white', inventoryLowOnly);
  }
  if (onlyLabel) onlyLabel.textContent = inventoryLowOnly ? 'Showing low stock only' : 'Show only low stock';
}

function toggleLowStockList() {
  lowStockListOpen = !lowStockListOpen;
  applyLowStockPanelState();
}

function toggleInventoryLowOnly() {
  inventoryLowOnly = !inventoryLowOnly;
  applyLowStockPanelState();
  renderInventoryRows();
}

function onInventorySearchInput() {
  inventorySearchTerm = (document.getElementById('inventorySearchInput')?.value || '').trim().toLowerCase();
  renderInventoryRows();
}

function clearInventorySearch() {
  const input = document.getElementById('inventorySearchInput');
  if (input) input.value = '';
  inventorySearchTerm = '';
  renderInventoryRows();
  input?.focus();
}

/** Jump from a low-stock chip to that item's row: switch to All Items, search for it and highlight it. */
function focusInventoryItem(id) {
  const item = inventoryItemsList.find(i => i.id === id);
  if (!item) return;
  inventoryLowOnly = false;
  applyLowStockPanelState();
  const input = document.getElementById('inventorySearchInput');
  if (input) input.value = item.name;
  inventorySearchTerm = (item.name || '').trim().toLowerCase();
  if (currentInventoryCategoryFilter !== 'ALL') {
    switchInventoryCategory('ALL'); // re-renders the rows with the new search term
  } else {
    renderInventoryRows();
  }
  document.getElementById('inventoryTableBody')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function inventoryMatchesSearch(i, term) {
  if (!term) return true;
  return [i.name, i.itemCategory || 'Stock', i.supplier, i.unit, i.volumeUnit]
    .some(v => v && String(v).toLowerCase().includes(term));
}

function getInventoryCategoryItems() {
  return currentInventoryCategoryFilter === 'ALL'
    ? inventoryItemsList
    : inventoryItemsList.filter(i => (i.itemCategory || 'Stock').toLowerCase() === currentInventoryCategoryFilter.toLowerCase());
}

function renderInventoryRows() {
  const tbody = document.getElementById('inventoryTableBody');
  if (!tbody) return;
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  const term = inventorySearchTerm;
  const categoryItems = getInventoryCategoryItems();
  const filteredItems = categoryItems.filter(i => (!inventoryLowOnly || i.lowStock) && inventoryMatchesSearch(i, term));

  const clearBtn = document.getElementById('btnClearInventorySearch');
  if (clearBtn) clearBtn.classList.toggle('hidden', !term);
  const countEl = document.getElementById('inventoryResultCount');
  if (countEl) {
    const filtered = Boolean(term) || inventoryLowOnly;
    countEl.textContent = filtered
      ? `Showing ${filteredItems.length} of ${categoryItems.length} item${categoryItems.length === 1 ? '' : 's'}${currentInventoryCategoryFilter === 'ALL' ? '' : ' in ' + currentInventoryCategoryFilter}`
      : '';
  }

  if (filteredItems.length === 0) {
    let hint = '';
    if (term && currentInventoryCategoryFilter !== 'ALL') {
      const elsewhere = inventoryItemsList.filter(i => (!inventoryLowOnly || i.lowStock) && inventoryMatchesSearch(i, term)).length;
      if (elsewhere > 0) {
        hint = `<div class="mt-2"><button type="button" onclick="switchInventoryCategory('ALL')" class="text-amber-400 hover:text-amber-300 underline">${elsewhere} match${elsewhere === 1 ? '' : 'es'} in other categories - search All Items</button></div>`;
      }
    }
    const what = term ? `No items match "${escapeHtml(term)}"` : (inventoryLowOnly ? 'No low stock items here' : `No ${currentInventoryCategoryFilter === 'ALL' ? '' : escapeHtml(currentInventoryCategoryFilter)} items found`);
    tbody.innerHTML = `<tr><td colspan="12" class="text-center py-8 text-gray-500">${what}${hint}</td></tr>`;
    return;
  }

  tbody.innerHTML = filteredItems.map(i => {
    const unitVol = i.unitVolume != null ? i.unitVolume : (i.volume != null ? i.volume : 1);
    const volUnit = i.volumeUnit || i.unit || 'kg';
    const isCountable = isItemCountableUnit(i.unit, volUnit);
    const totalVol = i.totalVolume != null ? i.totalVolume : (isCountable ? (i.quantity || 0) : ((i.quantity || 0) * unitVol));
    const costPerUnit = i.costPerUnit || 0;
    const costPerVol = i.costPerVolume != null ? i.costPerVolume : (isCountable ? costPerUnit : (unitVol > 0 ? (costPerUnit / unitVol) : costPerUnit));

    return `
    <tr class="hover:bg-gray-800/40">
      <td class="p-3 font-semibold text-white">
        ${escapeHtml(i.name)}
        ${i.lowStock ? '<span class="ml-2 px-1.5 py-0.5 rounded text-[9px] font-bold bg-rose-500/20 text-rose-400">LOW</span>' : ''}
      </td>
      <td class="p-3">
        <span class="px-2 py-0.5 rounded text-[10px] font-bold ${getCategoryBadgeClass(i.itemCategory)}">${escapeHtml(i.itemCategory || 'Stock')}</span>
      </td>
      <td class="p-3 font-bold ${i.lowStock ? 'text-rose-400' : 'text-emerald-400'}">${i.quantity} ${escapeHtml(i.unit || '')}</td>
      <td class="p-3 text-center text-amber-300 font-medium">${isCountable ? (volUnit === 'na' ? '-' : `1 ${volUnit}`) : `${unitVol} ${volUnit}/${i.unit}`}</td>
      <td class="p-3 text-center font-bold text-amber-400">${isCountable ? `${i.quantity} ${volUnit === 'na' ? i.unit : volUnit}` : `${totalVol.toLocaleString()} ${volUnit}`}</td>
      <td class="p-3 text-right font-semibold text-white">₹${costPerUnit.toFixed(2)}</td>
      <td class="p-3 text-right font-semibold text-emerald-400">${isCountable ? `₹${costPerUnit.toFixed(2)} / pc` : `₹${costPerVol.toFixed(2)} / ${volUnit}`}</td>
      <td class="p-3 text-center text-gray-400">${i.minQuantity} ${escapeHtml(i.unit || '')}</td>
      <td class="p-3 text-gray-400">${escapeHtml(i.supplier || '-')}</td>
      <td class="p-3 text-center">
        <button onclick="openDecreaseStockModal(${i.id})" class="px-2.5 py-1 rounded bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 border border-rose-500/30 font-semibold text-xs flex items-center gap-1 mx-auto">
          <i class="fa-solid fa-arrow-down text-[10px]"></i>Issue Stock
        </button>
      </td>
      <td class="p-3 text-center">
        <button onclick="notifyManagerLowStock(${Number(i.id)})"
          class="px-2.5 py-1 rounded text-xs font-semibold transition flex items-center justify-center gap-1 mx-auto ${i.lowStock ? 'bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 border border-rose-500/40 shadow-sm' : 'bg-gray-800 hover:bg-gray-700 text-gray-400 border border-gray-700'}"
          title="Notify Manager about low stock for this item">
          <i class="fa-solid fa-triangle-exclamation text-[11px]"></i>
          <span>Alert Mgr</span>
        </button>
      </td>
      <td class="p-3 text-right">
        ${isManagerOrAdmin ? `
          <button onclick="openEditInventoryModal(${i.id})" class="text-amber-400 hover:text-amber-300 mr-2.5" title="Edit Item Details">
            <i class="fa-regular fa-pen-to-square"></i>
          </button>
          <button onclick="deleteInventoryItem(${i.id})" class="text-gray-400 hover:text-rose-400" title="Delete">
            <i class="fa-regular fa-trash-can"></i>
          </button>
        ` : `
          <span class="text-gray-600 text-xs">-</span>
        `}
      </td>
    </tr>
  `}).join('');
}

function openDecreaseStockModal(id) {
  const item = inventoryItemsList.find(i => i.id === id);
  if (!item) return;

  document.getElementById('decreaseStockItemId').value = item.id;
  document.getElementById('decreaseStockItemName').textContent = `${item.name}`;
  document.getElementById('decreaseStockAvailable').textContent = `Available in Stock: ${item.quantity} ${item.unit}`;
  document.getElementById('decreaseStockQty').value = '';
  document.getElementById('decreaseStockQty').max = item.quantity;
  document.getElementById('decreaseStockReason').value = '';
  document.getElementById('decreaseStockError').classList.add('hidden');
  document.getElementById('decreaseStockModal').classList.remove('hidden');
}

function closeDecreaseStockModal() {
  document.getElementById('decreaseStockModal').classList.add('hidden');
}

async function submitDecreaseStock(e) {
  e.preventDefault();
  const id = document.getElementById('decreaseStockItemId').value;
  const qty = parseFloat(document.getElementById('decreaseStockQty').value);
  const reason = document.getElementById('decreaseStockReason').value.trim();
  const errEl = document.getElementById('decreaseStockError');
  errEl.classList.add('hidden');

  if (isNaN(qty) || qty <= 0) {
    errEl.textContent = 'Please enter a valid quantity greater than zero.';
    errEl.classList.remove('hidden');
    return;
  }

  try {
    await apiRequest(`/inventory/${id}/decrease`, {
      method: 'POST',
      body: JSON.stringify({ quantity: qty, reason: reason })
    });
    showToast('Stock issued successfully', 'success');
    closeDecreaseStockModal();
    loadInventoryData();
  } catch (err) {
    errEl.textContent = err.message;
    errEl.classList.remove('hidden');
  }
}

// ─── Inventory Transaction History ──────────────────────────────────────────

function onInvHistPresetChange() {
  const preset = document.getElementById('invHistPreset').value;
  const customDiv = document.getElementById('invHistCustomDates');
  if (preset === 'custom') {
    customDiv.classList.remove('hidden');
  } else {
    customDiv.classList.add('hidden');
  }
}

function populateHistoryFilters() {
  const prodSelect = document.getElementById('invHistProductFilter');
  if (prodSelect) {
    const curVal = prodSelect.value;
    prodSelect.innerHTML = '<option value="">All Products</option>' +
      inventoryItemsList.map(i => `<option value="${i.id}" ${curVal == i.id ? 'selected' : ''}>${escapeHtml(i.name)}</option>`).join('');
  }
  const supSelect = document.getElementById('invHistSupplierFilter');
  if (supSelect && typeof allSuppliers !== 'undefined') {
    const curVal = supSelect.value;
    supSelect.innerHTML = '<option value="">All Suppliers</option>' +
      allSuppliers.map(s => `<option value="${s.id}" ${curVal == s.id ? 'selected' : ''}>${s.name}</option>`).join('');
  }
}

function applyInventoryHistoryFilters() {
  const preset = document.getElementById('invHistPreset').value;
  let startDate = '';
  let endDate = '';
  const now = new Date();

  if (preset === 'today') {
    startDate = now.toISOString().split('T')[0];
    endDate = startDate;
  } else if (preset === 'yesterday') {
    const y = new Date();
    y.setDate(y.getDate() - 1);
    startDate = y.toISOString().split('T')[0];
    endDate = startDate;
  } else if (preset === 'this_week') {
    const day = now.getDay();
    const diff = now.getDate() - day + (day === 0 ? -6 : 1); // Monday
    const monday = new Date(now.setDate(diff));
    startDate = monday.toISOString().split('T')[0];
    endDate = new Date().toISOString().split('T')[0];
  } else if (preset === 'this_month') {
    const mStart = new Date(now.getFullYear(), now.getMonth(), 1);
    startDate = mStart.toISOString().split('T')[0];
    endDate = new Date().toISOString().split('T')[0];
  } else if (preset === 'custom') {
    startDate = document.getElementById('invHistFromDate').value;
    endDate = document.getElementById('invHistToDate').value;
  }

  const type = document.getElementById('invHistTypeFilter').value;
  const itemId = document.getElementById('invHistProductFilter').value;
  const supplierId = document.getElementById('invHistSupplierFilter').value;

  loadInventoryTransactions({ startDate, endDate, transactionType: type, itemId, supplierId });
}

async function loadInventoryTransactions(filters = {}) {
  const tbody = document.getElementById('inventoryHistoryTableBody');
  const countEl = document.getElementById('invHistCount');
  tbody.innerHTML = `<tr><td colspan="9" class="text-center py-6 text-gray-500"><i class="fa-solid fa-spinner fa-spin mr-2"></i>Loading stock history...</td></tr>`;

  const query = new URLSearchParams();
  if (filters.startDate) query.append('startDate', filters.startDate);
  if (filters.endDate) query.append('endDate', filters.endDate);
  if (filters.transactionType) query.append('transactionType', filters.transactionType);
  if (filters.itemId) query.append('itemId', filters.itemId);
  if (filters.supplierId) query.append('supplierId', filters.supplierId);

  try {
    const txns = await apiRequest(`/inventory/transactions?${query.toString()}`);
    countEl.textContent = `${txns.length} records found`;
    if (!txns || txns.length === 0) {
      tbody.innerHTML = `<tr><td colspan="9" class="text-center py-8 text-gray-500">No stock movement transactions found for selected filters</td></tr>`;
      return;
    }

    tbody.innerHTML = txns.map(t => {
      let typeBadge = '';
      if (t.transactionType === 'STOCK_IN') {
        typeBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">STOCK IN</span>`;
      } else if (t.transactionType === 'STOCK_OUT') {
        typeBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-rose-500/20 text-rose-400 border border-rose-500/30">STOCK OUT</span>`;
      } else {
        typeBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-blue-500/20 text-blue-400 border border-blue-500/30">${t.transactionType}</span>`;
      }

      const dateStr = t.createdAt ? new Date(t.createdAt).toLocaleString('en-IN', {
        dateStyle: 'short', timeStyle: 'short'
      }) : '-';

      return `
        <tr class="hover:bg-gray-800/40">
          <td class="p-3 whitespace-nowrap text-gray-400">${dateStr}</td>
          <td class="p-3 font-semibold text-white">${t.itemName || '-'}</td>
          <td class="p-3">${typeBadge}</td>
          <td class="p-3 font-bold ${t.transactionType === 'STOCK_IN' ? 'text-emerald-400' : 'text-rose-400'}">
            ${t.transactionType === 'STOCK_IN' ? '+' : '-'}${t.quantity} ${t.unit || 'pcs'}
          </td>
          <td class="p-3 text-gray-400 text-xs">
            <span class="text-gray-500">${t.previousStock}</span> → <span class="font-bold text-white">${t.newStock}</span>
          </td>
          <td class="p-3">
            <span class="text-white font-medium">${t.userName || 'SYSTEM'}</span>
            ${t.userRole ? `<span class="ml-1 text-[10px] text-gray-400">(${t.userRole})</span>` : ''}
          </td>
          <td class="p-3 text-gray-300">
            ${t.supplierName ? `<div class="font-medium text-amber-300">${t.supplierName}</div>` : ''}
            ${t.invoiceReference ? `<div class="text-[10px] text-gray-400">Ref: ${t.invoiceReference}</div>` : (t.supplierName ? '' : '-')}
          </td>
          <td class="p-3 text-gray-300">${t.unitPrice ? `₹${t.unitPrice.toFixed(2)}` : '-'}</td>
          <td class="p-3 text-gray-400 text-xs max-w-xs truncate" title="${t.notes || ''}">${t.notes || '-'}</td>
        </tr>
      `;
    }).join('');
  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="9" class="text-center py-6 text-rose-400">${err.message}</td></tr>`;
  }
}

function updateInvModalCalculations() {
  const qty = parseFloat(document.getElementById('invQuantity')?.value) || 0;
  const unitVol = parseFloat(document.getElementById('invUnitVolume')?.value) || 1;
  const unit = document.getElementById('invUnit')?.value || 'packet';
  const volUnit = document.getElementById('invVolumeUnit')?.value || 'kg';
  const cost = parseFloat(document.getElementById('invCostPerUnit')?.value) || 0;

  const isCountable = isItemCountableUnit(unit, volUnit);
  const totalVol = isCountable ? qty : (Math.round(qty * unitVol * 1000) / 1000);
  const ratePerVol = isCountable ? cost : (unitVol > 0 ? (cost / unitVol) : cost);

  const totalVolEl = document.getElementById('invCalcTotalVol');
  const ratePerVolEl = document.getElementById('invCalcRatePerVol');
  if (totalVolEl) {
    totalVolEl.textContent = isCountable
      ? `${qty.toLocaleString()} ${volUnit === 'na' ? unit : volUnit}`
      : `${totalVol.toLocaleString()} ${volUnit}`;
  }
  if (ratePerVolEl) {
    ratePerVolEl.textContent = isCountable
      ? `₹${cost.toFixed(2)} / pc`
      : `₹${ratePerVol.toFixed(2)} / ${volUnit}`;
  }
}

function onInvUnitChange() {
  const unitEl = document.getElementById('invUnit');
  const volEl = document.getElementById('invUnitVolume');
  const volUnitEl = document.getElementById('invVolumeUnit');
  if (!unitEl || !volUnitEl) return;
  const val = unitEl.value.toLowerCase();
  if (['piece', 'pieces'].includes(val)) {
    if (volEl) volEl.value = '1';
    volUnitEl.value = 'pieces';
  } else if (['meter', 'cm', 'mm', 'inch'].includes(val)) {
    volUnitEl.value = val;
  }
  updateInvModalCalculations();
}

function openEditInventoryModal(id) {
  const item = inventoryItemsList.find(i => i.id === id);
  if (!item) return;

  document.getElementById('invId').value = item.id;
  document.getElementById('invName').value = item.name || '';
  document.getElementById('invQuantity').value = item.quantity != null ? item.quantity : 0;
  const invUnitEl = document.getElementById('invUnit');
  const rawUnit = (item.unit || 'packet').toLowerCase();
  if (invUnitEl) {
    if (!Array.from(invUnitEl.options).some(o => o.value.toLowerCase() === rawUnit)) {
      const opt = document.createElement('option');
      opt.value = item.unit;
      opt.textContent = item.unit;
      invUnitEl.appendChild(opt);
    }
    invUnitEl.value = rawUnit;
  }

  document.getElementById('invUnitVolume').value = item.unitVolume != null ? item.unitVolume : (item.volume != null ? item.volume : 1);

  const invVolUnitEl = document.getElementById('invVolumeUnit');
  const rawVolUnit = (item.volumeUnit || item.unit || 'kg').toLowerCase();
  if (invVolUnitEl) {
    if (!Array.from(invVolUnitEl.options).some(o => o.value.toLowerCase() === rawVolUnit)) {
      const opt = document.createElement('option');
      opt.value = item.volumeUnit || item.unit;
      opt.textContent = item.volumeUnit || item.unit;
      invVolUnitEl.appendChild(opt);
    }
    invVolUnitEl.value = rawVolUnit;
  }
  document.getElementById('invMinQuantity').value = item.minQuantity != null ? item.minQuantity : 0;
  document.getElementById('invCostPerUnit').value = item.costPerUnit != null ? item.costPerUnit : 0;
  document.getElementById('invSupplier').value = item.supplier || '';
  const invCatEl = document.getElementById('invCategory');
  if (invCatEl) invCatEl.value = item.itemCategory || 'Stock';

  updateInvModalCalculations();

  const title = document.getElementById('invModalTitle');
  if (title) title.textContent = 'Edit Raw Material / Stock';
  document.getElementById('inventoryModal').classList.remove('hidden');
}

function openAddInventoryModal() {
  document.getElementById('invId').value = '';
  document.getElementById('invName').value = '';
  const invCatEl = document.getElementById('invCategory');
  if (invCatEl) invCatEl.value = (currentInventoryCategoryFilter !== 'ALL' ? currentInventoryCategoryFilter : 'Stock');
  document.getElementById('invQuantity').value = '';
  document.getElementById('invUnit').value = 'packet';
  document.getElementById('invUnitVolume').value = '1';
  document.getElementById('invVolumeUnit').value = 'kg';
  document.getElementById('invMinQuantity').value = '';
  document.getElementById('invCostPerUnit').value = '';
  document.getElementById('invSupplier').value = '';

  updateInvModalCalculations();

  const title = document.getElementById('invModalTitle');
  if (title) title.textContent = 'Add Raw Material / Stock';
  document.getElementById('inventoryModal').classList.remove('hidden');
}

async function saveInventoryItem(e) {
  e.preventDefault();
  const invId = document.getElementById('invId').value;
  const unit = document.getElementById('invUnit').value.trim() || 'packet';
  const volUnit = document.getElementById('invVolumeUnit').value || 'kg';
  const isCountable = isItemCountableUnit(unit, volUnit);
  const unitVol = parseFloat(document.getElementById('invUnitVolume').value) || (isCountable ? 1 : 1);
  const qty = parseFloat(document.getElementById('invQuantity').value) || 0;
  const costPerUnit = parseFloat(document.getElementById('invCostPerUnit').value) || 0;

  const payload = {
    name: document.getElementById('invName').value.trim(),
    quantity: qty,
    unit: unit,
    itemCategory: document.getElementById('invCategory')?.value || 'Stock',
    unitVolume: isCountable ? 1 : unitVol,
    volume: isCountable ? 1 : unitVol,
    volumeUnit: volUnit,
    totalVolume: isCountable ? qty : Math.round(qty * unitVol * 1000) / 1000,
    costPerVolume: isCountable ? costPerUnit : (unitVol > 0 ? (costPerUnit / unitVol) : costPerUnit),
    minQuantity: parseFloat(document.getElementById('invMinQuantity').value) || 0,
    costPerUnit: costPerUnit,
    supplier: document.getElementById('invSupplier').value.trim(),
    active: true
  };

  try {
    if (invId) {
      await apiRequest(`/inventory/${invId}`, { method: 'PUT', body: JSON.stringify(payload) });
      showToast('Inventory item updated successfully', 'success');
    } else {
      await apiRequest('/inventory', { method: 'POST', body: JSON.stringify(payload) });
      showToast('Inventory item added successfully', 'success');
    }
    closeModal('inventoryModal');
    loadInventoryData();
  } catch (err) {
    showToast('Failed to save inventory: ' + err.message, 'error');
  }
}

async function adjustStock(id, change) {
  try {
    await apiRequest(`/inventory/${id}/stock`, {
      method: 'PATCH',
      body: JSON.stringify({ change })
    });
    loadInventoryData();
  } catch (err) {
    showToast('Failed to adjust stock: ' + err.message, 'error');
  }
}

async function deleteInventoryItem(id) {
  if (!confirm('Remove this inventory item?')) return;
  try {
    await apiRequest(`/inventory/${id}`, { method: 'DELETE' });
    showToast('Item deleted', 'success');
    loadInventoryData();
  } catch (err) {
    showToast('Failed to delete item: ' + err.message, 'error');
  }
}

// ============================================================
// HELPERS & MODAL UTILITIES
// ============================================================
function closeModal(id) {
  const el = document.getElementById(id);
  if (el) el.classList.add('hidden');
}

let toastDismissTimer = null;

function dismissToast() {
  if (toastDismissTimer) {
    clearTimeout(toastDismissTimer);
    toastDismissTimer = null;
  }
  const toast = document.getElementById('toast');
  if (!toast) return;
  toast.classList.add('-translate-y-12', 'opacity-0', 'pointer-events-none');
  toast.classList.remove('translate-y-0', 'opacity-100', 'pointer-events-auto');
}

function showToast(msg, type = 'success') {
  const toast = document.getElementById('toast');
  const msgEl = document.getElementById('toastMsg');
  const icon = document.getElementById('toastIcon');
  if (!toast || !msgEl || !icon) return;

  if (toastDismissTimer) {
    clearTimeout(toastDismissTimer);
    toastDismissTimer = null;
  }

  msgEl.textContent = msg;
  let borderClass = 'border-amber-500/50 shadow-amber-950/40';
  let iconClass = 'fa-solid fa-circle-check text-emerald-400 text-base shrink-0';

  if (type === 'error') {
    iconClass = 'fa-solid fa-circle-exclamation text-rose-400 text-base shrink-0';
    borderClass = 'border-rose-500/60 shadow-rose-950/40';
  } else if (type === 'warning') {
    iconClass = 'fa-solid fa-triangle-exclamation text-amber-400 text-base shrink-0';
    borderClass = 'border-amber-500/60 shadow-amber-950/40';
  } else if (type === 'info') {
    iconClass = 'fa-solid fa-circle-info text-cyan-400 text-base shrink-0';
    borderClass = 'border-cyan-500/60 shadow-cyan-950/40';
  } else {
    iconClass = 'fa-solid fa-circle-check text-emerald-400 text-base shrink-0';
    borderClass = 'border-emerald-500/60 shadow-emerald-950/40';
  }

  icon.className = iconClass;
  toast.className = `fixed top-5 right-5 sm:top-6 sm:right-6 z-[80] transition-all duration-300 glass-panel px-4 py-3 rounded-2xl flex items-center justify-between gap-3 text-xs sm:text-sm border ${borderClass} shadow-2xl backdrop-blur-md cursor-pointer select-none max-w-[90vw] sm:max-w-md`;

  // Animate in from top (never blocks bottom action buttons)
  toast.classList.remove('-translate-y-12', 'opacity-0', 'pointer-events-none');
  toast.classList.add('translate-y-0', 'opacity-100', 'pointer-events-auto');

  toastDismissTimer = setTimeout(() => {
    dismissToast();
  }, 2200);
}

// Global hotkeys for rapid POS operation
window.addEventListener('keydown', (e) => {
  if (e.key === '/' && activeTab === 'tab-pos') {
    const activeEl = document.activeElement;
    const isEditing = activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA' || activeEl.isContentEditable);
    if (!isEditing) {
      e.preventDefault();
      const sInput = document.getElementById('posSearchInput');
      if (sInput) {
        sInput.focus();
        sInput.select();
      }
    }
  } else if (e.key === 'Escape' && document.activeElement?.id === 'posSearchInput') {
    clearPosSearch();
    document.activeElement.blur();
  }
});

function setupEventListeners() {
  document.getElementById('loginForm')?.addEventListener('submit', handleLogin);
  document.getElementById('dishForm')?.addEventListener('submit', saveDish);
  document.getElementById('categoryForm')?.addEventListener('submit', saveCategory);
  document.getElementById('inventoryForm')?.addEventListener('submit', saveInventoryItem);
  document.getElementById('staffForm')?.addEventListener('submit', saveStaff);
  document.getElementById('salaryForm')?.addEventListener('submit', saveSalary);
  document.getElementById('editBillForm')?.addEventListener('submit', handleEditBillSubmit);
  const expForm = document.getElementById('expenseForm');
  if (expForm && !expForm.dataset.bound) {
    expForm.dataset.bound = 'true';
    expForm.addEventListener('submit', saveExpense);
  }
  const expTplForm = document.getElementById('expenseTemplateForm');
  if (expTplForm && !expTplForm.dataset.bound) {
    expTplForm.dataset.bound = 'true';
    expTplForm.addEventListener('submit', saveExpenseTemplate);
  }
  document.getElementById('leaveForm')?.addEventListener('submit', saveLeaveApplication);
  document.getElementById('reviewLeaveForm')?.addEventListener('submit', saveReviewLeave);
  document.getElementById('createUserForm')?.addEventListener('submit', saveCreateUser);
  document.getElementById('userPermissionsForm')?.addEventListener('submit', saveUserPermissions);
  document.getElementById('resetPasswordForm')?.addEventListener('submit', saveResetPassword);
  document.getElementById('changePasswordForm')?.addEventListener('submit', saveChangeOwnPassword);
  document.getElementById('cartCustomer')?.addEventListener('input', () => {
    isCartDirty = hasOrderChanges();
    updateOrderActionButtonsState();
  });
  document.getElementById('cartOrderNotes')?.addEventListener('input', () => {
    isCartDirty = hasOrderChanges();
    updateOrderActionButtonsState();
  });
}

// ============================================================
// SELF PASSWORD CHANGE & PASSWORD POLICY (Available to all users / Forced on First Login)
// ============================================================
let isPasswordChangeForced = false;

function openChangePasswordModal(forced = false) {
  if (!currentUser) return;
  isPasswordChangeForced = Boolean(forced);

  const curPassEl = document.getElementById('cpCurrentPassword');
  const newPassEl = document.getElementById('cpNewPassword');
  const confirmPassEl = document.getElementById('cpConfirmPassword');
  const errEl = document.getElementById('cpError');
  const userLabel = document.getElementById('changePwdUserLabel');
  const forcedNotice = document.getElementById('cpForcedNotice');
  const closeBtn = document.getElementById('cpCloseBtn');
  const modalTitle = document.getElementById('cpModalTitle');
  const submitBtnText = document.getElementById('cpSubmitBtnText');

  if (!forced && curPassEl) {
    curPassEl.value = '';
  }
  if (newPassEl) newPassEl.value = '';
  if (confirmPassEl) confirmPassEl.value = '';
  if (errEl) {
    errEl.classList.add('hidden');
    errEl.textContent = '';
  }

  if (forcedNotice) {
    if (forced) forcedNotice.classList.remove('hidden');
    else forcedNotice.classList.add('hidden');
  }

  if (closeBtn) {
    if (forced) closeBtn.classList.add('hidden');
    else closeBtn.classList.remove('hidden');
  }

  if (modalTitle) {
    modalTitle.textContent = forced ? 'Set New Secure Password' : 'Change Password';
  }

  if (submitBtnText) {
    submitBtnText.textContent = forced ? 'Activate Account & Continue' : 'Update Password';
  }

  if (userLabel) {
    userLabel.innerHTML = `Account: <span class="text-white font-bold">${escapeHtml(currentUser.username)}</span> (${escapeHtml(currentUser.role)})`;
  }

  validatePasswordPolicyInputs();
  const modal = document.getElementById('changePasswordModal');
  if (modal) modal.classList.remove('hidden');
}

function validatePasswordPolicyInputs() {
  const newPass = document.getElementById('cpNewPassword')?.value || '';
  const confirmPass = document.getElementById('cpConfirmPassword')?.value || '';

  const hasLen = newPass.length >= 8;
  const hasUpper = /[A-Z]/.test(newPass);
  const hasLower = /[a-z]/.test(newPass);
  const hasDigit = /[0-9]/.test(newPass);
  const hasSpecial = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?`~]/.test(newPass);

  updatePolicyBadge('ppRuleLen', hasLen, '8+ characters');
  updatePolicyBadge('ppRuleUpper', hasUpper, 'Uppercase letter (A-Z)');
  updatePolicyBadge('ppRuleLower', hasLower, 'Lowercase letter (a-z)');
  updatePolicyBadge('ppRuleDigit', hasDigit, 'Number (0-9)');
  updatePolicyBadge('ppRuleSpecial', hasSpecial, 'Special char (!@#$%^&* etc.)');

  const matchEl = document.getElementById('cpMatchFeedback');
  if (matchEl) {
    if (!confirmPass) {
      matchEl.classList.add('hidden');
    } else if (newPass === confirmPass) {
      matchEl.textContent = '✓ Passwords match';
      matchEl.className = 'text-[11px] text-emerald-400 font-semibold mt-1 block';
    } else {
      matchEl.textContent = '✗ Passwords do not match';
      matchEl.className = 'text-[11px] text-rose-400 font-semibold mt-1 block';
    }
  }

  return hasLen && hasUpper && hasLower && hasDigit && hasSpecial && (newPass === confirmPass);
}

function updatePolicyBadge(elementId, passed, label) {
  const el = document.getElementById(elementId);
  if (!el) return;
  if (passed) {
    el.innerHTML = `<i class="fa-solid fa-circle-check text-[11px] text-emerald-400"></i><span class="text-emerald-300 font-semibold">${label}</span>`;
  } else {
    el.innerHTML = `<i class="fa-solid fa-circle text-[7px] text-gray-600"></i><span class="text-gray-400">${label}</span>`;
  }
}

async function submitChangePassword(e) {
  if (e) e.preventDefault();
  const currentPassword = document.getElementById('cpCurrentPassword')?.value || '';
  const newPassword = document.getElementById('cpNewPassword')?.value || '';
  const confirmPassword = document.getElementById('cpConfirmPassword')?.value || '';
  const errEl = document.getElementById('cpError');

  if (errEl) {
    errEl.classList.add('hidden');
    errEl.textContent = '';
  }

  if (!currentPassword) {
    if (errEl) {
      errEl.textContent = 'Please enter your current or temporary password.';
      errEl.classList.remove('hidden');
    }
    return;
  }

  if (newPassword.length < 8) {
    if (errEl) {
      errEl.textContent = 'Password must be at least 8 characters long.';
      errEl.classList.remove('hidden');
    }
    return;
  }
  if (!/[A-Z]/.test(newPassword)) {
    if (errEl) {
      errEl.textContent = 'Password must contain at least one uppercase letter (A-Z).';
      errEl.classList.remove('hidden');
    }
    return;
  }
  if (!/[a-z]/.test(newPassword)) {
    if (errEl) {
      errEl.textContent = 'Password must contain at least one lowercase letter (a-z).';
      errEl.classList.remove('hidden');
    }
    return;
  }
  if (!/[0-9]/.test(newPassword)) {
    if (errEl) {
      errEl.textContent = 'Password must contain at least one digit (0-9).';
      errEl.classList.remove('hidden');
    }
    return;
  }
  if (!/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?`~]/.test(newPassword)) {
    if (errEl) {
      errEl.textContent = 'Password must contain at least one special character (!@#$%^&* etc.).';
      errEl.classList.remove('hidden');
    }
    return;
  }
  if (newPassword !== confirmPassword) {
    if (errEl) {
      errEl.textContent = 'New passwords do not match.';
      errEl.classList.remove('hidden');
    }
    return;
  }
  if (currentPassword === newPassword) {
    if (errEl) {
      errEl.textContent = 'New password cannot be the same as your current password.';
      errEl.classList.remove('hidden');
    }
    return;
  }

  try {
    const res = await apiRequest('/users/me/change-password', {
      method: 'PATCH',
      body: JSON.stringify({ currentPassword, newPassword })
    });

    if (currentUser) {
      currentUser.mustChangePassword = false;
      localStorage.setItem('neram_user', JSON.stringify(currentUser));
    }

    closeModal('changePasswordModal');
    showToast(res.message || 'Password changed successfully! Welcome to NERAM POS.', 'success');
    applyUserSession();
  } catch (err) {
    if (errEl) {
      errEl.textContent = err.message || 'Failed to change password.';
      errEl.classList.remove('hidden');
    }
  }
}

const saveChangeOwnPassword = submitChangePassword;

// ============================================================
// CASHIER SHIFT & DRAWER RECONCILIATION (Feature 1)
// ============================================================
let currentOpenShift = null;
let shiftModuleSettings = { enabled: true };

async function updateShiftHeaderIndicator() {
  const desktopBtn = document.getElementById('headerShiftStatusBtn');
  const mobileBtn = document.getElementById('headerMobileShiftBtn');
  const dot = document.getElementById('headerShiftDot');
  const label = document.getElementById('headerShiftLabel');

  // Employee does not need shift - strictly for Manager and Admin
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  if (!isManagerOrAdmin) {
    if (desktopBtn) desktopBtn.classList.add('hidden');
    if (mobileBtn) mobileBtn.classList.add('hidden');
    return;
  }

  try {
    const settings = await apiRequest('/shifts/settings');
    shiftModuleSettings = settings;

    // Check if shift module is disabled by admin
    if (settings && settings.enabled === false) {
      const isAdmin = currentUser && currentUser.role === 'ADMIN';
      if (!isAdmin) {
        // Disappear completely from Manager/Staff until Admin re-enables it
        if (desktopBtn) desktopBtn.classList.add('hidden');
        if (mobileBtn) mobileBtn.classList.add('hidden');
        return;
      } else {
        // Only visible to ADMIN so Admin can review and re-enable it
        if (desktopBtn) desktopBtn.classList.remove('hidden');
        if (mobileBtn) mobileBtn.classList.remove('hidden');
        if (dot) dot.className = 'w-2 h-2 rounded-full bg-gray-600';
        if (label) label.textContent = 'Shift (Disabled)';
        return;
      }
    }

    // Shift is enabled
    if (desktopBtn) desktopBtn.classList.remove('hidden');
    if (mobileBtn) mobileBtn.classList.remove('hidden');

    const shift = await apiRequest('/shifts/current');
    currentOpenShift = shift;
    if (dot) dot.className = 'w-2 h-2 rounded-full bg-emerald-400 animate-pulse';
    if (label) label.textContent = shift.cashierName ? `Shift: ${shift.cashierName}` : `Shift #${shift.id} (Open)`;
  } catch (e) {
    currentOpenShift = null;
    const needsShiftCleanup = (e?.message || '').includes('More than one shift is open');
    if (dot) dot.className = `w-2 h-2 rounded-full ${needsShiftCleanup ? 'bg-rose-400' : 'bg-gray-500'}`;
    if (label) label.textContent = needsShiftCleanup ? 'Multiple Shifts Open' : 'Shift Closed';
  }
}

async function openCashierShiftModal() {
  const modal = document.getElementById('cashierShiftModal');
  if (!modal) return;

  // Shift is strictly for Manager & Admin
  const isManagerOrAdmin = currentUser && (currentUser.role === 'ADMIN' || currentUser.role === 'MANAGER');
  if (!isManagerOrAdmin) {
    showToast('Shift management is only accessible to Managers and Admins.', 'warning');
    modal.classList.add('hidden');
    return;
  }

  // If disabled by Admin, reject access for all other users
  if (shiftModuleSettings && shiftModuleSettings.enabled === false && (!currentUser || currentUser.role !== 'ADMIN')) {
    showToast('Cashier Shift module has been disabled by Administrator.', 'warning');
    modal.classList.add('hidden');
    return;
  }

  modal.classList.remove('hidden');

  // If user is Admin, render the Admin Module Control Switch
  const adminCard = document.getElementById('shiftAdminControlCard');
  if (adminCard) {
    if (currentUser && currentUser.role === 'ADMIN') {
      adminCard.classList.remove('hidden');
      try {
        const settings = await apiRequest('/shifts/settings');
        shiftModuleSettings = settings;
        const toggle = document.getElementById('shiftModuleToggle');
        const statusLabel = document.getElementById('shiftSettingStatusLabel');
        if (toggle) toggle.checked = !!settings.enabled;
        if (statusLabel) {
          statusLabel.textContent = settings.enabled ? 'ENABLED' : 'DISABLED';
          statusLabel.className = settings.enabled ? 'text-xs font-bold text-emerald-400' : 'text-xs font-bold text-rose-400';
        }
      } catch (err) {
        console.error('Failed to load shift settings:', err);
      }
    } else {
      adminCard.classList.add('hidden');
    }
  }

  // Switch to current shift tab by default
  switchShiftSubTab('current');
}

function closeCashierShiftModal() {
  const modal = document.getElementById('cashierShiftModal');
  if (modal) modal.classList.add('hidden');
}

async function toggleShiftModule(enabled) {
  try {
    const updated = await apiRequest('/shifts/settings', {
      method: 'PUT',
      body: JSON.stringify({ enabled })
    });
    shiftModuleSettings = updated;
    const statusLabel = document.getElementById('shiftSettingStatusLabel');
    if (statusLabel) {
      statusLabel.textContent = updated.enabled ? 'ENABLED' : 'DISABLED';
      statusLabel.className = updated.enabled ? 'text-xs font-bold text-emerald-400' : 'text-xs font-bold text-rose-400';
    }
    showToast(`Cashier Shift feature has been ${updated.enabled ? 'ENABLED' : 'DISABLED'}`, 'success');
    await updateShiftHeaderIndicator();
  } catch (err) {
    showToast('Failed to update shift feature status: ' + err.message, 'error');
    const toggle = document.getElementById('shiftModuleToggle');
    if (toggle) toggle.checked = !enabled;
  }
}

function switchShiftSubTab(tab) {
  const btnCurrent = document.getElementById('shiftSubTabCurrent');
  const btnHistory = document.getElementById('shiftSubTabHistory');
  const contentCurrent = document.getElementById('shiftModalContent');
  const contentHistory = document.getElementById('shiftHistoryContent');

  if (tab === 'current') {
    if (btnCurrent) btnCurrent.className = 'px-3.5 py-1.5 rounded-lg text-xs font-bold bg-amber-500/20 text-amber-300 border border-amber-500/30 transition flex items-center gap-1.5';
    if (btnHistory) btnHistory.className = 'px-3.5 py-1.5 rounded-lg text-xs font-bold bg-gray-900 text-gray-400 hover:text-gray-200 border border-gray-800 transition flex items-center gap-1.5';
    if (contentCurrent) contentCurrent.classList.remove('hidden');
    if (contentHistory) contentHistory.classList.add('hidden');
    loadCashierShiftData();
  } else {
    if (btnHistory) btnHistory.className = 'px-3.5 py-1.5 rounded-lg text-xs font-bold bg-amber-500/20 text-amber-300 border border-amber-500/30 transition flex items-center gap-1.5';
    if (btnCurrent) btnCurrent.className = 'px-3.5 py-1.5 rounded-lg text-xs font-bold bg-gray-900 text-gray-400 hover:text-gray-200 border border-gray-800 transition flex items-center gap-1.5';
    if (contentHistory) contentHistory.classList.remove('hidden');
    if (contentCurrent) contentCurrent.classList.add('hidden');
    loadShiftHistoryData();
  }
}

