// Re-render dishes grid on orientation/resize so mobile list vs desktop grid stays in sync
let _dishGridResizeTimer = null;
window.addEventListener('resize', () => {
  clearTimeout(_dishGridResizeTimer);
  _dishGridResizeTimer = setTimeout(() => {
    const grid = document.getElementById('posDishesGrid');
    if (grid && grid.children.length > 0) {
      renderDishesGrid();
    }
  }, 200);
});

